-- 01. Algebra -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b201
INSERT INTO topics (id, subject_id, unit_id, name, description, difficulty, display_order, is_active, created_at, updated_at)
SELECT 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b201', '55555555-5555-5555-5555-555555555501',
    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Algebra',
    'Includes expressions, equations, inequalities, and algebraic identities with variable relationships', 'MEDIUM', 29, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE id = 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b201');
INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b301', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b201',
    'Algebra Concepts',
    '<h4><strong>1. CONCEPTUAL FOUNDATION</strong></h4><p>Algebra is the branch of mathematics that uses symbols (usually letters) to represent unknown values and relationships between quantities. It helps us form general rules and solve problems where the exact numbers are not known.</p><p>It provides the foundation for almost all higher-level mathematics — equations, inequalities, functions, progressions, and more.</p><p>Algebra begins with basic arithmetic but generalizes it using variables. Instead of saying “2 + 3 = 5”, algebra says “x + 3 = 5”, meaning “find the number that makes the statement true.”</p><p><strong>Core Idea:</strong> Algebra is about finding values of unknowns (variables) using known relationships.</p><p><br></p><h4><strong>2. CORE THEORY &amp; PRINCIPLES</strong></h4><p><strong>(A) Algebraic Expressions</strong></p><p>An <strong>algebraic expression</strong> consists of constants, variables, and operations (addition, subtraction, multiplication, division, exponents).</p><p>Examples:</p><ol><li>3x + 5y – 7</li><li>4x² – 3x + 9</li></ol><p><strong>Terms:</strong> The parts of an expression separated by + or – signs.</p><p><strong>Coefficient:</strong> The number multiplied by a variable (e.g., in 3x, coefficient = 3).</p><p><strong>Degree:</strong> The highest power of the variable in the expression.</p><p><strong>(B) Algebraic Identities</strong></p><p>Commonly used to simplify and expand expressions:</p><ol><li>(a + b)² = a² + 2ab + b²</li><li>(a – b)² = a² – 2ab + b²</li><li>a² – b² = (a – b)(a + b)</li><li>(a + b + c)² = a² + b² + c² + 2(ab + bc + ca)</li><li>(a + b)³ = a³ + b³ + 3ab(a + b)</li><li>(a – b)³ = a³ – b³ – 3ab(a – b)</li><li>a³ + b³ = (a + b)(a² – ab + b²)</li><li>a³ – b³ = (a – b)(a² + ab + b²)</li></ol><h4><strong>(C) Factorization</strong></h4><p>Breaking an expression into a product of simpler expressions.</p><ol><li>Common factor method</li><li>Grouping method</li><li>Using algebraic identities</li><li>Splitting middle term (for quadratics)</li></ol><p>Example:</p><p>x² + 5x + 6 = (x + 2)(x + 3)</p><p><br></p><h4><strong>(D) Equations</strong></h4><p>An <strong>equation</strong> is a statement showing two expressions are equal.</p><p><strong>Types:</strong></p><ol><li>Linear equation: ax + b = 0</li><li>Quadratic equation: ax² + bx + c = 0</li><li>Simultaneous equations: two or more equations with multiple variables</li></ol><p><strong>Quadratic Equation Formula:</strong></p><p>x = (-b ± √(b² - 4ac)) / 2a</p><p><strong>Nature of Roots:</strong></p><ul><li>If b² – 4ac &gt; 0 → Real &amp; distinct roots</li><li>If b² – 4ac = 0 → Equal roots</li><li>If b² – 4ac &lt; 0 → Imaginary roots</li></ul><p><strong>(E) Laws of Exponents (Indices)</strong></p><ol><li>aᵐ × aⁿ = aᵐ⁺ⁿ</li><li>aᵐ / aⁿ = aᵐ⁻ⁿ</li><li>(aᵐ)ⁿ = aᵐⁿ</li><li>(ab)ⁿ = aⁿbⁿ</li><li>(a/b)ⁿ = aⁿ / bⁿ</li><li>a⁰ = 1</li><li>a⁻ⁿ = 1/aⁿ</li></ol><p><strong>(F) Rational Expressions</strong></p><p>Expressions that can be written as a fraction of two polynomials.</p><p>Simplify by cancelling common factors or using algebraic identities.</p><p><br></p><p><br></p><p><strong>(G) Simplification</strong></p><p>Combine like terms, apply BODMAS rules, and use algebraic identities to reduce to simplest form.</p><p><br></p><p><br></p><h4><strong>3. MAGIC SHORTCUTS</strong></h4><ol><li><strong>Square and Cube Patterns:</strong></li></ol><ul><li>(x + 1)² – (x – 1)² = 4x(x + 1)³ – (x – 1)³ = 6x² + 2</li></ul><ol><li><strong>Sum and Product Tricks:</strong></li></ol><ul><li>If x + 1/x = k → then x² + 1/x² = k² – 2If x + 1/x = k → then x³ + 1/x³ = k³ – 3k</li></ul><ol><li><strong>Quadratic without Formula:</strong></li></ol><ul><li>For ax² + bx + c = 0,</li><li>Product of roots = c/a</li><li> Sum of roots = –b/a</li></ul><ol><li><strong>Factorization Fast Track:</strong></li></ol><ul><li>Multiply a × c; find two numbers that multiply to (a×c) and add to b.</li><li> Split middle term accordingly.</li></ul><ol><li><strong>Special Result:</strong></li></ol><ul><li>If a + b + c = 0, then:</li><li> a³ + b³ + c³ = 3abc</li></ul><h4><strong>4. ESSENTIAL FORMULAE &amp; METHODS</strong></h4><p>Concept:Formula / Method</p><p>(a + b)² = a² + 2ab + b²</p><p>(a – b)² = a² – 2ab + b²</p><p>a² – b² = (a + b)(a – b)</p><p>a³ + b³ = (a + b)(a² – ab + b²)</p><p>a³ – b³ = (a – b)(a² + ab + b²)</p><p>(a + b + c)² = a² + b² + c² + 2(ab + bc + ca)</p><p>Sum of roots –b/a</p><p>Product of roots c/a</p><p>Quadratic Formula</p><p>x = (-b ± √(b² – 4ac)) / 2a</p><p><br></p><p>Exponent Rules: aᵐ × aⁿ = aᵐ⁺ⁿ, (aᵐ)ⁿ = aᵐⁿ, etc.</p><p><br></p><h4><strong>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</strong></h4><p><strong>Model 1: Simplification Problems</strong></p><ul><li>Involves identities, signs, and exponents.</li><li>Example: Simplify (x + y)² – (x – y)².</li></ul><p><strong>Model 2: Factorization Problems</strong></p><ul><li>Requires converting sums/differences into products.</li><li>Example: Factorize x² – 5x + 6.</li></ul><p><strong>Model 3: Solving Linear Equations</strong></p><ul><li>Usually direct substitution or elimination.</li></ul><p><strong>Model 4: Solving Quadratic Equations</strong></p><ul><li>Apply formula or factorization.</li></ul><p><strong>Model 5: Expression Evaluation</strong></p><ul><li>Substitute given values efficiently.</li></ul><p><strong>Model 6: Exponent &amp; Power Problems</strong></p><ul><li>Apply rules of indices; simplify using base properties.</li></ul><p><strong>Model 7: Word Problems Using Algebra</strong></p><ul><li>Convert statements into equations.</li></ul><h4><strong>6. STEP-BY-STEP SOLUTION METHODS</strong></h4><h3>Example 1: Simplify (x + y)² – (x – y)²</h3><p>Step 1: Expand both sides.</p><p>(x + y)² = x² + 2xy + y²</p><p>(x – y)² = x² – 2xy + y²</p><p>Step 2: Subtract → 4xy</p><p>Answer: 4xy</p><p><br></p><p><br></p><h3>Example 2: Solve 2x + 3 = 7</h3><p>Step 1: Subtract 3 → 2x = 4</p><p>Step 2: Divide by 2 → x = 2</p><p><br></p><p><br></p><h3>Example 3: Solve x² – 7x + 10 = 0</h3><p>Step 1: Find factors of 10 with sum 7 → (5, 2)</p><p>Step 2: (x – 5)(x – 2) = 0</p><p>x = 5 or x = 2</p><p><br></p><h3>Example 4: If x + 1/x = 3, find x² + 1/x²</h3><p>x² + 1/x² = (x + 1/x)² – 2 = 3² – 2 = 7</p><p><br></p><p><br></p><h3>Example 5: If a + b + c = 0, find a³ + b³ + c³</h3><p>a³ + b³ + c³ = 3abc</p><p><br></p><p><br></p><h4><strong>7. CONCLUSION</strong></h4><p>Algebra builds the foundation for all higher mathematical reasoning.</p><p>Understanding <strong>patterns, factorization, and equation solving</strong> enables smooth progress in later topics like Progressions, Functions, and Polynomials.</p><p><strong>Key Takeaways:</strong></p><ul><li>Know and use standard identities fluently.</li><li>Factorization and simplification save time in exams.</li><li>Always check results by substitution when possible.</li><li>Learn to convert word statements into algebraic equations — this is a crucial skill for advanced topics.</li></ul><p><br></p><p><strong>Practice Question:</strong></p><p>If $3x + 5 = 20$, find the value of $x$.</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b301');

-- 02. Geometry -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b202
INSERT INTO topics (id, subject_id, unit_id, name, description, difficulty, display_order, is_active, created_at, updated_at)
SELECT 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b202', '55555555-5555-5555-5555-555555555501',
    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Geometry',
    'Covers properties of points, lines, angles, triangles, circles, and other geometric shapes', 'MEDIUM', 30, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE id = 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b202');
INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b302', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b202',
    'Geometry Concepts',
    '<h4><strong>1. CONCEPTUAL FOUNDATION</strong></h4><p>Geometry is the branch of mathematics that deals with the <strong>study of shapes, sizes, figures, positions, and properties of space</strong>.</p><p>It provides the logical framework to understand and measure lines, angles, surfaces, and solids in both <strong>2D and 3D</strong> forms.</p><p>Geometry plays a vital role in <strong>quantitative aptitude</strong> questions that involve diagrams, distances, coordinates, and shapes like triangles, circles, polygons, cubes, and cylinders.</p><p><br></p><h4><strong>2. CORE THEORY &amp; PRINCIPLES</strong></h4><h5><strong>(a) Basic Definitions</strong></h5><ul><li><strong>Point</strong> – Represents a location; has no size or dimension.</li><li><strong>Line</strong> – Extends infinitely in both directions; no thickness.</li><li><strong>Line Segment</strong> – A part of a line with two endpoints.</li><li><strong>Ray</strong> – A line that starts at a point and extends infinitely in one direction.</li><li><strong>Plane</strong> – A flat surface that extends infinitely in all directions.</li></ul><h5><strong>(b) Types of Angles</strong></h5><ul><li><strong>Acute angle:</strong> Less than $90^\circ$</li><li><strong>Right angle:</strong> Equal to $90^\circ$</li><li><strong>Obtuse angle:</strong> Between $90^\circ$ and $180^\circ$</li><li><strong>Straight angle:</strong> Equal to $180^\circ$</li><li><strong>Reflex angle:</strong> Between $180^\circ$ and $360^\circ$</li></ul><h5><strong>(c) Angle Relationships</strong></h5><ul><li><strong>Complementary angles:</strong> Sum is $90^\circ$</li><li><strong>Supplementary angles:</strong> Sum is $180^\circ$</li><li><strong>Vertically opposite angles:</strong> Always equal when two lines intersect.</li></ul><h5><strong>(d) Basic Geometrical Shapes</strong></h5><ul><li><strong>Triangle</strong> – A closed figure with three sides and three angles.</li><li><strong>Quadrilateral</strong> – Four sides (includes square, rectangle, rhombus, parallelogram, trapezium).</li><li><strong>Circle</strong> – The set of all points in a plane equidistant from a fixed point (center).</li></ul><p><br></p><h4><strong>3. MAGIC SHORTCUTS</strong></h4><ul><li><strong>Exterior Angle Theorem for Triangles:</strong></li><li class="ql-indent-1">The measure of an exterior angle of a triangle = sum of the two interior opposite angles.$ \text{Exterior Angle} = \text{Sum of Two Interior Opposite Angles} $</li><li><strong>Right-Angle Triangle Shortcuts:</strong></li><li class="ql-indent-1"> Use the <strong>Pythagoras Theorem:</strong> $ h^2 = p^2 + b^2 $ where $h$ = hypotenuse, $p$ = perpendicular, $b$ = base.Common triplets: $(3, 4, 5)$, $(5, 12, 13)$, $(7, 24, 25)$, $(8, 15, 17)$</li><li><strong>Polygon Angle Sum:</strong></li><li class="ql-indent-1">$ \text{Sum of interior angles} = (n - 2) \times 180^\circ $$ \text{Each interior angle of regular polygon} = \frac{(n - 2) \times 180^\circ}{n} $</li><li><strong>Circle Geometry:</strong></li><li><strong>Angle in a semicircle</strong> is always a right angle ($90^\circ$).<strong>Tangent and radius</strong> are always perpendicular at the point of contact.</li></ul><h4><br></h4><h4><strong>4. ESSENTIAL FORMULAE &amp; METHODS</strong></h4><h3>(a) Triangle</h3><ul><li><strong>Area</strong> = $\frac{1}{2} \times \text{base} \times \text{height}$</li><li><strong>Heron’s Formula:</strong></li><li>$ \text{Area} = \sqrt{s(s-a)(s-b)(s-c)} $</li></ul><h3>where $ s = \frac{a+b+c}{2} $(</h3><h3>b) Rectangle and Square</h3><ul><li><strong>Rectangle:</strong></li><li>Area = $ l \times b $</li><li>Perimeter = $ 2(l+b) $</li><li><strong>Square:</strong></li><li>Area = $ 2(l+b) $</li><li>Perimeter = $ 4a $</li><li>Diagonal = $ a\sqrt{2} $</li></ul><h3>(c) Circle</h3><ul><li><strong>Circumference (Perimeter):</strong> $ 2\pi r $</li><li><strong>Area:</strong> $ \pi r^2 $</li><li><strong>Arc Length:</strong> $ \frac{\theta}{360^\circ} \times 2\pi r $</li><li><strong>Area of Sector:</strong> $ \frac{\theta}{360^\circ} \times \pi r^2 $</li></ul><h3>(d) Polygons</h3><ul><li><strong>Sum of interior angles:</strong> $ (n - 2) \times 180^\circ $</li><li><strong>Each exterior angle:</strong> $ \frac{360^\circ}{n} $</li></ul><p><br></p><h4><strong>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</strong></h4><ol><li><strong>Type 1 – Basic Angle Problems</strong></li><li>(Finding missing angle values using geometry theorems)</li><li><strong>Type 2 – Triangle-Based Questions</strong></li><li>(Finding area, perimeter, unknown sides using Pythagoras or Heron’s formula)</li><li><strong>Type 3 – Quadrilateral &amp; Polygon Problems</strong></li><li>(Finding area or angle measures in regular polygons)</li><li><strong>Type 4 – Circle Geometry Problems</strong></li><li>(Tangents, chords, sectors, arcs, cyclic quadrilaterals)</li><li><strong>Type 5 – Combined Geometry</strong></li><li>(Figures combining multiple shapes — e.g., rectangle inscribed in a circle)</li></ol><p><br></p><h4><strong>6. STEP-BY-STEP SOLUTION METHODS</strong></h4><h3>Example 1: Find the area of a triangle with sides 5 cm, 6 cm, and 7 cm.</h3><p><strong>Step 1:</strong></p><p>Find the semi-perimeter:</p><p>$ s = \frac{a+b+c}{2} = \frac{5+6+7}{2} = 9 $</p><p><strong>Step 2:</strong></p><p>Apply Heron’s formula:</p><p>$ \text{Area} = \sqrt{s(s-a)(s-b)(s-c)} $</p><p><strong>Step 3:</strong></p><p>&nbsp;$ \text{Area} = \sqrt{9(9-5)(9-6)(9-7)} = \sqrt{9 \times 4 \times 3 \times 2} = \sqrt{216} = 14.7 \text{ cm}^2 $</p><p><br></p><h3>Example 2: Find the area of a sector of radius 7 cm and angle 90°.</h3><p><strong>Step 1:</strong></p><p>Use formula:</p><p>$ \text{Area of Sector} = \frac{\theta}{360^\circ} \times \pi r^2 $</p><p><strong>Step 2:</strong></p><p>&nbsp;$ \text{Area} = \frac{90}{360} \times \frac{22}{7} \times 7^2 = \frac{1}{4} \times 154 = 38.5 \text{ cm}^2 $</p><p><br></p><h4><strong>7. CONCLUSION</strong></h4><p>Geometry builds visual and spatial reasoning skills.</p><p>To master it in aptitude exams:</p><ul><li>Memorize all <strong>key theorems and formulae</strong>.</li><li>Practice <strong>figure-based questions</strong> regularly.</li><li>Learn to <strong>sketch rough diagrams</strong> quickly — this often reveals the relation or formula to be used.</li><li>Many geometry problems can be solved with <strong>ratio-based reasoning or Pythagoras shortcuts</strong>, so identify patterns smartly.</li></ul><p><br></p><h4><strong>Practice Question:</strong></h4><p>The radius of a circle is 14 cm and the angle of a sector is 120°. Find the area of the sector ?</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b302');

