INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b309', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b209',
    'Progressions (AP, GP, HP) Concepts',
    '<h4><strong>1. CONCEPTUAL FOUNDATION</strong></h4><p><strong>Progressions</strong> are sequences of numbers that follow a definite pattern or rule.</p><p>They are essential in understanding patterns, predicting terms, and solving real-life problems involving growth, repetition, and change.</p><p>There are <strong>three main types</strong> of progressions:</p><ol><li><strong>Arithmetic Progression (A.P.)</strong> – Numbers increase or decrease by a constant difference.</li><li><strong>Geometric Progression (G.P.)</strong> – Numbers increase or decrease by a constant ratio.</li><li><strong>Harmonic Progression (H.P.)</strong> – The reciprocals of numbers form an A.P.</li></ol><p>Understanding progressions helps in areas like finance, interest calculations, population growth, physics, and statistics.</p><p><br></p><h4><strong>2. CORE THEORY &amp; PRINCIPLES</strong></h4><h3>(A) Arithmetic Progression (A.P.)</h3><p>An A.P. is a sequence in which the <strong>difference between consecutive terms is constant</strong>.</p><p> This difference is called the <strong>common difference (d)</strong>.</p><p>If the first term is <strong>a</strong>, and the common difference is <strong>d</strong>,</p><p> then the sequence is:</p><p> a, a + d, a + 2d, a + 3d, …</p><p><strong>General Term (nth Term):</strong></p><p> Tₙ = a + (n – 1)d</p><p><strong>Sum of n Terms (Sₙ):</strong></p><p> Sₙ = (n/2)[2a + (n – 1)d]</p><p> or</p><p> Sₙ = (n/2)(a + l), where l = last term</p><h3>(B) Geometric Progression (G.P.)</h3><p>A G.P. is a sequence in which the <strong>ratio between consecutive terms is constant</strong>.</p><p> This ratio is called the <strong>common ratio (r)</strong>.</p><p>If the first term is <strong>a</strong>, and the common ratio is <strong>r</strong>,</p><p> then the sequence is:</p><p> a, ar, ar², ar³, …</p><p><strong>General Term (nth Term):</strong></p><p> Tₙ = arⁿ⁻¹</p><p><strong>Sum of n Terms (Sₙ):</strong></p><p> If r ≠ 1,</p><p> Sₙ = a(1 – rⁿ) / (1 – r)</p><p><strong>Sum of Infinite G.P.:</strong></p><p> If |r| &lt; 1,</p><p> S∞ = a / (1 – r)</p><h3>(C) Harmonic Progression (H.P.)</h3><p>A H.P. is a sequence in which the <strong>reciprocals of the terms form an A.P.</strong></p><p>If a, b, c are in H.P., then 1/a, 1/b, 1/c are in A.P.</p><p><strong>nth Term of H.P.:</strong></p><p> If reciprocals form an A.P.,</p><p> then</p><p> 1/Tₙ = 1/a + (n – 1)d</p><p> ⇒ Tₙ = 1 / [1/a + (n – 1)d]</p><h3>(D) Relationship Between A.P., G.P., and H.P.</h3><p>If <strong>a, b, c</strong> are in A.P., then</p><p> 2b = a + c</p><p>If <strong>a, b, c</strong> are in G.P., then</p><p> b² = ac</p><p>If <strong>a, b, c</strong> are in H.P., then</p><p> 2/b = 1/a + 1/c</p><p><br></p><h2>3. MAGIC SHORTCUTS</h2><ol><li><strong>Finding Missing Terms Quickly:</strong></li></ol><ul><li class="ql-indent-1">In A.P.: middle term = (first term + last term)/2</li><li class="ql-indent-1">In G.P.: middle term = √(first term × last term)</li><li class="ql-indent-1">In H.P.: middle term = 2 × (first term × last term) / (first term + last term)</li></ul><ol><li><strong>Finding Number of Terms (n):</strong></li></ol><ul><li class="ql-indent-1">For A.P.: n = [(l – a)/d] + 1</li></ul><ol><li><strong>Finding Common Difference (d):</strong></li></ol><ul><li class="ql-indent-1">d = (l – a)/(n – 1)</li></ul><ol><li><strong>Fast Sum Tricks:</strong></li></ol><ul><li class="ql-indent-1">Sum of first n natural numbers = n(n + 1)/2</li><li class="ql-indent-1">Sum of squares of first n natural numbers = n(n + 1)(2n + 1)/6</li><li class="ql-indent-1">Sum of cubes of first n natural numbers = [n(n + 1)/2]²</li></ul><ol><li><strong>Special G.P. Sums:</strong></li></ol><ul><li class="ql-indent-1">1 + r + r² + … + rⁿ⁻¹ = (rⁿ – 1)/(r – 1)</li><li class="ql-indent-1">If |r| &lt; 1 and n is large, use S∞ = a/(1 – r)</li></ul><ol><li><strong>Shortcut for nth Term Between A and B:</strong></li></ol><ul><li class="ql-indent-1">In A.P.: Tₙ = A + n(B – A)/(k + 1) where there are k terms between A and B.</li></ul><h2><br></h2><h4><strong style="background-color: transparent; color: rgb(0, 0, 0);">4. ESSENTIAL FORMULAE &amp; METHODS</strong></h4><table table_id="kznju4wlece" id="kznju4wlece" class=""><tr row_id="f3zrravd5ri" style="width: 100%;"><td table_id="kznju4wlece" row_id="f3zrravd5ri" cell_id="ylii0c7rhyd" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Type</strong></p></td><td table_id="kznju4wlece" row_id="f3zrravd5ri" cell_id="90vhi7xhjds" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Formula</strong></p></td><td table_id="kznju4wlece" row_id="f3zrravd5ri" cell_id="9z5v6q5opxf" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Description</strong></p></td></tr><tr row_id="bffwhfx41bb" style="width: 100%;"><td table_id="kznju4wlece" row_id="bffwhfx41bb" cell_id="zzvn05q462r" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">A.P. nth Term</span></p></td><td table_id="kznju4wlece" row_id="bffwhfx41bb" cell_id="0z8dtysd6oy" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Tₙ = a + (n – 1)d</span></p></td><td table_id="kznju4wlece" row_id="bffwhfx41bb" cell_id="gnghr93l9oq" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">To find any term</span></p></td></tr><tr row_id="kbrf7mq83zo" style="width: 100%;"><td table_id="kznju4wlece" row_id="kbrf7mq83zo" cell_id="axb71pt5ehl" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">A.P. Sum</span></p></td><td table_id="kznju4wlece" row_id="kbrf7mq83zo" cell_id="sjjl0be4qx" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Sₙ = n/2 [2a + (n – 1)d]</span></p></td><td table_id="kznju4wlece" row_id="kbrf7mq83zo" cell_id="l2u4ttfl1io" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Sum of n terms</span></p></td></tr><tr row_id="0bdgwcoy1uxv" style="width: 100%;"><td table_id="kznju4wlece" row_id="0bdgwcoy1uxv" cell_id="57tkhektj3r" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">A.P. Last Term</span></p></td><td table_id="kznju4wlece" row_id="0bdgwcoy1uxv" cell_id="junvkr1nbf9" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">l = a + (n – 1)d</span></p></td><td table_id="kznju4wlece" row_id="0bdgwcoy1uxv" cell_id="27g6nxayz89" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Final term</span></p></td></tr><tr row_id="5cbxv88t239" style="width: 100%;"><td table_id="kznju4wlece" row_id="5cbxv88t239" cell_id="7fgi6bi27iw" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">G.P. nth Term</span></p></td><td table_id="kznju4wlece" row_id="5cbxv88t239" cell_id="64q6hlvx55l" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Tₙ = arⁿ⁻¹</span></p></td><td table_id="kznju4wlece" row_id="5cbxv88t239" cell_id="aovonl9l3mu" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">nth term of G.P.</span></p></td></tr><tr row_id="oa2ru61iwxh" style="width: 100%;"><td table_id="kznju4wlece" row_id="oa2ru61iwxh" cell_id="hmvgqr8tgq" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">G.P. Sum</span></p></td><td table_id="kznju4wlece" row_id="oa2ru61iwxh" cell_id="g2p30ws48zk" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Sₙ = a(1 – rⁿ)/(1 – r)</span></p></td><td table_id="kznju4wlece" row_id="oa2ru61iwxh" cell_id="nssrqjqs1j8" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Sum of n terms</span></p></td></tr><tr row_id="gsamuly5ntk" style="width: 100%;"><td table_id="kznju4wlece" row_id="gsamuly5ntk" cell_id="gkxb9yp97mu" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">G.P. Infinite Sum</span></p></td><td table_id="kznju4wlece" row_id="gsamuly5ntk" cell_id="sb0cvi5rfpo" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">S∞ = a/(1 – r)</span></p></td><td table_id="kznju4wlece" row_id="gsamuly5ntk" cell_id="z3vn3nqzpjo" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">When</span></p></td></tr><tr row_id="7ac0298uo5x" style="width: 100%;"><td table_id="kznju4wlece" row_id="7ac0298uo5x" cell_id="ql7phah5ys" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">H.P. nth Term</span></p></td><td table_id="kznju4wlece" row_id="7ac0298uo5x" cell_id="2ut3ljs41da" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Tₙ = 1 / [1/a + (n – 1)d]</span></p></td><td table_id="kznju4wlece" row_id="7ac0298uo5x" cell_id="bu3n1ik6tl9" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Reciprocal form</span></p></td></tr><tr row_id="ngh1yz0c9bm" style="width: 100%;"><td table_id="kznju4wlece" row_id="ngh1yz0c9bm" cell_id="6f31yh69j6t" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Relation between A.P., G.P., H.P.</span></p></td><td table_id="kznju4wlece" row_id="ngh1yz0c9bm" cell_id="qnm7cb7n2g" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">A : G : H = (a + b)/2 : √(ab) : 2ab/(a + b)</span></p></td><td table_id="kznju4wlece" row_id="ngh1yz0c9bm" cell_id="6z49e5jclz" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Mean relations</span></p></td></tr></table><h2><br></h2><p><br></p><h2>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</h2><p><strong>Model 1:</strong> Find nth term or missing term in A.P./G.P./H.P.</p><p> <strong>Model 2:</strong> Find number of terms when first term, last term, and difference/ratio are given.</p><p> <strong>Model 3:</strong> Find sum of n terms (finite or infinite).</p><p> <strong>Model 4:</strong> Find relation between terms of A.P., G.P., or H.P.</p><p> <strong>Model 5:</strong> Mixed progressions – combination of A.P. and G.P.</p><p> <strong>Model 6:</strong> Mean problems – arithmetic mean, geometric mean, harmonic mean.</p><p> <strong>Model 7:</strong> Word problems involving growth/decay or installment pattern (G.P. model).</p><h2>6. STEP-BY-STEP SOLUTION METHODS</h2><h3>Example 1: Find the 10th term of the A.P. 2, 5, 8, 11, …</h3><p>Given: a = 2, d = 3</p><p> Tₙ = a + (n – 1)d = 2 + (10 – 1)×3 = 2 + 27 = 29</p><p> <strong>Answer: 29</strong></p><h3>Example 2: Find the sum of first 20 terms of the A.P. 3, 7, 11, …</h3><p>Given: a = 3, d = 4, n = 20</p><p> Sₙ = n/2 [2a + (n – 1)d]</p><p> = 20/2 [6 + 76] = 10 × 82 = 820</p><p> <strong>Answer: 820</strong></p><h3>Example 3: Find 8th term of G.P. 3, 6, 12, 24, …</h3><p>Given: a = 3, r = 2, n = 8</p><p> Tₙ = arⁿ⁻¹ = 3 × 2⁷ = 3 × 128 = 384</p><p> <strong>Answer: 384</strong></p><h3>Example 4: Find sum to infinity of 9, 6, 4, …</h3><p>Given: a = 9, r = 2/3 (since 6/9 = 2/3)</p><p> S∞ = a/(1 – r) = 9/(1 – 2/3) = 9/(1/3) = 27</p><p> <strong>Answer: 27</strong></p><h3>Example 5: If 1/x, 1/y, 1/z are in A.P., show that x, y, z are in H.P.</h3><p>By definition of H.P., reciprocals form A.P.</p><p> Hence proved.</p><p><br></p><h2>7. CONCLUSION</h2><p>Progressions are powerful tools to handle patterns and series efficiently.</p><p> They occur frequently in exams under simplification, ratio, and interest models.</p><p><strong>Key Takeaways:</strong></p><ul><li>A.P. → constant difference</li><li>G.P. → constant ratio</li><li>H.P. → reciprocal of A.P.</li><li>Learn direct formulas and relations between A, G, and H means.</li><li>In G.P., check |r| &lt; 1 for infinite series.</li><li>Always label the given a, d, r, n carefully before substitution.</li></ul><p><br></p><p><strong>Practice Question:</strong></p><p>Find the 10th term of an Arithmetic Progression (A.P.) whose first term is 3 and common difference is 5.</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b309');

-- 10. Trigonometry -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b210
