INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b310', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b210',
    'Trigonometry Concepts',
    '<h3>1. CONCEPTUAL FOUNDATION</h3><p><strong>Trigonometry</strong> is the branch of mathematics that deals with the relationships between the sides and angles of triangles—especially <strong>right-angled triangles</strong>.</p><p>The term is derived from Greek words:</p><ul><li>Trigonon = triangle</li><li>Metron = measure</li></ul><p>Trigonometry is a core concept used in:</p><ul><li>Heights and distances</li><li>Navigation and astronomy</li><li>Architecture and engineering</li><li>Physics (waves, vectors, forces)</li></ul><p>The foundation of trigonometry lies in understanding <strong>trigonometric ratios</strong>, <strong>identities</strong>, and <strong>angles</strong>.</p><p><strong>Prerequisites:</strong></p><ul><li>Knowledge of triangles and their properties</li><li>Basic understanding of Pythagoras’ theorem</li><li>Concept of angles and degrees/radians</li></ul><p><br></p><h3>2. CORE THEORY &amp; PRINCIPLES</h3><h4>(a) The Right-Angled Triangle Model</h4><p>In a right-angled triangle with:</p><ul><li>Perpendicular = $P$</li><li>Base = $B$</li><li>Hypotenuse = $H$</li></ul><p>Then, the six <strong>trigonometric ratios</strong> for an acute angle $\theta$ are defined as:</p><ul><li>$\sin \theta = \frac{P}{H}$</li><li>$\cos \theta = \frac{B}{H}$</li><li>$\tan \theta = \frac{P}{B}$</li><li>$\cot \theta = \frac{B}{P}$</li><li>$\sec \theta = \frac{H}{B}$</li><li>$\csc \theta = \frac{H}{P}$</li></ul><h4>(b) Reciprocal Relations</h4><ul><li>$\sin \theta = \frac{1}{\csc \theta}$</li><li>$\cos \theta = \frac{1}{\sec \theta}$</li><li>$\tan \theta = \frac{1}{\cot \theta}$</li></ul><h4>(c) Quotient Relations</h4><ul><li>$\tan \theta = \frac{\sin \theta}{\cos \theta}$</li><li>$\cot \theta = \frac{\cos \theta}{\sin \theta}$</li></ul><h4>(d) Pythagorean Identities</h4><p>Derived from $H^2 = P^2 + B^2$, we get:</p><ul><li>$\sin^2 \theta + \cos^2 \theta = 1$</li><li>$1 + \tan^2 \theta = \sec^2 \theta$</li><li>$1 + \cot^2 \theta = \csc^2 \theta$</li></ul><h4>(e) Co-function Relations</h4><ul><li>$\sin (90^\circ - \theta) = \cos \theta$</li><li>$\cos (90^\circ - \theta) = \sin \theta$</li><li>$\tan (90^\circ - \theta) = \cot \theta$</li><li>$\cot (90^\circ - \theta) = \tan \theta$</li><li>$\sec (90^\circ - \theta) = \csc \theta$</li><li>$\csc (90^\circ - \theta) = \sec \theta$</li></ul><h4>(f) Signs of Trigonometric Functions — Quadrants</h4><table table_id="s8rn362xgc" id="s8rn362xgc" class=""><tr row_id="npx5vitciqa" style="width: 100%;"><td table_id="s8rn362xgc" row_id="npx5vitciqa" cell_id="0pusfq8u2sg" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Quadrant</strong></p></td><td table_id="s8rn362xgc" row_id="npx5vitciqa" cell_id="613h5gsczry" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Angle Range</strong></p></td><td table_id="s8rn362xgc" row_id="npx5vitciqa" cell_id="c4c6pbrxk6p" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Sign of sin</strong></p></td><td table_id="s8rn362xgc" row_id="npx5vitciqa" cell_id="jvipomvq3ca" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Sign of cos</strong></p></td><td table_id="s8rn362xgc" row_id="npx5vitciqa" cell_id="uc3wry0bw7" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Sign of tan</strong></p></td><td table_id="s8rn362xgc" row_id="npx5vitciqa" cell_id="pyj206g555a" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Mnemonic</strong></p></td></tr><tr row_id="7hcv749wgim" style="width: 100%;"><td table_id="s8rn362xgc" row_id="7hcv749wgim" cell_id="6rppebiczk3" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">I</span></p></td><td table_id="s8rn362xgc" row_id="7hcv749wgim" cell_id="kjkakgt8ldd" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$0^\circ$ to $90^\circ$</span></p></td><td table_id="s8rn362xgc" row_id="7hcv749wgim" cell_id="gjz3x7cl7iv" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">+</span></p></td><td table_id="s8rn362xgc" row_id="7hcv749wgim" cell_id="jp7vdah6pm" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">+</span></p></td><td table_id="s8rn362xgc" row_id="7hcv749wgim" cell_id="9lb73keca3k" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">+</span></p></td><td table_id="s8rn362xgc" row_id="7hcv749wgim" cell_id="eloe4vcjaun" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">All Positive</span></p></td></tr><tr row_id="si9lpeejf9" style="width: 100%;"><td table_id="s8rn362xgc" row_id="si9lpeejf9" cell_id="qn5ynh9f64d" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">II</span></p></td><td table_id="s8rn362xgc" row_id="si9lpeejf9" cell_id="rxbiud5nq5k" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$90^\circ$ to $180^\circ$</span></p></td><td table_id="s8rn362xgc" row_id="si9lpeejf9" cell_id="2koq5ykqxrc" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">+</span></p></td><td table_id="s8rn362xgc" row_id="si9lpeejf9" cell_id="3kon9geeubl" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">–</span></p></td><td table_id="s8rn362xgc" row_id="si9lpeejf9" cell_id="0e2dd9714yj9" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">–</span></p></td><td table_id="s8rn362xgc" row_id="si9lpeejf9" cell_id="70ev6xazo5a" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Sine Positive</span></p></td></tr><tr row_id="yssrt05502" style="width: 100%;"><td table_id="s8rn362xgc" row_id="yssrt05502" cell_id="l25ww8gvep" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">III</span></p></td><td table_id="s8rn362xgc" row_id="yssrt05502" cell_id="7y3w2zax9e5" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$180^\circ$ to $270^\circ$</span></p></td><td table_id="s8rn362xgc" row_id="yssrt05502" cell_id="5juk16aq10u" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">–</span></p></td><td table_id="s8rn362xgc" row_id="yssrt05502" cell_id="z7691jxe58" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">–</span></p></td><td table_id="s8rn362xgc" row_id="yssrt05502" cell_id="ajco87trdll" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">+</span></p></td><td table_id="s8rn362xgc" row_id="yssrt05502" cell_id="scv7xb0cfdo" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Tangent Positive</span></p></td></tr><tr row_id="l794hhz46xi" style="width: 100%;"><td table_id="s8rn362xgc" row_id="l794hhz46xi" cell_id="9ocom92jxmo" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">IV</span></p></td><td table_id="s8rn362xgc" row_id="l794hhz46xi" cell_id="wa4vrpy18wp" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$270^\circ$ to $360^\circ$</span></p></td><td table_id="s8rn362xgc" row_id="l794hhz46xi" cell_id="tgpc5d39y0f" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">–</span></p></td><td table_id="s8rn362xgc" row_id="l794hhz46xi" cell_id="6k3mc33tmpm" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">+</span></p></td><td table_id="s8rn362xgc" row_id="l794hhz46xi" cell_id="b1clk0y9j2g" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">–</span></p></td><td table_id="s8rn362xgc" row_id="l794hhz46xi" cell_id="qt4cx2mpgfb" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Cosine Positive</span></p></td></tr></table><p><br></p><h3>3. MAGIC SHORTCUTS</h3><ol><li><strong>Trick to Remember Standard Values</strong></li></ol><table table_id="kkd82crdme" id="kkd82crdme"><tr row_id="2saxe6icchz" style="width: 100%;"><td table_id="kkd82crdme" row_id="2saxe6icchz" cell_id="jb2h0aukjqb" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Angle</strong></p></td><td table_id="kkd82crdme" row_id="2saxe6icchz" cell_id="8xg7wgerupx" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">$\sin \theta$</strong></p></td><td table_id="kkd82crdme" row_id="2saxe6icchz" cell_id="t9oc2fwzykg" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">$\cos \theta$</strong></p></td><td table_id="kkd82crdme" row_id="2saxe6icchz" cell_id="9907at202ij" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">$\tan \theta$</strong></p></td></tr><tr row_id="voi36xyd5to" style="width: 100%;"><td table_id="kkd82crdme" row_id="voi36xyd5to" cell_id="v8bnye1ico" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$0^\circ$</span></p></td><td table_id="kkd82crdme" row_id="voi36xyd5to" cell_id="huh8kwut6qf" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">0</span></p></td><td table_id="kkd82crdme" row_id="voi36xyd5to" cell_id="iplsnoklmmb" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">1</span></p></td><td table_id="kkd82crdme" row_id="voi36xyd5to" cell_id="inis2xwf81c" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">0</span></p></td></tr><tr row_id="ru0hfalii6f" style="width: 100%;"><td table_id="kkd82crdme" row_id="ru0hfalii6f" cell_id="qt6c83xk9i" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$30^\circ$</span></p></td><td table_id="kkd82crdme" row_id="ru0hfalii6f" cell_id="3m8wv3lf4fa" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\frac{1}{2}$</span></p></td><td table_id="kkd82crdme" row_id="ru0hfalii6f" cell_id="n2tm1ewbdf9" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\frac{\sqrt{3}}{2}$</span></p></td><td table_id="kkd82crdme" row_id="ru0hfalii6f" cell_id="2x3by61kyl2" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\frac{1}{\sqrt{3}}$</span></p></td></tr><tr row_id="w2e6vko9zyb" style="width: 100%;"><td table_id="kkd82crdme" row_id="w2e6vko9zyb" cell_id="xa7c9r2h3oi" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$45^\circ$</span></p></td><td table_id="kkd82crdme" row_id="w2e6vko9zyb" cell_id="54ducs6dwq" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\frac{1}{\sqrt{2}}$</span></p></td><td table_id="kkd82crdme" row_id="w2e6vko9zyb" cell_id="1vbjk48nmlk" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\frac{1}{\sqrt{2}}$</span></p></td><td table_id="kkd82crdme" row_id="w2e6vko9zyb" cell_id="dnzrtfdga6w" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">1</span></p></td></tr><tr row_id="x0kpogpge2f" style="width: 100%;"><td table_id="kkd82crdme" row_id="x0kpogpge2f" cell_id="295zyr3ymq7" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$60^\circ$</span></p></td><td table_id="kkd82crdme" row_id="x0kpogpge2f" cell_id="0n0dflvq325" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\frac{\sqrt{3}}{2}$</span></p></td><td table_id="kkd82crdme" row_id="x0kpogpge2f" cell_id="lybpqx7jb7q" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\frac{1}{2}$</span></p></td><td table_id="kkd82crdme" row_id="x0kpogpge2f" cell_id="x9eck8lkxm" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\sqrt{3}$</span></p></td></tr><tr row_id="f2xu1vnttrh" style="width: 100%;"><td table_id="kkd82crdme" row_id="f2xu1vnttrh" cell_id="qdnszs0o5" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$90^\circ$</span></p></td><td table_id="kkd82crdme" row_id="f2xu1vnttrh" cell_id="1jkqt330gmm" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">1</span></p></td><td table_id="kkd82crdme" row_id="f2xu1vnttrh" cell_id="j8xxqlpx2x" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">0</span></p></td><td table_id="kkd82crdme" row_id="f2xu1vnttrh" cell_id="6ow8nqp41bx" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Not defined</span></p></td></tr></table><p><br></p><p><strong>Trick to memorize sin values:</strong></p><p>Write $0, \frac{1}{2}, \frac{1}{\sqrt{2}}, \frac{\sqrt{3}}{2}, 1$ — these are for $0^\circ, 30^\circ, 45^\circ, 60^\circ, 90^\circ$ respectively.</p><p>Cos values are <strong>reverse</strong> of sin values.</p><ol><li><strong>Relation Between Degrees and Radians:</strong></li></ol><ul><li>$180^\circ = \pi$ radians</li><li>$1^\circ = \frac{\pi}{180}$ radians</li><li>$1 \text{ radian} = \frac{180}{\pi}^\circ$</li></ul><ol><li><strong>Complementary Angle Trick:</strong></li><li>Angles that add up to $90^\circ$ are complements.</li><li>Example: $\sin 30^\circ = \cos 60^\circ$, $\tan 20^\circ = \cot 70^\circ$</li></ol><p><br></p><h3>4. ESSENTIAL FORMULAE &amp; METHODS</h3><table table_id="nm9ziwu3uxp" id="nm9ziwu3uxp"><tr row_id="s74kizfrei" style="width: 100%;"><td table_id="nm9ziwu3uxp" row_id="s74kizfrei" cell_id="vyyoi6w1kg" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Type</strong></p></td><td table_id="nm9ziwu3uxp" row_id="s74kizfrei" cell_id="ncz293ejdhp" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Formula</strong></p></td></tr><tr row_id="f6r4u5o0hfj" style="width: 100%;"><td table_id="nm9ziwu3uxp" row_id="f6r4u5o0hfj" cell_id="wuks8g321i" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Reciprocal</span></p></td><td table_id="nm9ziwu3uxp" row_id="f6r4u5o0hfj" cell_id="spremr5ay" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\sin \theta = \frac{1}{\csc \theta}$, $\cos \theta = \frac{1}{\sec \theta}$, $\tan \theta = \frac{1}{\cot \theta}$</span></p></td></tr><tr row_id="axsq1tkau5" style="width: 100%;"><td table_id="nm9ziwu3uxp" row_id="axsq1tkau5" cell_id="sh7tnc42psk" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Quotient</span></p></td><td table_id="nm9ziwu3uxp" row_id="axsq1tkau5" cell_id="14x3boykg8h" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\tan \theta = \frac{\sin \theta}{\cos \theta}$</span></p></td></tr><tr row_id="aegg9h92z9o" style="width: 100%;"><td table_id="nm9ziwu3uxp" row_id="aegg9h92z9o" cell_id="j5ambid0iwa" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Pythagorean</span></p></td><td table_id="nm9ziwu3uxp" row_id="aegg9h92z9o" cell_id="m6iao9ybd6i" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\sin^2 \theta + \cos^2 \theta = 1$</span></p></td></tr><tr row_id="p8dcis9lzng" style="width: 100%;"><td table_id="nm9ziwu3uxp" row_id="p8dcis9lzng" cell_id="amhnryciox" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Angle Sum</span></p></td><td table_id="nm9ziwu3uxp" row_id="p8dcis9lzng" cell_id="2izol44u5bc" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\sin (A + B) = \sin A \cos B + \cos A \sin B$</span></p></td></tr><tr row_id="0ujipstowin" style="width: 100%;"><td table_id="nm9ziwu3uxp" row_id="0ujipstowin" cell_id="8gd6xob1wae" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Angle Difference</span></p></td><td table_id="nm9ziwu3uxp" row_id="0ujipstowin" cell_id="cbbtiegzmnc" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\cos (A - B) = \cos A \cos B + \sin A \sin B$</span></p></td></tr><tr row_id="5f84fdiyb3q" style="width: 100%;"><td table_id="nm9ziwu3uxp" row_id="5f84fdiyb3q" cell_id="7stcj3pv8xu" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Double Angle</span></p></td><td table_id="nm9ziwu3uxp" row_id="5f84fdiyb3q" cell_id="jyop8upf6z" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\sin 2A = 2 \sin A \cos A$, $\cos 2A = \cos^2 A - \sin^2 A$</span></p></td></tr><tr row_id="8zuoadatqvx" style="width: 100%;"><td table_id="nm9ziwu3uxp" row_id="8zuoadatqvx" cell_id="7m8udj5zcjy" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Half Angle</span></p></td><td table_id="nm9ziwu3uxp" row_id="8zuoadatqvx" cell_id="bsfzoxg1yxj" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\sin \frac{A}{2} = \sqrt{\frac{1 - \cos A}{2}}$, $\cos \frac{A}{2} = \sqrt{\frac{1 + \cos A}{2}}$</span></p></td></tr></table><p><br></p><h2>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</h2><ol><li><strong>Type 1 – Basic Ratio Problems:</strong></li><li>Finding one trigonometric ratio when another is known.</li><li><strong>Type 2 – Identity Verification:</strong></li><li>Proving that LHS = RHS using trigonometric identities.</li><li><strong>Type 3 – Angle-based Problems:</strong></li><li>Problems involving complementary or supplementary angles.</li><li><strong>Type 4 – Expression Simplification:</strong></li><li>Simplifying expressions like $\frac{1 - \sin \theta}{1 + \sin \theta}$ or $\tan \theta + \cot \theta$.</li><li><strong>Type 5 – Heights &amp; Distances Applications:</strong></li><li>Practical geometry-based problems using trigonometric ratios.</li></ol><p><br></p><h2>6. STEP-BY-STEP SOLUTION METHODS</h2><h3>Example 1:</h3><p>If $\sin \theta = \frac{3}{5}$, find $\cos \theta$ and $\tan \theta$.</p><p><strong>Step 1:</strong></p><p>Use identity $\sin^2 \theta + \cos^2 \theta = 1$</p><p>$ \left(\frac{3}{5}\right)^2 + \cos^2 \theta = 1 $</p><p>$ \cos^2 \theta = 1 - \frac{9}{25} = \frac{16}{25} $</p><p>$ \cos \theta = \frac{4}{5} $</p><p><strong>Step 2:</strong></p><p>Now $ \tan \theta = \frac{\sin \theta}{\cos \theta} = \frac{3/5}{4/5} = \frac{3}{4} $</p><p><br></p><h3>Example 2:</h3><p>Prove that $\frac{1 - \sin^2 \theta}{\cos^2 \theta} = 1$.</p><p><strong>Step 1:</strong></p><p>LHS = $\frac{1 - \sin^2 \theta}{\cos^2 \theta}$</p><p><strong>Step 2:</strong></p><p>Use identity $ \sin^2 \theta + \cos^2 \theta = 1 $</p><p>So, $ 1 - \sin^2 \theta = \cos^2 \theta $</p><p><strong>Step 3:</strong></p><p>LHS = $\frac{\cos^2 \theta}{\cos^2 \theta} = 1$</p><p>Hence, proved</p><p><br></p><h2>7. CONCLUSION</h2><p>Trigonometry forms the <strong>foundation of many advanced topics</strong> in quantitative aptitude such as <strong>Heights &amp; Distances</strong>, <strong>Geometry</strong>, and <strong>Mensuration (3D)</strong>.</p><p>Key mastery goals:</p><ul><li>Memorize standard angle values and trigonometric identities.</li><li>Learn to visualize the right-angled triangle structure for every problem.</li><li>Practice identity proofs regularly to strengthen algebraic manipulation.</li><li>Remember quadrant rules for sign determination in angle conversions.</li></ul><p><br></p><h4>Practice Question:</h4><p>Evaluate (sin 30° + cos 60°) − (sin 60° + cos 30°).</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b310');

-- 11. Logarithms -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b211
INSERT INTO topics (id, subject_id, unit_id, name, description, difficulty, display_order, is_active, created_at, updated_at)
SELECT 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b211', '55555555-5555-5555-5555-555555555501',
    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Logarithms',
    'Uses laws of logarithms to simplify calculations and solve exponential equations', 'MEDIUM', 39, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE id = 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b211');
INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b311', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b211',
    'Logarithms Concepts',
    '<h3>1. CONCEPTUAL FOUNDATION</h3><p>A <strong>logarithm</strong> is the inverse operation of exponentiation.</p><p>If $a^x = N$, then the logarithmic form is written as:</p><p>$\log_a N = x$</p><p>This means that the logarithm of a number $N$ to the base $a$ is the <strong>exponent</strong> to which $a$ must be raised to get $N$.</p><p><strong>Example:</strong></p><p>Since $2^3 = 8$, we can write $\log_2 8 = 3$.</p><h4>Basic Conditions</h4><ul><li>The base ($a$) must be <strong>positive</strong> and <strong>not equal to 1</strong>.</li><li>⇒ $a &gt; 0$, $a \neq 1$</li><li>The number ($N$) must be <strong>positive</strong>.</li><li>⇒ $N &gt; 0$</li></ul><p><br></p><h3>2. CORE THEORY &amp; PRINCIPLES</h3><h4>2.1 Fundamental Concepts</h4><ul><li><strong>Exponential Form:</strong> $a^x = N$</li><li><strong>Logarithmic Form:</strong> $\log_a N = x$</li></ul><p>Both expressions represent the same relationship.</p><p><br></p><h4>2.2 Important Properties of Logarithms</h4><ol><li><strong>Product Rule:</strong></li><li>$\log_a (MN) = \log_a M + \log_a N$</li><li><strong>Quotient Rule:</strong></li><li>$\log_a \left(\frac{M}{N}\right) = \log_a M - \log_a N$</li><li><strong>Power Rule:</strong></li><li>$\log_a (M^n) = n \log_a M$</li><li><strong>Base Change Rule:</strong></li><li>$\log_a M = \frac{\log_b M}{\log_b a}$</li><li><strong>Reciprocal Rule:</strong></li><li>$\log_a b = \frac{1}{\log_b a}$</li><li><strong>Log of 1:</strong></li><li>$\log_a 1 = 0$</li><li><strong>Log of Base:</strong></li><li>$\log_a a = 1$</li></ol><p><br></p><h3>3. MAGIC SHORTCUTS</h3><ol><li><strong>Converting Between Bases Quickly:</strong></li></ol><ul><li>$\log_2 8 = 3$ because $8 = 2^3$$\log_5 125 = 3$ because $125 = 5^3$</li></ul><ol><li><strong>Natural and Common Logs:</strong></li></ol><ul><li><strong>Common Logarithm:</strong> Base 10 → $\log_{10} x = \log x$<strong>Natural Logarithm:</strong> Base $e$ → $\log_e x = \ln x$</li></ul><ol><li><strong>Shortcut for Multiplying Numbers Using Logs (Conceptual):</strong></li><li>Multiplication can be done by addition of logarithms:</li><li>$\log (A \times B) = \log A + \log B$</li><li><strong>When the Question Asks “Find the Value”:</strong></li><li>Try expressing the number in powers of the base to make the calculation direct.</li></ol><p><br></p><h3>4. ESSENTIAL FORMULAE &amp; METHODS</h3><table table_id="nyu6mi19jz" id="nyu6mi19jz" class=""><tr row_id="g6o93czf4mf" style="width: 100%;"><td table_id="nyu6mi19jz" row_id="g6o93czf4mf" cell_id="f5fqo5p53b" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Concept</strong></p></td><td table_id="nyu6mi19jz" row_id="g6o93czf4mf" cell_id="82f3fafud12" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Formula</strong></p></td></tr><tr row_id="myur83zjqgl" style="width: 100%;"><td table_id="nyu6mi19jz" row_id="myur83zjqgl" cell_id="vbjsfax2uxq" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Exponential Form</span></p></td><td table_id="nyu6mi19jz" row_id="myur83zjqgl" cell_id="fvgsqlz5ac" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$a^x = N$</span></p></td></tr><tr row_id="it4ttj0r92p" style="width: 100%;"><td table_id="nyu6mi19jz" row_id="it4ttj0r92p" cell_id="5vfntzti9f3" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Logarithmic Form</span></p></td><td table_id="nyu6mi19jz" row_id="it4ttj0r92p" cell_id="i7kfaouxe5r" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\log_a N = x$</span></p></td></tr><tr row_id="024q8wlsnmfi" style="width: 100%;"><td table_id="nyu6mi19jz" row_id="024q8wlsnmfi" cell_id="pnefek66xx" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Product Rule</span></p></td><td table_id="nyu6mi19jz" row_id="024q8wlsnmfi" cell_id="oqaezbv3nmb" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\log_a (MN) = \log_a M + \log_a N$</span></p></td></tr><tr row_id="uvs39t6itg" style="width: 100%;"><td table_id="nyu6mi19jz" row_id="uvs39t6itg" cell_id="d4etkib8cgm" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Quotient Rule</span></p></td><td table_id="nyu6mi19jz" row_id="uvs39t6itg" cell_id="po0rpezki2l" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\log_a \left(\frac{M}{N}\right) = \log_a M - \log_a N$</span></p></td></tr><tr row_id="3h5d4grmjzs" style="width: 100%;"><td table_id="nyu6mi19jz" row_id="3h5d4grmjzs" cell_id="1cal4giepvt" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Power Rule</span></p></td><td table_id="nyu6mi19jz" row_id="3h5d4grmjzs" cell_id="og8p7zj80ie" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\log_a (M^n) = n \log_a M$</span></p></td></tr><tr row_id="itt8sxug47c" style="width: 100%;"><td table_id="nyu6mi19jz" row_id="itt8sxug47c" cell_id="b2gwc11e3go" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Change of Base</span></p></td><td table_id="nyu6mi19jz" row_id="itt8sxug47c" cell_id="h79r56wrd7p" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\log_a M = \frac{\log_b M}{\log_b a}$</span></p></td></tr><tr row_id="y1s6x0sq7wj" style="width: 100%;"><td table_id="nyu6mi19jz" row_id="y1s6x0sq7wj" cell_id="sgaqp483fxq" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Reciprocal Rule</span></p></td><td table_id="nyu6mi19jz" row_id="y1s6x0sq7wj" cell_id="gpbxuf8qbe4" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\log_a b = \frac{1}{\log_b a}$</span></p></td></tr><tr row_id="geo4k0a6w64" style="width: 100%;"><td table_id="nyu6mi19jz" row_id="geo4k0a6w64" cell_id="95lo1hcmdh9" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\log_a 1$</span></p></td><td table_id="nyu6mi19jz" row_id="geo4k0a6w64" cell_id="oecpfkd25q" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$0$</span></p></td></tr><tr row_id="cjpk0opux2" style="width: 100%;"><td table_id="nyu6mi19jz" row_id="cjpk0opux2" cell_id="jylrwe8woy" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\log_a a$</span></p></td><td table_id="nyu6mi19jz" row_id="cjpk0opux2" cell_id="ogxpdvkgmpe" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$1$</span></p></td></tr></table><p><br></p><p><br></p><h3>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</h3><p><strong>Type 1:</strong> Convert between exponential and logarithmic forms</p><p><strong>Type 2:</strong> Simplify expressions using log properties</p><p><strong>Type 3:</strong> Evaluate numerical values of logarithmic expressions</p><p><strong>Type 4:</strong> Solve equations involving logarithms</p><p><strong>Type 5:</strong> Apply change of base and reciprocal rules</p><p><strong>Type 6:</strong> Real-world applications (growth, decay, sound intensity, etc.)</p><p><br></p><h3>6. STEP-BY-STEP SOLUTION METHODS</h3><p><strong>Example 1: Convert Exponential to Logarithmic Form</strong></p><p>Given: $3^4 = 81$</p><p><strong>Solution:</strong></p><p>Using the definition of log, $\log_3 81 = 4$.</p><p><br></p><p><strong>Example 2: Simplify $\log_5 125$</strong></p><p><strong>Step 1:</strong> Express 125 as a power of 5.</p><p>$125 = 5^3$</p><p><strong>Step 2:</strong> Apply log rule.</p><p>$\log_5 125 = \log_5 (5^3) = 3 \log_5 5 = 3(1) = 3$</p><p><br></p><p><br></p><p><strong>Example 3: Simplify $\log_{10} 1000$</strong></p><p><strong>Solution:</strong></p><p>Since $1000 = 10^3$,</p><p>$\log_{10} 1000 = \log_{10} (10^3) = 3$</p><p><br></p><p><strong>Example 4: Simplify $\log_2 8 + \log_2 4$</strong></p><p><strong>Step 1:</strong> Apply product rule.</p><p>$\log_2 8 + \log_2 4 = \log_2 (8 \times 4) = \log_2 32$</p><p><strong>Step 2:</strong> Express 32 as a power of 2.</p><p>$32 = 2^5$</p><p>$\Rightarrow \log_2 32 = 5$</p><p><br></p><p><strong>Example 5: Solve for $x$ in $\log_2 (x - 3) = 3$</strong></p><p><strong>Step 1:</strong> Convert to exponential form.</p><p>$x - 3 = 2^3$</p><p><strong>Step 2:</strong> Simplify.</p><p>$x - 3 = 8$</p><p>$\Rightarrow x = 11$</p><p><br></p><h3>7. CONCLUSION</h3><p>Logarithms are essential for simplifying complex calculations involving powers and roots.</p><p>They bridge <strong>exponents and algebra</strong>, making them indispensable in quantitative aptitude, physics, and computer science.</p><p><strong>Key Takeaways:</strong></p><ul><li>Remember $\log_a (MN)$, $\log_a \left(\frac{M}{N}\right)$, and $\log_a (M^n)$ rules.</li><li>Be comfortable switching between exponential and logarithmic forms.</li><li>Master $\log_a b = \frac{1}{\log_b a}$ and $\log_a M = \frac{\log_b M}{\log_b a}$.</li><li>Practice simplification-based and equation-solving problems.</li></ul><p><br></p><p>Practice Question:</p><p>Find the value of $\log_232+\log_5125.$</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b311');

-- 12. Calendar -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b212
