    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Calendar',
    'Calculates day, date, and odd days for given years or centuries', 'MEDIUM', 40, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE id = 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b212');
INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b312', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b212',
    'Calendar Concepts',
    '<h2><strong>1. CONCEPTUAL FOUNDATION</strong></h2><p>The <strong>Calendar</strong> topic deals with finding <strong>days, dates, and relationships between them</strong> based on the mathematical structure of the Gregorian calendar.</p><p> It helps determine:</p><ul><li>The day of the week for any given date.</li><li>The relationship between dates and days.</li><li>How leap years affect the calendar pattern.</li></ul><h3><strong>Real-World Context</strong></h3><p>Calendars are essential in:</p><ul><li>Scheduling and planning tasks.</li><li>Determining anniversaries, birthdays, or historical events.</li><li>Exam and interview aptitude tests for logical-mathematical reasoning.</li></ul><h3><strong>Mathematical Significance</strong></h3><p>Every calendar repeats after a certain interval because of the fixed number of <strong>days in a week (7)</strong> and the periodic occurrence of <strong>leap years (every 4 years except centuries not divisible by 400)</strong>.</p><p><br></p><h3><strong>Prerequisites</strong></h3><ul><li>Knowledge of <strong>division and remainders</strong>.</li><li>Concept of <strong>odd days</strong> (extra days beyond complete weeks).</li><li>Familiarity with leap years and normal years.</li></ul><h2><strong>2. CORE THEORY &amp; PRINCIPLES</strong></h2><h3><strong>2.1 Basic Terms</strong></h3><table table_id="l4gvizsm3os" id="l4gvizsm3os" class=""><tr row_id="hk2x9h20zrb" style="width: 100%;"><td table_id="l4gvizsm3os" row_id="hk2x9h20zrb" cell_id="gl9ys3x3j8l" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Term</strong></p></td><td table_id="l4gvizsm3os" row_id="hk2x9h20zrb" cell_id="f4bk5mao0lt" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Definition</strong></p></td></tr><tr row_id="c7tey70vahr" style="width: 100%;"><td table_id="l4gvizsm3os" row_id="c7tey70vahr" cell_id="zzuxcggfsx8" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Ordinary Year</strong></p></td><td table_id="l4gvizsm3os" row_id="c7tey70vahr" cell_id="w23e13scljt" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">A year with 365 days.</span></p></td></tr><tr row_id="nbums1s8rk" style="width: 100%;"><td table_id="l4gvizsm3os" row_id="nbums1s8rk" cell_id="df38kdqzuwq" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Leap Year</strong></p></td><td table_id="l4gvizsm3os" row_id="nbums1s8rk" cell_id="ei9fbt7alnh" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">A year with 366 days (February has 29 days).</span></p></td></tr><tr row_id="w35kaljgood" style="width: 100%;"><td table_id="l4gvizsm3os" row_id="w35kaljgood" cell_id="0fht5d8dlu8" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Odd Days</strong></p></td><td table_id="l4gvizsm3os" row_id="w35kaljgood" cell_id="m8otoo2zip" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">The number of days left after complete weeks in a given period.</span></p></td></tr><tr row_id="4b3o0pcdce9" style="width: 100%;"><td table_id="l4gvizsm3os" row_id="4b3o0pcdce9" cell_id="phhxz47epjh" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Weekdays</strong></p></td><td table_id="l4gvizsm3os" row_id="4b3o0pcdce9" cell_id="1drt2wfnt9ji" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday.</span></p></td></tr></table><p><br></p><h3><strong>2.2 Leap Year Rule</strong></h3><p>A year is <strong>Leap Year</strong> if:</p><ol><li>It is divisible by 4, <strong>but not by 100</strong>, or</li><li>It is divisible by <strong>400</strong>.</li></ol><p><strong>Examples:</strong></p><ul><li>2000 → Leap Year (divisible by 400)</li><li>1900 → Not a Leap Year (divisible by 100 but not 400)</li><li>2024 → Leap Year (divisible by 4)</li></ul><h3><strong>2.3 Odd Days Concept</strong></h3><table table_id="tm0erak1c0h" id="tm0erak1c0h" class=""><tr row_id="f046gxsu0ko" style="width: 100%;"><td table_id="tm0erak1c0h" row_id="f046gxsu0ko" cell_id="m4kt0cscu9j" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Type of Year</strong></p></td><td table_id="tm0erak1c0h" row_id="f046gxsu0ko" cell_id="dhx6wcmielm" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Days</strong></p></td><td table_id="tm0erak1c0h" row_id="f046gxsu0ko" cell_id="hkcfgrjyvxj" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Weeks</strong></p></td><td table_id="tm0erak1c0h" row_id="f046gxsu0ko" cell_id="r87okz9i3fn" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Odd Days</strong></p></td></tr><tr row_id="4hlzk3a48u2" style="width: 100%;"><td table_id="tm0erak1c0h" row_id="4hlzk3a48u2" cell_id="w7lh9fbxlyf" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Ordinary Year</span></p></td><td table_id="tm0erak1c0h" row_id="4hlzk3a48u2" cell_id="1c20mv88sk2" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">365</span></p></td><td table_id="tm0erak1c0h" row_id="4hlzk3a48u2" cell_id="45ousn94lpp" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">52 weeks + 1 day</span></p></td><td table_id="tm0erak1c0h" row_id="4hlzk3a48u2" cell_id="6utim131se7" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1</span></p></td></tr><tr row_id="sguamc7h99f" style="width: 100%;"><td table_id="tm0erak1c0h" row_id="sguamc7h99f" cell_id="605oiydlgiv" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Leap Year</span></p></td><td table_id="tm0erak1c0h" row_id="sguamc7h99f" cell_id="t6offyzbyzq" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">366</span></p></td><td table_id="tm0erak1c0h" row_id="sguamc7h99f" cell_id="5w5qvo6blu4" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">52 weeks + 2 days</span></p></td><td table_id="tm0erak1c0h" row_id="sguamc7h99f" cell_id="5qtraafl1mt" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">2</span></p></td></tr></table><p><br></p><blockquote><strong>Note:</strong> 100 years = 76 ordinary + 24 leap years = 36524 days = 52 weeks + 100 odd days = 5 odd days.</blockquote><h3><strong>2.4 Day Order Reference</strong></h3><table table_id="2ru5w7ys2wj" id="2ru5w7ys2wj" class=""><tr row_id="xvecth74glk" style="width: 100%;"><td table_id="2ru5w7ys2wj" row_id="xvecth74glk" cell_id="akakm8j9e2i" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Day</strong></p></td><td table_id="2ru5w7ys2wj" row_id="xvecth74glk" cell_id="0n6m5rvhjui" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Number</strong></p></td></tr><tr row_id="8vess3799l" style="width: 100%;"><td table_id="2ru5w7ys2wj" row_id="8vess3799l" cell_id="b8lrigrwbd" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Sunday</span></p></td><td table_id="2ru5w7ys2wj" row_id="8vess3799l" cell_id="f5xhtmwhqzo" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">0</span></p></td></tr><tr row_id="3t7aeh2rpp6" style="width: 100%;"><td table_id="2ru5w7ys2wj" row_id="3t7aeh2rpp6" cell_id="noeg5chy39" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Monday</span></p></td><td table_id="2ru5w7ys2wj" row_id="3t7aeh2rpp6" cell_id="zl4znyp8v0c" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1</span></p></td></tr><tr row_id="fndm4hx4246" style="width: 100%;"><td table_id="2ru5w7ys2wj" row_id="fndm4hx4246" cell_id="zh1kz6rerts" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Tuesday</span></p></td><td table_id="2ru5w7ys2wj" row_id="fndm4hx4246" cell_id="23mh2czg73d" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">2</span></p></td></tr><tr row_id="j9pewmlqkm" style="width: 100%;"><td table_id="2ru5w7ys2wj" row_id="j9pewmlqkm" cell_id="80341x8u81b" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Wednesday</span></p></td><td table_id="2ru5w7ys2wj" row_id="j9pewmlqkm" cell_id="o7q08t4lskk" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td></tr><tr row_id="hvc4kg1undb" style="width: 100%;"><td table_id="2ru5w7ys2wj" row_id="hvc4kg1undb" cell_id="3rei2v9ftzv" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Thursday</span></p></td><td table_id="2ru5w7ys2wj" row_id="hvc4kg1undb" cell_id="ttz6svi26g" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">4</span></p></td></tr><tr row_id="i81ufhxuqb" style="width: 100%;"><td table_id="2ru5w7ys2wj" row_id="i81ufhxuqb" cell_id="4es8cvwox2g" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Friday</span></p></td><td table_id="2ru5w7ys2wj" row_id="i81ufhxuqb" cell_id="dtrbl336sls" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">5</span></p></td></tr><tr row_id="j8ifgffnux" style="width: 100%;"><td table_id="2ru5w7ys2wj" row_id="j8ifgffnux" cell_id="hg2qle4r2su" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Saturday</span></p></td><td table_id="2ru5w7ys2wj" row_id="j8ifgffnux" cell_id="ryy9buglpbi" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">6</span></p></td></tr></table><p><br></p><h3><strong>2.5 Month-wise Odd Days</strong></h3><table table_id="vrs7kegtwgg" id="vrs7kegtwgg" class=""><tr row_id="g71stgqdt78" style="width: 100%;"><td table_id="vrs7kegtwgg" row_id="g71stgqdt78" cell_id="bvh07c2ecwh" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Month</strong></p></td><td table_id="vrs7kegtwgg" row_id="g71stgqdt78" cell_id="lfmgqnw74ah" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Odd Days (Ordinary Year)</strong></p></td><td table_id="vrs7kegtwgg" row_id="g71stgqdt78" cell_id="7phasp4laxi" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Odd Days (Leap Year)</strong></p></td></tr><tr row_id="jldkp6d4mqg" style="width: 100%;"><td table_id="vrs7kegtwgg" row_id="jldkp6d4mqg" cell_id="frd4hrk6y8n" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">January</span></p></td><td table_id="vrs7kegtwgg" row_id="jldkp6d4mqg" cell_id="wbxn6hhdwln" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td><td table_id="vrs7kegtwgg" row_id="jldkp6d4mqg" cell_id="ktjn17h2jxs" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td></tr><tr row_id="qowvycj01qo" style="width: 100%;"><td table_id="vrs7kegtwgg" row_id="qowvycj01qo" cell_id="2rt7qqygrrl" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">February</span></p></td><td table_id="vrs7kegtwgg" row_id="qowvycj01qo" cell_id="9uxlsq3c03" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">0</span></p></td><td table_id="vrs7kegtwgg" row_id="qowvycj01qo" cell_id="64n77yafb9a" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1</span></p></td></tr><tr row_id="xfhxhjqd23q" style="width: 100%;"><td table_id="vrs7kegtwgg" row_id="xfhxhjqd23q" cell_id="yb9d95dw1fe" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">March</span></p></td><td table_id="vrs7kegtwgg" row_id="xfhxhjqd23q" cell_id="8imyum96gw5" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td><td table_id="vrs7kegtwgg" row_id="xfhxhjqd23q" cell_id="xkaj848ui7l" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td></tr><tr row_id="sb1u73rlivn" style="width: 100%;"><td table_id="vrs7kegtwgg" row_id="sb1u73rlivn" cell_id="dr91dl3fbw" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">April</span></p></td><td table_id="vrs7kegtwgg" row_id="sb1u73rlivn" cell_id="yiun6m0jpap" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">2</span></p></td><td table_id="vrs7kegtwgg" row_id="sb1u73rlivn" cell_id="eckohb7jlj5" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">2</span></p></td></tr><tr row_id="0wjia8q7jwg" style="width: 100%;"><td table_id="vrs7kegtwgg" row_id="0wjia8q7jwg" cell_id="qfuubtc7him" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">May</span></p></td><td table_id="vrs7kegtwgg" row_id="0wjia8q7jwg" cell_id="cdvrxpftfvg" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td><td table_id="vrs7kegtwgg" row_id="0wjia8q7jwg" cell_id="xiee8j7hjuq" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td></tr><tr row_id="kkpkqudwken" style="width: 100%;"><td table_id="vrs7kegtwgg" row_id="kkpkqudwken" cell_id="5o0ywbktmwm" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">June</span></p></td><td table_id="vrs7kegtwgg" row_id="kkpkqudwken" cell_id="jgol8v1xebs" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">2</span></p></td><td table_id="vrs7kegtwgg" row_id="kkpkqudwken" cell_id="ue8mdjlzw9" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">2</span></p></td></tr><tr row_id="2nupk7veznj" style="width: 100%;"><td table_id="vrs7kegtwgg" row_id="2nupk7veznj" cell_id="p3v7p9wiq1i" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">July</span></p></td><td table_id="vrs7kegtwgg" row_id="2nupk7veznj" cell_id="lo1ov1qgsrc" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td><td table_id="vrs7kegtwgg" row_id="2nupk7veznj" cell_id="e6n7olyaw3s" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td></tr><tr row_id="trn8383mxk8" style="width: 100%;"><td table_id="vrs7kegtwgg" row_id="trn8383mxk8" cell_id="l2ueg97gwe" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">August</span></p></td><td table_id="vrs7kegtwgg" row_id="trn8383mxk8" cell_id="ifhddvh9zu" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td><td table_id="vrs7kegtwgg" row_id="trn8383mxk8" cell_id="hicooqhn81l" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td></tr><tr row_id="mz7vfweakr" style="width: 100%;"><td table_id="vrs7kegtwgg" row_id="mz7vfweakr" cell_id="pweg75gydsk" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">September</span></p></td><td table_id="vrs7kegtwgg" row_id="mz7vfweakr" cell_id="oydxqbd7uk" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">2</span></p></td><td table_id="vrs7kegtwgg" row_id="mz7vfweakr" cell_id="t1hqdri091i" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">2</span></p></td></tr><tr row_id="523ugnkx2ju" style="width: 100%;"><td table_id="vrs7kegtwgg" row_id="523ugnkx2ju" cell_id="qgmbc27q2ic" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">October</span></p></td><td table_id="vrs7kegtwgg" row_id="523ugnkx2ju" cell_id="hyim09rvd0d" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td><td table_id="vrs7kegtwgg" row_id="523ugnkx2ju" cell_id="9792avxuqdf" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td></tr><tr row_id="g8nroazi3j" style="width: 100%;"><td table_id="vrs7kegtwgg" row_id="g8nroazi3j" cell_id="vizq0iymgcb" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">November</span></p></td><td table_id="vrs7kegtwgg" row_id="g8nroazi3j" cell_id="1e4gl6j6vaa" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">2</span></p></td><td table_id="vrs7kegtwgg" row_id="g8nroazi3j" cell_id="9nbbaw84n8n" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">2</span></p></td></tr><tr row_id="u9zox8lru5" style="width: 100%;"><td table_id="vrs7kegtwgg" row_id="u9zox8lru5" cell_id="r34vujrxlmj" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">December</span></p></td><td table_id="vrs7kegtwgg" row_id="u9zox8lru5" cell_id="um7aok5n8vi" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td><td table_id="vrs7kegtwgg" row_id="u9zox8lru5" cell_id="tfdzp0rlqs" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td></tr></table><p><br></p><h2><strong>3. MAGIC SHORTCUTS</strong></h2><ol><li><strong>Shortcut 1: Leap Year Check</strong></li></ol><ul><li class="ql-indent-1">If the year is divisible by <strong>400</strong> → Leap Year.</li><li class="ql-indent-1">Else if divisible by <strong>100</strong> → Not Leap Year.</li><li class="ql-indent-1">Else if divisible by <strong>4</strong> → Leap Year.</li><li class="ql-indent-1">Else → Not Leap Year.</li></ul><ol><li><strong>Shortcut 2: Odd Days of a Century</strong></li></ol><ul><li class="ql-indent-1">100 years → 5 odd days</li><li class="ql-indent-1">200 years → 3 odd days</li><li class="ql-indent-1">300 years → 1 odd day</li><li class="ql-indent-1">400 years → 0 odd day (calendar repeats)</li></ul><ol><li><strong>Shortcut 3: Day Difference Rule</strong></li></ol><ul><li class="ql-indent-1">Each <strong>ordinary year adds +1 day</strong> to the weekday.</li><li class="ql-indent-1">Each <strong>leap year adds +2 days</strong> to the weekday.</li></ul><ol><li><strong>Shortcut 4: Finding Day of Any Date</strong></li></ol><ul><li>Formula:</li><li class="ql-indent-1"> $\text{Day} = (\text{Odd days of complete years} + \text{Odd days of months} + \text{Date}) \mod 7$</li></ul><h2><strong>4. ESSENTIAL FORMULAE &amp; METHODS</strong></h2><table table_id="n4jidst7v7k" id="n4jidst7v7k" class=""><tr row_id="delip15e3zp" style="width: 100%;"><td table_id="n4jidst7v7k" row_id="delip15e3zp" cell_id="5kdsof2mpjm" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Concept</strong></p></td><td table_id="n4jidst7v7k" row_id="delip15e3zp" cell_id="eouqtp6p0bq" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Formula</strong></p></td></tr><tr row_id="8ahvt985ypa" style="width: 100%;"><td table_id="n4jidst7v7k" row_id="8ahvt985ypa" cell_id="y8d1azjm39d" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Odd days in 100 years</span></p></td><td table_id="n4jidst7v7k" row_id="8ahvt985ypa" cell_id="5lqwaa7gkp" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">5</span></p></td></tr><tr row_id="5hs9wczh2oj" style="width: 100%;"><td table_id="n4jidst7v7k" row_id="5hs9wczh2oj" cell_id="9nunin6ykir" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Odd days in 200 years</span></p></td><td table_id="n4jidst7v7k" row_id="5hs9wczh2oj" cell_id="k87xn86siw" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">3</span></p></td></tr><tr row_id="te4eb2yntva" style="width: 100%;"><td table_id="n4jidst7v7k" row_id="te4eb2yntva" cell_id="7463j8wu8o5" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Odd days in 300 years</span></p></td><td table_id="n4jidst7v7k" row_id="te4eb2yntva" cell_id="mnus7l18g4" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1</span></p></td></tr><tr row_id="90q914eo1rs" style="width: 100%;"><td table_id="n4jidst7v7k" row_id="90q914eo1rs" cell_id="kptfo75ia7c" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Odd days in 400 years</span></p></td><td table_id="n4jidst7v7k" row_id="90q914eo1rs" cell_id="hdy8i2x6aaj" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">0</span></p></td></tr><tr row_id="2y26mmwfyak" style="width: 100%;"><td table_id="n4jidst7v7k" row_id="2y26mmwfyak" cell_id="yevj7zm3x3g" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Leap year check</span></p></td><td table_id="n4jidst7v7k" row_id="2y26mmwfyak" cell_id="6cuzhqk3pxh" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Divisible by 4, not 100 unless divisible by 400</span></p></td></tr><tr row_id="mk0atwuzmn" style="width: 100%;"><td table_id="n4jidst7v7k" row_id="mk0atwuzmn" cell_id="bquk2b7ud86" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Day of given date</span></p></td><td table_id="n4jidst7v7k" row_id="mk0atwuzmn" cell_id="lvbyqwxxxo7" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\text{Total odd days} \mod 7$</span></p></td></tr><tr row_id="to9pxwhij5h" style="width: 100%;"><td table_id="n4jidst7v7k" row_id="to9pxwhij5h" cell_id="3ox8rgbrf3v" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Reference day order</span></p></td><td table_id="n4jidst7v7k" row_id="to9pxwhij5h" cell_id="02lw64dwiskh" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Sunday = 0, Monday = 1, … Saturday = 6</span></p></td></tr></table><p><br></p><h2><strong>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</strong></h2><h3><strong>Type 1: Leap Year Identification</strong></h3><p>Problems asking whether a year is a leap year or not.</p><p><br></p><h3><strong>Type 2: Counting Odd Days</strong></h3><p>Finding the number of odd days in a given number of years.</p><p><br></p><h3><strong>Type 3: Finding Day of the Week</strong></h3><p>Determining which day corresponds to a particular date.</p><p><br></p><h3><strong>Type 4: Calendar Matching</strong></h3><p>Identifying which year will have the same calendar as a given year.</p><p><br></p><h3><strong>Type 5: Day Relationships</strong></h3><p>Finding what day it was or will be after a certain number of days.</p><p><br></p><h2><strong>6. STEP-BY-STEP SOLUTION METHODS</strong></h2><h3><strong>Example 1: Leap Year</strong></h3><p><strong>Question:</strong> Is 1900 a leap year?</p><p> <strong>Solution:</strong></p><ul><li>1900 ÷ 100 → true, but not divisible by 400.</li><li> <strong>Answer:</strong> Not a leap year.</li></ul><h3><strong>Example 2: Odd Days in 200 Years</strong></h3><p><strong>Solution:</strong></p><p> From table → 200 years have <strong>3 odd days</strong>.</p><p><br></p><h3><strong>Example 3: Find the day on 15th August 1947</strong></h3><p><strong>Step 1:</strong> Break into parts</p><ul><li>Century = 1900 → 100 years = 5 odd days</li><li>Years after 1900 = 47 years</li><li> → 47 ordinary years = 47 odd days</li><li> → 11 leap years = 11 extra odd days</li><li> → Total = 47 + 11 = 58 odd days = 2 odd days (since 58 mod 7 = 2)</li></ul><p><strong>Step 2:</strong> Month-wise odd days up to July (ordinary year)</p><p> = 3 + 0 + 3 + 2 + 3 + 2 + 3 = 16 → 16 mod 7 = 2 odd days.</p><p><strong>Step 3:</strong> Add date = 15 → 15 mod 7 = 1</p><p> Total odd days = 5 + 2 + 2 + 1 = 10 → 10 mod 7 = 3.</p><p><strong>Step 4:</strong> 3 corresponds to <strong>Friday</strong>.</p><p> <strong>Answer:</strong> 15 August 1947 was a <strong>Friday</strong>.</p><p><br></p><h3><strong>Example 4: Find which year has the same calendar as 2017</strong></h3><p><strong>Solution:</strong></p><p> 2017 → Ordinary year → adds +1 odd day.</p><p> Keep adding years until total odd days = 0 or multiple of 7.</p><p> 2017 + 11 = 2028 gives same calendar.</p><p> <strong>Answer:</strong> 2028.</p><h3><strong>Example 5: Day after ‘x’ days</strong></h3><p><strong>Question:</strong> If today is Monday, what day will it be after 100 days?</p><p> $\text{100 mod 7} = 2 \Rightarrow$ Monday + 2 days = <strong>Wednesday</strong>.</p><p><br></p><h2><strong>7. CONCLUSION</strong></h2><p>The <strong>Calendar</strong> topic combines logical and modular arithmetic to determine days and dates accurately.</p><p> It emphasizes understanding <strong>odd days</strong>, <strong>leap years</strong>, and the <strong>cyclic nature</strong> of weeks.</p><p><br></p><h3><strong>Key Insights</strong></h3><ul><li>Calendar repeats every <strong>400 years</strong>.</li><li>Odd days determine the weekday directly.</li><li>Leap year rule is crucial to accurate computation.</li><li>Practicing month-wise and year-wise patterns leads to mastery.</li></ul><h3><strong>Mastery Indicators</strong></h3><ul><li>Can identify leap years quickly.</li><li>Can find day of any date within 1 minute.</li><li>Can recognize repeated calendars.</li><li>Understands odd-day modular arithmetic fluently.</li></ul><p><br></p><p>Practice Question:</p><p>Which of the following years is a leap year?</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b312');

