INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b316', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b216',
    'Time & Distance Concepts',
    '<h2>1. CONCEPTUAL FOUNDATION</h2><p><strong>Time and Distance</strong> deals with the relationship between how far an object travels (distance), how fast it moves (speed), and how long it takes (time).</p><p>This topic forms the <strong>core base</strong> for advanced applications like <strong>Boats &amp; Streams</strong>, <strong>Trains</strong>, <strong>Races</strong>, and <strong>Circular Tracks</strong>.</p><p><strong>Real-Life Connection:</strong></p><p> Everyday commuting, travel planning, speed analysis, and logistics all depend on the same fundamental Time–Distance relationship.</p><p><strong>Basic Relation:</strong></p><p> Distance = Speed × Time</p><p><br></p><h2>2. CORE THEORY &amp; PRINCIPLES</h2><ol><li><strong>Basic Formulae:</strong></li></ol><ul><li class="ql-indent-1">Distance = Speed × Time</li><li class="ql-indent-1">Speed = Distance / Time</li><li class="ql-indent-1">Time = Distance / Speed</li></ul><ol><li><strong>Units:</strong></li></ol><ul><li class="ql-indent-1">If Distance is in km and Time in hours → Speed in km/hr</li><li class="ql-indent-1">If Distance is in meters and Time in seconds → Speed in m/s</li><li class="ql-indent-1">Conversion: 1 km/hr = 5/18 m/s or 1 m/s = 18/5 km/hr</li></ul><ol><li><strong>Relative Speed:</strong></li></ol><ul><li class="ql-indent-1">When two bodies move <strong>in the same direction</strong>, Relative Speed = (Speed₁ – Speed₂)</li><li class="ql-indent-1">When they move <strong>in opposite directions</strong>, Relative Speed = (Speed₁ + Speed₂)</li></ul><ol><li><strong>Average Speed:</strong></li></ol><ul><li class="ql-indent-1">Average Speed = Total Distance / Total Time</li><li>When equal distances are covered at two speeds S₁ and S₂:</li><li class="ql-indent-1"> Average Speed = (2S₁S₂) / (S₁ + S₂)</li></ul><ol><li><strong>Speed-Time Relationship:</strong></li></ol><ul><li class="ql-indent-1">If speed increases, time decreases (inversely proportional).</li><li class="ql-indent-1">If speed decreases by x%, time increases by [x / (100 – x)]%.</li></ul><p><br></p><h2>3. MAGIC SHORTCUTS</h2><ol><li><strong>Shortcut for Equal Distance:</strong></li></ol><ul><li class="ql-indent-1">Average Speed = (2S₁S₂)/(S₁ + S₂)</li></ul><ol><li><strong>Shortcut for Equal Time:</strong></li></ol><ul><li class="ql-indent-1">Average Speed = (S₁ + S₂)/2</li></ul><ol><li><strong>Conversion Shortcuts:</strong></li></ol><ul><li class="ql-indent-1">km/hr → m/s: multiply by 5/18</li><li class="ql-indent-1">m/s → km/hr: multiply by 18/5</li></ul><ol><li><strong>Shortcut for Late/Early Problems:</strong></li></ol><ul><li class="ql-indent-1">Time Difference = Distance × (1/S₁ – 1/S₂)</li></ul><ol><li><strong>Speed Change Problems:</strong></li></ol><ul><li>% Change in Speed ⇒ Time changes inversely</li><li> If speed ↑ by x%, then time ↓ by (x / (100 + x)) × 100%</li><li class="ql-indent-1"> If speed ↓ by x%, then time ↑ by (x / (100 – x)) × 100%</li></ul><ol><li><strong>Round Trip Shortcut (Same Path Forth &amp; Back):</strong></li></ol><ul><li>If distances are equal but speeds differ:</li><li class="ql-indent-1"> Average Speed = (2S₁S₂)/(S₁ + S₂)</li></ul><ol><li><strong>Relative Speed Trick:</strong></li></ol><ul><li class="ql-indent-1">Meeting Time (same direction) = Distance Difference / Relative Speed</li><li class="ql-indent-1">Meeting Time (opposite direction) = Total Distance / Relative Speed</li></ul><ol><li><strong>Time Saved Shortcut:</strong></li></ol><ul><li class="ql-indent-1">Time Saved = Distance × [(1/S₂) – (1/S₁)]</li></ul><p><br></p><h2><strong style="background-color: transparent; color: rgb(0, 0, 0);">4. ESSENTIAL FORMULAE &amp; METHODS</strong></h2><table table_id="o1m9yt5wus" id="o1m9yt5wus" class=""><tr row_id="j7zhq03ii9r" style="width: 100%;"><td table_id="o1m9yt5wus" row_id="j7zhq03ii9r" cell_id="23gh4t10fbi" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Concept</strong></p></td><td table_id="o1m9yt5wus" row_id="j7zhq03ii9r" cell_id="xmny4es0i9" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Formula</strong></p></td><td table_id="o1m9yt5wus" row_id="j7zhq03ii9r" cell_id="edcz5a37yqn" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Description</strong></p></td></tr><tr row_id="osvv77p83xq" style="width: 100%;"><td table_id="o1m9yt5wus" row_id="osvv77p83xq" cell_id="bgavz9s3vw" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Distance</span></p></td><td table_id="o1m9yt5wus" row_id="osvv77p83xq" cell_id="qu11qwd18w" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">D = S × T</span></p></td><td table_id="o1m9yt5wus" row_id="osvv77p83xq" cell_id="669v22ipn23" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Product of speed and time</span></p></td></tr><tr row_id="7umxnz0n3n8" style="width: 100%;"><td table_id="o1m9yt5wus" row_id="7umxnz0n3n8" cell_id="3oc8g6satsq" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Speed</span></p></td><td table_id="o1m9yt5wus" row_id="7umxnz0n3n8" cell_id="ehsps9bzprp" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">S = D / T</span></p></td><td table_id="o1m9yt5wus" row_id="7umxnz0n3n8" cell_id="ipuf67bkox" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Speed = distance per unit time</span></p></td></tr><tr row_id="eohd7eu30js" style="width: 100%;"><td table_id="o1m9yt5wus" row_id="eohd7eu30js" cell_id="coudxaz2837" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Time</span></p></td><td table_id="o1m9yt5wus" row_id="eohd7eu30js" cell_id="zaul6zvrwuh" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">T = D / S</span></p></td><td table_id="o1m9yt5wus" row_id="eohd7eu30js" cell_id="agq2nhkkuzt" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Time = distance divided by speed</span></p></td></tr><tr row_id="wbjout498ks" style="width: 100%;"><td table_id="o1m9yt5wus" row_id="wbjout498ks" cell_id="3dryqxkz1vy" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Relative Speed (same direction)</span></p></td><td table_id="o1m9yt5wus" row_id="wbjout498ks" cell_id="z7glaf3j99" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">S₁ – S₂</span></p></td><td table_id="o1m9yt5wus" row_id="wbjout498ks" cell_id="3meqmb56xyz" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Difference of speeds</span></p></td></tr><tr row_id="zj1etypp5j" style="width: 100%;"><td table_id="o1m9yt5wus" row_id="zj1etypp5j" cell_id="9wu6j0jism" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Relative Speed (opposite direction)</span></p></td><td table_id="o1m9yt5wus" row_id="zj1etypp5j" cell_id="7vxpc8eo1ec" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">S₁ + S₂</span></p></td><td table_id="o1m9yt5wus" row_id="zj1etypp5j" cell_id="o877vu8x35s" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Sum of speeds</span></p></td></tr><tr row_id="3orqzi10x4a" style="width: 100%;"><td table_id="o1m9yt5wus" row_id="3orqzi10x4a" cell_id="3lxfnoo99c1" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Average Speed (equal distance)</span></p></td><td table_id="o1m9yt5wus" row_id="3orqzi10x4a" cell_id="humx9auvlbo" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">(2S₁S₂)/(S₁ + S₂)</span></p></td><td table_id="o1m9yt5wus" row_id="3orqzi10x4a" cell_id="vnus9hpjoxh" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Harmonic mean of speeds</span></p></td></tr><tr row_id="o9ipadqizus" style="width: 100%;"><td table_id="o1m9yt5wus" row_id="o9ipadqizus" cell_id="iiaealilude" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Average Speed (unequal distance)</span></p></td><td table_id="o1m9yt5wus" row_id="o9ipadqizus" cell_id="bfcodtepd2n" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">(Total Distance) / (Total Time)</span></p></td><td table_id="o1m9yt5wus" row_id="o9ipadqizus" cell_id="nnvtx35eyhb" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">For general case</span></p></td></tr><tr row_id="fah1v3zia6" style="width: 100%;"><td table_id="o1m9yt5wus" row_id="fah1v3zia6" cell_id="5z2japfh01w" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">% Relation</span></p></td><td table_id="o1m9yt5wus" row_id="fah1v3zia6" cell_id="t5liqfqzufs" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Speed₁ × Time₁ = Speed₂ × Time₂</span></p></td><td table_id="o1m9yt5wus" row_id="fah1v3zia6" cell_id="t8yiz1uyy7" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">When distance is constant</span></p></td></tr><tr row_id="x834xtrydd" style="width: 100%;"><td table_id="o1m9yt5wus" row_id="x834xtrydd" cell_id="taz1vimt1dj" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Conversion</span></p></td><td table_id="o1m9yt5wus" row_id="x834xtrydd" cell_id="4b2jhxhf1f9" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1 km/hr = 5/18 m/s</span></p></td><td table_id="o1m9yt5wus" row_id="x834xtrydd" cell_id="99v9qjay5n6" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Unit conversion</span></p></td></tr><tr row_id="7hn5mlxm6e9" style="width: 100%;"><td table_id="o1m9yt5wus" row_id="7hn5mlxm6e9" cell_id="0tgqcw2ycs3e" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Time Difference</span></p></td><td table_id="o1m9yt5wus" row_id="7hn5mlxm6e9" cell_id="zgmuuq38qn" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">ΔT = D × (1/S₁ – 1/S₂)</span></p></td><td table_id="o1m9yt5wus" row_id="7hn5mlxm6e9" cell_id="u0gqdpn76b" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Used in early/late problems</span></p></td></tr></table><p><br></p><h2>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</h2><p><strong>Model 1: Direct Formula Problems</strong></p><p> – Finding Distance, Speed, or Time using the basic relation.</p><p><strong>Model 2: Unit Conversion Problems</strong></p><p> – Converting km/hr to m/s and vice versa before calculation.</p><p><strong>Model 3: Relative Speed Problems</strong></p><p> – Two objects moving in same or opposite directions, or meeting each other after a certain time.</p><p><strong>Model 4: Average Speed Problems</strong></p><p> – Journeys with different speeds or distances; same path twice.</p><p><strong>Model 5: Early/Late Arrival Problems</strong></p><p> – Speed adjustment resulting in reaching earlier or later.</p><p><strong>Model 6: Ratio of Speeds and Times</strong></p><p> – When distances or times are in given ratios, find one variable.</p><p><strong>Model 7: Circular Track Problems</strong></p><p> – Two or more people starting from same or opposite points on a circular path.</p><p><strong>Model 8: Variable Speed or Multi-Part Journey</strong></p><p> – Distance covered in different parts of journey with different speeds.</p><p><br></p><h2>6. STEP-BY-STEP SOLUTION METHODS</h2><h3>Example 1:</h3><p>A car travels 180 km in 3 hours. Find its speed.</p><p> Speed = Distance / Time = 180 / 3 = 60 km/hr</p><p> <strong>Answer: 60 km/hr</strong></p><h3>Example 2:</h3><p>Convert 90 km/hr into m/s.</p><p> = 90 × (5/18) = 25 m/s</p><p> <strong>Answer: 25 m/s</strong></p><h3>Example 3:</h3><p>A bus travels at 60 km/hr and returns at 40 km/hr. Find average speed.</p><p> Average Speed = (2S₁S₂)/(S₁ + S₂) = (2 × 60 × 40)/(60 + 40) = 4800/100 = 48 km/hr</p><p> <strong>Answer: 48 km/hr</strong></p><h3>Example 5:</h3><p>A person reaches office 10 minutes late when traveling at 40 km/hr but 10 minutes early at 60 km/hr.</p><p> Find the distance.</p><p> Difference in time = 20 minutes = 1/3 hr</p><p> Distance = (S₁ × S₂ × ΔT)/(S₂ – S₁) = (40 × 60 × 1/3)/(60 – 40) = (2400/3)/20 = 40 km</p><p> <strong>Answer: 40 km</strong></p><h3>Example 6:</h3><p>Two persons start from the same point and move in opposite directions at 4 m/s and 6 m/s.</p><p> Find distance between them after 10 seconds.</p><p> Relative Speed = 4 + 6 = 10 m/s</p><p> Distance = 10 × 10 = 100 m</p><p> <strong>Answer: 100 m</strong></p><p><br></p><h2>7. CONCLUSION</h2><p><strong>Concept Recap:</strong></p><ul><li>Always connect <strong>Speed, Distance, and Time</strong>: D = S × T</li><li><strong>Speed and Time are inversely related</strong> when distance is constant.</li><li>For <strong>same distance</strong>, use harmonic mean formula for average speed.</li><li>Always convert units properly before calculations.</li><li><strong>Relative speed</strong> is key for moving objects (trains, boats, people).</li></ul><p><strong>Speed Tips for Exams:</strong></p><ul><li>Write down S, D, and T values clearly before substitution.</li><li>Practice relative speed and average speed models thoroughly.</li><li>Memorize unit conversions perfectly — most mistakes occur there.</li><li>Shortcut for early/late problems is highly time-saving in exams.</li></ul><p><br></p><p><strong>Practice Question:</strong></p><p>Two trains are moving in opposite directions at 45 km/hr and 63 km/hr.</p><p>Find their relative speed in m/s.</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b316');

-- 17. Pipes & Cisterns -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b217
INSERT INTO topics (id, subject_id, unit_id, name, description, difficulty, display_order, is_active, created_at, updated_at)
SELECT 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b217', '55555555-5555-5555-5555-555555555501',
    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Pipes & Cisterns',
    'Similar to time and work, applied to filling and emptying tanks with inlet and outlet pipes', 'MEDIUM', 45, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE id = 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b217');
INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b317', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b217',
    'Pipes & Cisterns Concepts',
    '<h4>1. CONCEPTUAL FOUNDATION</h4><p>The <em>Pipes and Cisterns</em> topic is a direct application of <em>Time and Work</em>. Here, instead of people doing work, pipes (or taps) fill or empty tanks. The same logic applies — rate of work (filling or emptying per hour) × time = total work (or total capacity of the tank).</p><p><strong>Core Idea:</strong></p><ul><li>A pipe that fills a tank is called an <strong>inlet</strong>.</li><li>A pipe that empties a tank is called an <strong>outlet</strong>.</li><li>The net rate of work is determined by adding or subtracting the rates of the pipes working together.</li></ul><p><br></p><h3>2. CORE THEORY &amp; PRINCIPLES</h3><ol><li><strong>Basic Relation:</strong></li></ol><ul><li class="ql-indent-1">If a pipe fills a tank in <em>x</em> hours, part of the tank filled in 1 hour = $1/x$.</li><li class="ql-indent-1">If another pipe empties it in <em>y</em> hours, part of the tank emptied in 1 hour = $1/y$.</li></ul><ol><li><strong>Net Work Rate:</strong></li></ol><ul><li class="ql-indent-1">If both inlet and outlet are open, net part filled in one hour = $(1/x - 1/y)$ (if outlet is slower, net fill happens).</li><li class="ql-indent-1">If outlet is faster, the tank is emptied.</li></ul><ol><li><strong>Total Time Calculation:</strong></li></ol><ul><li>For two inlet pipes A and B,</li><li> $1/T = 1/x + 1/y$</li><li class="ql-indent-1"> → $T = \dfrac{xy}{x + y}$</li></ul><ol><li><strong>For Inlet + Outlet Together:</strong></li></ol><ul><li class="ql-indent-1">$1/T = 1/x - 1/y$ (if filling still happens)</li></ul><ol><li><strong>Partial Time (Tank Not Empty/Full):</strong></li></ol><ul><li class="ql-indent-1">If the tank has <em>k%</em> of water already or partially filled, adjust the total work to remaining capacity.</li></ul><ol><li><strong>Cistern Overflow Condition:</strong></li></ol><ul><li class="ql-indent-1">If outlet is closed before completion, work done till that time is subtracted or added as per net flow.</li></ul><h3>3. MAGIC SHORTCUTS</h3><ol><li><strong>Shortcut 1 – Combined Rate Trick:</strong></li></ol><ul><li class="ql-indent-1">If a pipe fills in <em>x</em> hr and another empties in <em>y</em> hr, and <em>x &lt; y</em>, then time to fill the tank = $\dfrac{xy}{y - x}$.</li></ul><ol><li><strong>Shortcut 2 – Alternate Filling and Emptying:</strong></li></ol><ul><li class="ql-indent-1">For alternate hours or minutes, calculate total work done in one complete cycle (1 fill + 1 empty) and divide total work accordingly.</li></ul><ol><li><strong>Shortcut 3 – Efficiency Ratio Method:</strong></li></ol><ul><li class="ql-indent-1">Filling and emptying efficiencies are inversely proportional to their times.</li></ul><ol><li><strong>Shortcut 4 – Partial Filling Cases:</strong></li></ol><ul><li class="ql-indent-1">If 2/3 of a tank is full, then remaining = 1/3. Multiply this fraction by total time to find additional time required.</li></ul><ol><li><strong>Shortcut 5 – LCM Shortcut:</strong></li></ol><ul><li class="ql-indent-1">When multiple pipes work together, take LCM of times as total capacity for easy unit calculation.</li></ul><p><br></p><h3>4. ESSENTIAL FORMULAE &amp; METHODS</h3><ol><li><strong>Work done by inlet per hour:</strong> $1/x$</li><li><strong>Work done by outlet per hour:</strong> $-1/y$</li><li><strong>Net work rate:</strong> $(1/x ± 1/y)$ depending on operation</li><li><strong>Total time to fill tank:</strong> $T = \dfrac{xy}{y - x}$ (for inlet &amp; outlet)</li><li><strong>If both inlets fill:</strong> $T = \dfrac{xy}{x + y}$</li><li><strong>If 3 pipes (A, B, C):</strong> $1/T = 1/x + 1/y + 1/z$</li><li><strong>Fraction filled in ‘t’ hours:</strong> $t/T$</li><li><strong>Work left or done ratio:</strong> Work left = $1 - \text{(work done fraction)}$</li></ol><p><br></p><h3>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</h3><ol><li><strong>Type 1: Simple Inlet or Outlet Problems</strong></li></ol><ul><li class="ql-indent-1">Only one pipe filling or emptying.</li></ul><ol><li><strong>Type 2: Two Pipes (Both Inlets)</strong></li></ol><ul><li class="ql-indent-1">Pipes filling simultaneously.</li></ul><ol><li><strong>Type 3: Inlet and Outlet Together</strong></li></ol><ul><li class="ql-indent-1">One fills and another empties.</li></ul><ol><li><strong>Type 4: Pipes Opened/Closed After Some Time</strong></li></ol><ul><li class="ql-indent-1">Net filling or emptying rate changes after certain duration.</li></ul><ol><li><strong>Type 5: Partial Tank Problems</strong></li></ol><ul><li class="ql-indent-1">Tank already filled or partially empty.</li></ul><ol><li><strong>Type 6: Alternate Filling &amp; Emptying</strong></li></ol><ul><li class="ql-indent-1">Pipes operate alternately in equal or unequal time intervals.</li></ul><ol><li><strong>Type 7: Leakage Problems</strong></li></ol><ul><li class="ql-indent-1">Leakage acts as an outlet reducing effective filling rate.</li></ul><ol><li><strong>Type 8: Cistern Overflow / Multiple Pipe Combinations</strong></li></ol><ul><li class="ql-indent-1">Complex multi-stage operations with closing/opening of valves.</li></ul><p><br></p><h3>6. STEP-BY-STEP SOLUTION METHODS</h3><p><strong>Example 2:</strong></p><p> A pipe can fill a tank in 12 hours, and an outlet can empty it in 20 hours. If both are open together, find the time to fill the tank.</p><p><strong>Step 1:</strong> Filling rate = 1/12, emptying rate = 1/20</p><p> <strong>Step 2:</strong> Net rate = 1/12 – 1/20 = (5 – 3)/60 = 2/60 = 1/30</p><p> <strong>Step 3:</strong> Total time = 30 hours.</p><p><strong>Example 3:</strong></p><p> A can fill a tank in 8 hours, B in 12 hours. C is a leakage that can empty the tank in 24 hours. Find the time required to fill when all are open.</p><p><strong>Step 1:</strong> Net rate = 1/8 + 1/12 – 1/24</p><p> = (3 + 2 – 1)/24 = 4/24 = 1/6</p><p> <strong>Step 2:</strong> Time required = 6 hours.</p><p><br></p><h3>7. CONCLUSION</h3><p>Pipes and Cisterns problems are real-life applications of <em>Time and Work</em> principles involving filling and emptying actions. Understanding whether a pipe contributes positively or negatively to the total work is the key.</p><p><strong>Key Points to Remember:</strong></p><ul><li>Treat filling pipes as positive and emptying pipes as negative.</li><li>Combine their rates for simultaneous operation.</li><li>Always work with <em>fraction of tank filled per hour/minute</em>.</li><li>For alternate or multi-stage problems, compute effective work in each phase.</li></ul><p>By practicing rate-based thinking and proportional reasoning, students can easily master all types of problems under this topic.</p><p><br></p><p><strong>Practice Question:</strong></p><p>A pipe can fill a tank in 10 hours and another can fill it in 15 hours. How long will it take if both are opened together?</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b317');

-- 18. Partnership -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b218
