INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b318', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b218',
    'Partnership Concepts',
    '<h2>1. CONCEPTUAL FOUNDATION</h2><p><strong>Definition:</strong></p><p> A <em>partnership</em> is a business arrangement where two or more persons invest money (and sometimes time or effort) to carry on a business and share its profits or losses in an agreed ratio.</p><p><strong>Purpose:</strong></p><p> It tests your understanding of proportional investment, time, and profit relationships — a blend of ratio and percentage concepts. It’s frequently asked in competitive exams due to its real-world business relevance.</p><p><strong>Key Idea:</strong></p><p> The share of each partner in profit or loss is directly proportional to the product of:</p><ul><li>Amount invested (Capital)</li><li>Time period for which the capital is invested</li></ul><p>That is, Profit ∝ (Capital × Time)</p><p><br></p><h2>2. CORE THEORY &amp; PRINCIPLES</h2><ol><li><strong>Basic Principle:</strong></li><li> If two or more partners invest different amounts for different periods, then:</li></ol><ul><li class="ql-indent-1">Profit (or loss) is divided in the ratio of their <em>Capital × Time</em>.</li></ul><ol><li>For example,</li><li> A invests ₹6,000 for 6 months,</li><li> B invests ₹8,000 for 9 months.</li><li> Profit ratio = (6,000 × 6) : (8,000 × 9) = 36,000 : 72,000 = 1 : 2.</li><li><strong>Types of Partnership:</strong></li></ol><ul><li class="ql-indent-1"><strong>Simple Partnership:</strong> All partners invest money for the same period.</li><li class="ql-indent-1"><strong>Compound Partnership:</strong> Investments are made for different time periods.</li></ul><ol><li><strong>Working Partner vs Sleeping Partner:</strong></li></ol><ul><li class="ql-indent-1"><strong>Working Partner:</strong> Actively involved in business and gets additional remuneration (salary, commission, etc.).</li><li class="ql-indent-1"><strong>Sleeping Partner:</strong> Only invests capital, not involved in management.</li></ul><ol><li><strong>Adjustment for Salary or Commission:</strong></li><li> If a working partner receives salary or commission, it is deducted from the total profit before dividing the remaining profit among all partners.</li></ol><p><br></p><h2>3. MAGIC SHORTCUTS</h2><ol><li><strong>Profit Share Ratio:</strong></li><li> $A : B = (C_1 × T_1) : (C_2 × T_2)$</li><li><strong>Finding Missing Investment:</strong></li><li> If profit shares and times are known,</li><li> $C_1 / C_2 = (P_1 × T_2) / (P_2 × T_1)$</li><li><strong>Equal Investment – Different Time:</strong></li><li> Profit ratio = Time ratio</li><li><strong>Equal Time – Different Investment:</strong></li><li> Profit ratio = Investment ratio</li><li><strong>If one partner joins later:</strong></li><li> Adjust his time as a fraction of total period.</li><li><strong>When additional capital is added:</strong></li><li> Split the time and calculate profit proportion separately for each period.</li></ol><p><br></p><h2>4. ESSENTIAL FORMULAE &amp; METHODS</h2><ol><li><strong>Profit Division Formula:</strong></li><li> $P_A : P_B : P_C = (C_A × T_A) : (C_B × T_B) : (C_C × T_C)$</li><li><strong>Total Profit Distribution:</strong></li><li> Individual Share = (Individual Ratio ÷ Total Ratio) × Total Profit</li><li><strong>If Working Partner Gets Salary:</strong></li><li> Net Profit for Distribution = Total Profit – Salary</li><li><strong>If One Partner Joins Later:</strong></li><li> His time = (Total Duration – Delay of Joining)</li><li><strong>If Partner Withdraws Early:</strong></li><li> His time = (Duration till Withdrawal)</li></ol><p><br></p><h2>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</h2><p><strong>Common Types of Questions:</strong></p><ol><li><strong>Direct Ratio Problems:</strong> Based on proportionality of investment and time.</li><li><strong>Variable Investment Periods:</strong> When one partner joins later or withdraws earlier.</li><li><strong>Working Partner Cases:</strong> Adjust salary or commission before distribution.</li><li><strong>Total Profit Distribution:</strong> Finding share from total profit or total capital.</li><li><strong>Reverse Problems:</strong> Finding investment or time when profits are given.</li></ol><p><strong>Keywords to Identify:</strong></p><ul><li>“Joined after … months”</li><li>“Withdrew after … months”</li><li>“Salary or commission of …”</li><li>“Invested ₹x for y months”</li><li>“Share of profit/loss”</li></ul><p><br></p><h2>6. STEP-BY-STEP SOLUTION METHODS</h2><p><strong>Model 1: Simple Partnership</strong></p><ul><li>Step 1: Note capitals and equal time.</li><li>Step 2: Profit ratio = Capital ratio.</li><li>Step 3: Apply ratio on total profit.</li></ul><p>Example:</p><p> A and B invest ₹5,000 and ₹7,000 for one year.</p><p> Profit ratio = 5 : 7.</p><p>If profit = ₹12,000,</p><p> A’s share = 5/12 × 12,000 = ₹5,000</p><p> B’s share = 7/12 × 12,000 = ₹7,000.</p><p><strong>Model 2: Different Time Periods</strong></p><ul><li>Step 1: Multiply each partner’s capital with time.</li><li>Step 2: Profit ratio = (Capital × Time)</li><li>Step 3: Divide profit according to ratio.</li></ul><p>Example:</p><p> A invests ₹6,000 for 6 months,</p><p> B invests ₹8,000 for 9 months.</p><p> Ratio = 6×6 : 8×9 = 36 : 72 = 1 : 2.</p><p><strong>Model 3: Partner Joins Later</strong></p><ul><li>Step 1: Adjust time for the late partner.</li><li>Step 2: Multiply each investment with time.</li><li>Step 3: Find ratio and divide profit.</li></ul><p>Example:</p><p> A starts a business with ₹50,000.</p><p> B joins after 4 months with ₹60,000.</p><p> Business runs for 12 months.</p><p> A’s time = 12, B’s time = 8.</p><p> Ratio = 50,000×12 : 60,000×8 = 6,00,000 : 4,80,000 = 5 : 4.</p><p><strong>Model 4: Working Partner with Salary</strong></p><ul><li>Step 1: Deduct salary/commission from total profit.</li><li>Step 2: Divide remaining profit in the ratio of investment × time.</li><li>Step 3: Add salary to working partner’s share.</li></ul><p>Example:</p><p> Total profit = ₹12,000</p><p> A &amp; B invest equally.</p><p> A gets salary ₹2,000.</p><p> Remaining profit = ₹10,000</p><p> Equal division = ₹5,000 each.</p><p> A’s total = ₹5,000 + ₹2,000 = ₹7,000</p><p> B’s share = ₹5,000.</p><p><strong>Model 5: Finding Missing Investment</strong></p><p> Given: A &amp; B’s profit share and time known.</p><p> Use: $C_1 / C_2 = (P_1 × T_2) / (P_2 × T_1)$</p><p>Example:</p><p> A and B share profits in ratio 3 : 2.</p><p> A invested ₹6,000 for 10 months, find B’s investment.</p><p> $6,000 / x = (3×10) / (2×10)$ ⇒ $x = (6,000×2)/3 = ₹4,000$</p><p><br></p><h2>7. CONCLUSION</h2><p><strong>Key Takeaways:</strong></p><ul><li>Profit/Loss share always depends on <em>Capital × Time</em>.</li><li>Always equalize time before comparing investments.</li><li>For working partners, deduct salary or commission first.</li><li>For changing investments, divide time periods and calculate separately.</li><li>Ratio simplification is the fastest step to verify accuracy.</li></ul><p><strong>Connections with Other Topics:</strong></p><ul><li>Based on Ratio &amp; Proportion (used in dividing profits)</li><li>Uses Percentage concept in interpreting profits</li><li>Helps in understanding advanced Business Math concepts</li></ul><p><strong>Exam Tip:</strong></p><p> Memorize “Profit Share ∝ Capital × Time” — 80% of questions can be solved mentally using this idea.</p><p><br></p><p><strong>Practice Question:</strong></p><p>A and B invest ₹40,000 and ₹60,000 respectively in a business. Find the ratio of their profits.</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b318');

-- 19. Permutations & Combinations -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b219
INSERT INTO topics (id, subject_id, unit_id, name, description, difficulty, display_order, is_active, created_at, updated_at)
SELECT 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b219', '55555555-5555-5555-5555-555555555501',
    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Permutations & Combinations',
    'Evaluates possible arrangements or selections of objects under given conditions', 'MEDIUM', 47, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE id = 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b219');
INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b319', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b219',
    'Permutations & Combinations Concepts',
    '<h4><strong>1. CONCEPTUAL FOUNDATION</strong></h4><p><strong>Definition:</strong></p><ul><li><strong>Permutation</strong> refers to the <strong>arrangement</strong> of objects where <strong>order matters</strong>.</li><li><strong>Combination</strong> refers to the <strong>selection</strong> of objects where <strong>order does not matter</strong>.</li></ul><p><strong>Real-World Context:</strong></p><ul><li>Arranging people in a queue (order matters → permutation).</li><li>Choosing a committee from a group (order doesn’t matter → combination).</li><li>Forming passwords, telephone numbers, seating plans, and lottery selections.</li></ul><p><strong>Mathematical Significance:</strong></p><p> Permutations and combinations form the foundation for <strong>probability, statistics, counting principles</strong>, and <strong>combinatorial analysis</strong> in mathematics.</p><p><strong>Prerequisites:</strong></p><ul><li>Basic understanding of factorial notation ($n!$)</li><li>Knowledge of counting principles (addition and multiplication rules)</li><li>Concept of identical and distinct objects</li></ul><p><br></p><h4><strong>2. CORE THEORY &amp; PRINCIPLES</strong></h4><p><strong>1. Fundamental Counting Principle:</strong></p><p> If one event can occur in $m$ ways and another in $n$ ways, then both can occur in $m \times n$ ways.</p><p><strong>2. Factorial Concept:</strong></p><p> For any natural number $n$,</p><p> $n! = n \times (n-1) \times (n-2) \times ... \times 2 \times 1$</p><p> and</p><p> $0! = 1$</p><p><strong>3. Permutation (Without Repetition):</strong></p><p> The number of ways of arranging $r$ things out of $n$ distinct things is given by:</p><p> $^nP_r = \frac{n!}{(n-r)!}$</p><p><strong>4. Combination:</strong></p><p> The number of ways of selecting $r$ things out of $n$ distinct things is:</p><p> $^nC_r = \frac{n!}{r!(n-r)!}$</p><p><strong>5. Relationship Between Permutations and Combinations:</strong></p><p> $^nP_r = ^nC_r \times r!$</p><p><strong>6. Permutation (With Repetition):</strong></p><p> When each item can be used repeatedly,</p><p> Number of permutations = $n^r$</p><p><strong>7. Permutations of Repeated Items:</strong></p><p> If there are $n$ objects, where some are identical, e.g.,</p><p> $n_1$ of one kind, $n_2$ of another kind, ..., then</p><p> Number of permutations = $\frac{n!}{n_1! \times n_2! \times ...}$</p><p><strong>8. Circular Permutations:</strong></p><ul><li>For $n$ distinct objects arranged in a circle: $(n - 1)!$</li><li>If clockwise and anticlockwise directions are identical: $\frac{(n - 1)!}{2}$</li></ul><p><br></p><h4><strong>3. MAGIC SHORTCUTS</strong></h4><ol><li><strong>Order Matters → Permutation | Order Doesn’t → Combination</strong></li><li> Example:</li></ol><ul><li class="ql-indent-1">Forming words → permutation</li><li class="ql-indent-1">Selecting players → combination</li></ul><ol><li><strong>Quick Relation Shortcut:</strong></li><li> $^nP_r = ^nC_r \times r!$</li><li><strong>Circular Arrangement Trick:</strong></li></ol><ul><li class="ql-indent-1">All distinct → $(n - 1)!$</li><li class="ql-indent-1">With identical orientation → $\frac{(n - 1)!}{2}$</li></ul><ol><li><strong>Repetition Allowed → $n^r$</strong></li><li> Example: Number of 3-digit numbers formed using 0–9 = $10^3 = 1000$</li><li><strong>At Least / At Most Selections:</strong></li><li> Sum all valid combinations:</li><li> $^nC_r + ^nC_{r+1} + ... + ^nC_n$</li><li><strong>nCr Symmetry Rule:</strong></li><li> $^nC_r = ^nC_{n-r}$</li></ol><p><br></p><h4><strong>4. ESSENTIAL FORMULAE &amp; METHODS</strong></h4><ol><li>$^nP_r = \frac{n!}{(n - r)!}$</li><li>$^nC_r = \frac{n!}{r!(n - r)!}$</li><li>$^nP_r = ^nC_r \times r!$</li><li>Permutations with repetition → $n^r$</li><li>Repetition of identical items → $\frac{n!}{n_1! \times n_2! \times ...}$</li><li>Circular permutations → $(n - 1)!$ or $\frac{(n - 1)!}{2}$</li><li>$^nC_r = ^nC_{n - r}$</li></ol><p><br></p><h4><strong>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</strong></h4><p><strong>1. Direct Permutation Problems:</strong></p><p> Questions asking for arrangements of letters, digits, or people in specific orders.</p><p><strong>2. Repetition Problems:</strong></p><p> Forming numbers or words where repetition is allowed.</p><p><strong>3. Circular Arrangement Problems:</strong></p><p> Arranging people around tables or necklaces.</p><p><strong>4. Selection Problems (Combinations):</strong></p><p> Choosing groups, teams, or committees.</p><p><strong>5. Mixed Permutation-Combination Problems:</strong></p><p> Both selection and arrangement are involved — e.g., “select and arrange” type questions.</p><p><strong>6. Constraints-based Problems:</strong></p><p> Arrangements with restrictions — like “vowels together”, “certain people must sit together”, etc.</p><p><strong>7. Identical Object Problems:</strong></p><p> Situations where some objects are repeated — e.g., letters in the word “BALLOON”.</p><p><br></p><h4><strong>6. CONCLUSION</strong></h4><ul><li><strong>Permutation → Arrangement (Order matters)</strong></li><li><strong>Combination → Selection (Order doesn’t matter)</strong></li><li>Understanding factorials and counting principles is critical for mastery.</li><li>These concepts directly support <strong>Probability</strong>, <strong>Statistics</strong>, and <strong>Combinatorics</strong>.</li><li>Students should practice both conceptual and restricted cases extensively.</li><li>Accuracy in factorial and combination computation ensures efficiency in competitive exams.</li></ul><p><br></p><p><strong>Practice Question:</strong></p><p>How many 3-digit numbers can be formed using digits 1, 2, 3, and 4 if repetition of digits is allowed?</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b319');

-- 20. Races & Game of Skill -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b220
INSERT INTO topics (id, subject_id, unit_id, name, description, difficulty, display_order, is_active, created_at, updated_at)
SELECT 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b220', '55555555-5555-5555-5555-555555555501',
    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Races & Game of Skill',
    'Covers speed comparison, winning conditions, and relative performance in games', 'MEDIUM', 48, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE id = 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b220');
INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b320', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b220',
    'Races & Game of Skill Concepts',
    '<h3>1. CONCEPTUAL FOUNDATION</h3><p>A <strong>race</strong> is a competition of speed where two or more persons, animals, or vehicles start together and try to reach a finishing point first.</p><p>A <strong>game of skill</strong> is a competition where winning depends on individual ability rather than chance.</p><p>In quantitative aptitude, this topic focuses on comparing <strong>speeds</strong>, <strong>advantages (head start or distance)</strong>, and <strong>time differences</strong> between competitors.</p><p><br></p><h3>2. CORE THEORY &amp; PRINCIPLES</h3><ol><li><strong>Key Terms</strong></li></ol><ul><li><strong>Race Course</strong>: The path or track on which the race is conducted.<strong>Starting Point</strong>: The point from which the race begins.<strong>Winning Point (Goal)</strong>: The point where the race ends.<strong>Dead Heat</strong>: When two or more participants reach the goal <strong>simultaneously</strong>.</li></ul><ol><li><strong>Types of Advantages</strong></li></ol><ul><li><strong>Start Advantage (Head Start in Distance)</strong>: When one racer starts a few meters ahead of another.<strong>Time Advantage</strong>: When one racer starts earlier than the other.</li></ul><ol><li><strong>Relationship Between Speed, Time, and Distance</strong></li><li>Formula: $\text{Speed} = \frac{\text{Distance}}{\text{Time}}$</li><li><strong>Winning Conditions</strong></li></ol><ul><li>If two racers, A and B, run the same distance and A finishes earlier by <em>t</em> seconds,</li><li class="ql-indent-1"> then: $\frac{\text{Speed of A}}{\text{Speed of B}} = \frac{\text{Distance}}{\text{Distance} - (\text{B’s distance behind A})}$</li><li>If A gives B a start of <em>d</em> meters in a race of <em>D</em> meters, and both finish together,</li><li> then: $\frac{\text{Speed of A}}{\text{Speed of B}} = \frac{D}{D - d}$</li></ul><p><br></p><h3>3. MAGIC SHORTCUTS</h3><ol><li><strong>Shortcut for Head Start (Distance Advantage)</strong></li><li>If A gives B a start of <em>d</em> meters in a <em>D</em>-meter race and they finish together:</li><li>$\text{Ratio of speeds (A:B)} = D : (D - d)$</li><li><strong>Shortcut for Time Advantage</strong></li><li>If A gives B <em>t</em> seconds start and both finish together:</li><li>$\text{Ratio of speeds (A:B)} = \text{Time taken by B} : (\text{Time taken by B} - t)$</li><li><strong>Dead Heat Shortcut</strong></li><li>If both reach together in a race of <em>D</em> meters, then both speeds are equal.</li><li><strong>When Given Speeds and Distances</strong></li><li>$\text{Time taken} = \frac{\text{Distance}}{\text{Speed}}$</li><li>Winner = One with the <strong>lesser time</strong>.</li></ol><p><br></p><h3>4. ESSENTIAL FORMULAE &amp; METHODS</h3><ol><li><strong>Speed Ratio from Time Difference:</strong></li><li>$\frac{\text{Speed of A}}{\text{Speed of B}} = \frac{\text{Time taken by B}}{\text{Time taken by A}}$</li><li><strong>When A beats B by Distance:</strong></li><li>If in a race of <em>D</em> meters, A beats B by <em>d</em> meters, then:</li><li>$\frac{\text{Speed of A}}{\text{Speed of B}} = \frac{D}{D - d}$</li><li><strong>When A beats B by Time:</strong></li><li>$\frac{\text{Speed of A}}{\text{Speed of B}} = \frac{\text{Time of B}}{\text{Time of B} - t}$</li><li><strong>Equal Finish (Dead Heat):</strong></li><li>$\text{Speed of A} = \text{Speed of B}$</li><li><strong>Time Difference Formula:</strong></li><li>$\text{Time difference} = \frac{\text{Distance difference}}{\text{Speed}}$</li></ol><p><br></p><h3>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</h3><p><strong>Model 1:</strong> Finding speed ratio when one racer beats another by a certain distance.</p><p><strong>Model 2:</strong> Finding distance advantage when time advantage is known.</p><p><strong>Model 3:</strong> Finding time advantage when distance advantage is known.</p><p><strong>Model 4:</strong> Determining winner or dead heat conditions.</p><p><strong>Model 5:</strong> Mixed problems involving both time and distance advantages.</p><p><br></p><h3>6. STEP-BY-STEP SOLUTION METHODS</h3><p><strong>Example 1:</strong></p><p>In a 1000 m race, A beats B by 100 m. Find the ratio of their speeds.</p><p><strong>Step 1:</strong> Use formula</p><p>$\frac{\text{Speed of A}}{\text{Speed of B}} = \frac{D}{D - d}$</p><p><strong>Step 2:</strong> Substitute values</p><p>$\frac{\text{Speed of A}}{\text{Speed of B}} = \frac{1000}{900} = \frac{10}{9}$</p><p>Hence, the ratio of their speeds is <strong>10 : 9</strong>.</p><p><br></p><p><strong>Example 2:</strong></p><p>In a 500 m race, A gives B a start of 25 m and beats him by 5 seconds. Find A’s speed if B runs 5 m/s.</p><p><strong>Step 1:</strong> Distance covered by B = 500 – 25 = 475 m</p><p>Time taken by B = $\frac{475}{5} = 95$ s</p><p>Time taken by A = 95 – 5 = 90 s</p><p>Speed of A = $\frac{500}{90} = 5.56$ m/s</p><p>Hence, A’s speed is <strong>5.56 m/s</strong>.</p><p><br></p><p><strong>Example 3:</strong></p><p>A gives B a start of 10 seconds and still beats him by 20 m in a 200 m race. Find their speed ratio.</p><p><strong>Let:</strong> Speed of A = $x$, Speed of B = $y$.</p><p>Then, A’s time for 200 m = $\frac{200}{x}$,</p><p>B’s time for 200 m = $\frac{200}{y} + 10$.</p><p>At the finish line, A is 20 m ahead:</p><p>$\frac{200}{x} = \frac{180}{y} + 10$</p><p>→ $200y = 180x + 10xy$</p><p>→ $\frac{x}{y} = \frac{200}{180 + 10y}$ (solve based on given data).</p><p><br></p><h3>7. CONCLUSION</h3><ul><li>Races and games of skill problems are based on comparing <strong>relative speeds</strong> and <strong>advantages</strong>.</li><li>Always clarify whether the advantage is in <strong>distance</strong> or <strong>time</strong>.</li><li>Most problems reduce to a <strong>ratio of speeds</strong> or a <strong>difference in time/distance</strong>.</li><li>Understanding the relationship between time, distance, and speed is key to solving quickly.</li></ul><p><br></p><p>Practice Question:</p><p>In a 400 m race, A defeats B by 40 m. Find the ratio of their speeds (A : B).</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b320');

