INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b323', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b223',
    'Percentage Concepts',
    '<h4><strong style="background-color: transparent; color: rgb(0, 0, 0);">1. CONCEPTUAL FOUNDATION</strong></h4><p><span style="background-color: transparent; color: rgb(0, 0, 0);">The concept of </span><strong style="background-color: transparent; color: rgb(0, 0, 0);">Percentage</strong><span style="background-color: transparent; color: rgb(0, 0, 0);"> is a cornerstone of Arithmetic and appears across almost every quantitative aptitude topic.</span></p><ul><li><span style="background-color: transparent;">The term </span><strong style="background-color: transparent;">“percent”</strong><span style="background-color: transparent;"> literally means </span><em style="background-color: transparent;">“per hundred”</em><span style="background-color: transparent;">, i.e., a ratio or fraction with denominator 100.</span></li><li>It is used to express comparisons, changes, profits, losses, increases, decreases, and performance ratios in a standardized form.</li><li>Percentages allow easy comparison between values of different magnitudes.</li></ul><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Real-Life Relevance:</strong></p><ul><li><span style="background-color: transparent;">Used in discounts, profit–loss, population growth, interest rates, exam scores, and statistics.</span></li><li><span style="background-color: transparent;">In aptitude exams, percentages form the backbone of </span><strong style="background-color: transparent;">Profit &amp; Loss</strong><span style="background-color: transparent;">, </span><strong style="background-color: transparent;">Simple Interest &amp; Compound Interest</strong><span style="background-color: transparent;">, </span><strong style="background-color: transparent;">Data Interpretation</strong><span style="background-color: transparent;">, and </span><strong style="background-color: transparent;">Mixtures</strong><span style="background-color: transparent;"> problems.</span></li></ul><p><br></p><h4><strong style="background-color: transparent; color: rgb(0, 0, 0);">2. CORE THEORY &amp; PRINCIPLES</strong></h4><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Basic Definition:</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> If a quantity $x$ is $\dfrac{p}{100}$ part of another quantity $y$, then:</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> $x = \dfrac{p}{100} \times y$</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Thus,</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> $p%$ of $y = \dfrac{p}{100} \times y$</span></p><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Conversions:</strong></p><ul><li><span style="background-color: transparent;">Fraction → Percentage: Multiply by 100</span></li><li><span style="background-color: transparent;">Decimal → Percentage: Multiply by 100</span></li><li><span style="background-color: transparent;">Percentage → Fraction: Divide by 100</span></li></ul><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Example:</span></p><ul><li><span style="background-color: transparent;">$\dfrac{1}{4} = 25%$</span></li><li><span style="background-color: transparent;">$0.6 = 60%$</span></li><li><span style="background-color: transparent;">$75% = \dfrac{3}{4}$</span></li></ul><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Types of Percentage Relationships:</strong></p><ol><li><strong style="background-color: transparent;">Percentage of Quantity:</strong><span style="background-color: transparent;"> Find part of a whole.</span></li><li>Example: 25% of 80 = (25/100)×80 = 20.</li><li><br></li><li><strong style="background-color: transparent;">Percentage Change (Increase/Decrease):</strong></li><li><span style="background-color: transparent;"> Change% = $\dfrac{\text{Difference}}{\text{Original Value}} \times 100$</span></li><li><strong style="background-color: transparent;">Percentage Comparison:</strong></li><li><span style="background-color: transparent;"> When one quantity is compared with another.</span></li><li><span style="background-color: transparent;"> Example: A is 20% more than B ⇒ A = 1.2B.</span></li><li><span style="background-color: transparent;"> B is 20% less than A ⇒ B = 0.8A.</span></li></ol><p><br></p><h4><strong style="background-color: transparent; color: rgb(0, 0, 0);">3. MAGIC SHORTCUTS</strong></h4><p><strong style="background-color: transparent;">Quick Percent–Fraction Conversion Table:</strong></p><table table_id="817jfvq1ajn" id="817jfvq1ajn" class=""><tr row_id="q3r5bknpql" style="width: 100%;"><td table_id="817jfvq1ajn" row_id="q3r5bknpql" cell_id="de1l67tc9s" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Fraction</strong></p></td><td table_id="817jfvq1ajn" row_id="q3r5bknpql" cell_id="h1l5xr98cei" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Percentage</strong></p></td><td table_id="817jfvq1ajn" row_id="q3r5bknpql" cell_id="36x7817t1" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Fraction</strong></p></td><td table_id="817jfvq1ajn" row_id="q3r5bknpql" cell_id="ijvz97t01jr" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Percentage</strong></p></td></tr><tr row_id="u2y0mdza1k8" style="width: 100%;"><td table_id="817jfvq1ajn" row_id="u2y0mdza1k8" cell_id="ckjwx6q4qy" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1/2</span></p></td><td table_id="817jfvq1ajn" row_id="u2y0mdza1k8" cell_id="hn4mz3h99e9" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">50%</span></p></td><td table_id="817jfvq1ajn" row_id="u2y0mdza1k8" cell_id="7h7a43sm6pv" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1/8</span></p></td><td table_id="817jfvq1ajn" row_id="u2y0mdza1k8" cell_id="6pv1f1h9x7" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">12.5%</span></p></td></tr><tr row_id="p5i0xe2qvwr" style="width: 100%;"><td table_id="817jfvq1ajn" row_id="p5i0xe2qvwr" cell_id="eyb2upeud1d" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1/3</span></p></td><td table_id="817jfvq1ajn" row_id="p5i0xe2qvwr" cell_id="tdesnju9fom" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">33⅓%</span></p></td><td table_id="817jfvq1ajn" row_id="p5i0xe2qvwr" cell_id="wrhnrbzz9kq" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1/9</span></p></td><td table_id="817jfvq1ajn" row_id="p5i0xe2qvwr" cell_id="639diime56" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">11.11%</span></p></td></tr><tr row_id="nkhyjwwdaxf" style="width: 100%;"><td table_id="817jfvq1ajn" row_id="nkhyjwwdaxf" cell_id="3srgffcn1li" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1/4</span></p></td><td table_id="817jfvq1ajn" row_id="nkhyjwwdaxf" cell_id="0zuuyk7q4rja" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">25%</span></p></td><td table_id="817jfvq1ajn" row_id="nkhyjwwdaxf" cell_id="b768smy0b3j" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1/10</span></p></td><td table_id="817jfvq1ajn" row_id="nkhyjwwdaxf" cell_id="ms34iya6uwc" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">10%</span></p></td></tr><tr row_id="z3hqi279yb" style="width: 100%;"><td table_id="817jfvq1ajn" row_id="z3hqi279yb" cell_id="nhzn098v7r" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1/5</span></p></td><td table_id="817jfvq1ajn" row_id="z3hqi279yb" cell_id="8kf4i4c2x93" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">20%</span></p></td><td table_id="817jfvq1ajn" row_id="z3hqi279yb" cell_id="kjfwo5imvh" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1/12</span></p></td><td table_id="817jfvq1ajn" row_id="z3hqi279yb" cell_id="x8k0hpg6n8" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">8.33%</span></p></td></tr><tr row_id="hj8ub8b0o6" style="width: 100%;"><td table_id="817jfvq1ajn" row_id="hj8ub8b0o6" cell_id="no70x75my3d" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1/6</span></p></td><td table_id="817jfvq1ajn" row_id="hj8ub8b0o6" cell_id="apms0cj1tlr" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">16⅔%</span></p></td><td table_id="817jfvq1ajn" row_id="hj8ub8b0o6" cell_id="acedokuiba" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1/15</span></p></td><td table_id="817jfvq1ajn" row_id="hj8ub8b0o6" cell_id="ok1qrswox" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">6.66%</span></p></td></tr><tr row_id="ftldwrroe15" style="width: 100%;"><td table_id="817jfvq1ajn" row_id="ftldwrroe15" cell_id="lpgp539e20a" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1/7</span></p></td><td table_id="817jfvq1ajn" row_id="ftldwrroe15" cell_id="7whasqbu13b" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">14.28%</span></p></td><td table_id="817jfvq1ajn" row_id="ftldwrroe15" cell_id="4d4509kmyx1" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">1/20</span></p></td><td table_id="817jfvq1ajn" row_id="ftldwrroe15" cell_id="jxunu5t0m1p" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">5%</span></p></td></tr></table><p><br></p><p><strong style="background-color: transparent;">Successive Percentage Change Formula:</strong></p><ul><li><span style="background-color: transparent;">If a number increases by </span><em style="background-color: transparent;">a%</em><span style="background-color: transparent;"> and then by </span><em style="background-color: transparent;">b%</em><span style="background-color: transparent;">,</span></li><li class="ql-indent-1">Net % change = a + b + (ab)/100</li><li><span style="background-color: transparent; color: rgb(0, 0, 0);">If one increase and one decrease:</span></li><li class="ql-indent-1"><span style="background-color: transparent; color: rgb(0, 0, 0);">Net % change = a − b − (ab)/100</span></li></ul><p><strong style="background-color: transparent;">Percentage Reversal Trick:</strong></p><ol><li><span style="background-color: transparent;">If A is p% more than B, then B is $\dfrac{p}{100+p} \times 100%$ less than A.</span></li><li><span style="background-color: transparent;"> Example: A is 25% more than B ⇒ B is (25/125)×100 = 20% less than A.</span></li></ol><p><strong style="background-color: transparent;">Population Growth Shortcut:</strong></p><ol><li><span style="background-color: transparent;"> If population grows by r% per year,</span></li><li><span style="background-color: transparent;"> Population after n years = P(1 + r/100)ⁿ</span></li><li><span style="background-color: transparent;"> If population decreases, use (1 − r/100)ⁿ.</span></li></ol><p><strong style="background-color: transparent;">Equalization Trick:</strong></p><ol><li><span style="background-color: transparent;"> If x% of A = y% of B, then A : B = y : x.</span></li></ol><p><br></p><h3><strong style="background-color: transparent; color: rgb(0, 0, 0);">4. ESSENTIAL FORMULAE &amp; METHODS</strong></h3><ol><li><strong style="background-color: transparent;">Basic Percentage Formula: </strong><span style="background-color: transparent;">Percentage = (Part / Whole) × 100</span></li><li><strong style="background-color: transparent;">Increase/Decrease Formula:</strong><span style="background-color: transparent;"> New Value = Original × (1 ± r/100)</span></li><li><strong style="background-color: transparent;">Profit &amp; Loss Relation:</strong></li><li><span style="background-color: transparent;"> Profit% = (Profit / Cost Price) × 100</span></li><li><span style="background-color: transparent;"> Loss% = (Loss / Cost Price) × 100</span></li><li><strong style="background-color: transparent;">Successive Change:</strong></li><li><span style="background-color: transparent;"> Net Change% = a + b + (ab)/100</span></li><li><strong style="background-color: transparent;">Reverse Percentage:</strong></li><li><span style="background-color: transparent;"> If value increases by p%, then the original value = Final Value × (100 / (100 + p))</span></li><li><span style="background-color: transparent;"> If value decreases by p%, then Original = Final × (100 / (100 − p))</span></li><li><strong style="background-color: transparent;">Exam or Mark Problems:</strong></li><li><span style="background-color: transparent;"> Marks obtained = (Percentage × Total Marks)/100</span></li></ol><p><br></p><h3><strong style="background-color: transparent; color: rgb(0, 0, 0);">5. PROBLEM RECOGNITION &amp; CLASSIFICATION</strong></h3><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Common Question Types:</strong></p><table table_id="fd4115xom0g" id="fd4115xom0g"><tr row_id="ai9r3jlqdo" style="width: 100%;"><td table_id="fd4115xom0g" row_id="ai9r3jlqdo" cell_id="ys7rk8odl3" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Type</strong></p></td><td table_id="fd4115xom0g" row_id="ai9r3jlqdo" cell_id="066hjz9derx4" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Description</strong></p></td><td table_id="fd4115xom0g" row_id="ai9r3jlqdo" cell_id="ndl1mpm5kc" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Example</strong></p></td></tr><tr row_id="cefgk33e1u" style="width: 100%;"><td table_id="fd4115xom0g" row_id="cefgk33e1u" cell_id="e80lclxplkj" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Type 1</span></p></td><td table_id="fd4115xom0g" row_id="cefgk33e1u" cell_id="5kgmfw2prri" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Finding % value</span></p></td><td table_id="fd4115xom0g" row_id="cefgk33e1u" cell_id="vkh5jp3ge6m" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Find 25% of 240</span></p></td></tr><tr row_id="urg9m74916l" style="width: 100%;"><td table_id="fd4115xom0g" row_id="urg9m74916l" cell_id="deunh6inpt8" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Type 2</span></p></td><td table_id="fd4115xom0g" row_id="urg9m74916l" cell_id="ww3aayjqc0r" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Converting % to fraction or vice versa</span></p></td><td table_id="fd4115xom0g" row_id="urg9m74916l" cell_id="a32lp96eigm" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Convert 0.45 to %</span></p></td></tr><tr row_id="1k6onnxqx9r" style="width: 100%;"><td table_id="fd4115xom0g" row_id="1k6onnxqx9r" cell_id="fcquzo7cx9" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Type 3</span></p></td><td table_id="fd4115xom0g" row_id="1k6onnxqx9r" cell_id="rpk130wb0s" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">% Increase/Decrease</span></p></td><td table_id="fd4115xom0g" row_id="1k6onnxqx9r" cell_id="5055tvhoqf4" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Price increases from ₹400 to ₹500</span></p></td></tr><tr row_id="wv0q9l01h9f" style="width: 100%;"><td table_id="fd4115xom0g" row_id="wv0q9l01h9f" cell_id="6w31mmm88vo" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Type 4</span></p></td><td table_id="fd4115xom0g" row_id="wv0q9l01h9f" cell_id="rul4xmi8qj" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Reverse %</span></p></td><td table_id="fd4115xom0g" row_id="wv0q9l01h9f" cell_id="nwurt3vmumf" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">After 25% rise, salary is ₹25,000. Find original.</span></p></td></tr><tr row_id="v2c8g3qhyjk" style="width: 100%;"><td table_id="fd4115xom0g" row_id="v2c8g3qhyjk" cell_id="jqmi4x9vafm" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Type 5</span></p></td><td table_id="fd4115xom0g" row_id="v2c8g3qhyjk" cell_id="1kwep4b7oa6" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Comparison %</span></p></td><td table_id="fd4115xom0g" row_id="v2c8g3qhyjk" cell_id="m8w0tippzd" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">A is 20% more than B. How much less is B than A?</span></p></td></tr><tr row_id="nptdp1aq38k" style="width: 100%;"><td table_id="fd4115xom0g" row_id="nptdp1aq38k" cell_id="lslh023xvbn" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Type 6</span></p></td><td table_id="fd4115xom0g" row_id="nptdp1aq38k" cell_id="yg58ieaybxb" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Successive %</span></p></td><td table_id="fd4115xom0g" row_id="nptdp1aq38k" cell_id="s0tajkuxcmf" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Price rises 10% then 20%. Find net rise.</span></p></td></tr><tr row_id="p4gylb8mrzj" style="width: 100%;"><td table_id="fd4115xom0g" row_id="p4gylb8mrzj" cell_id="f6v6sg90jg" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Type 7</span></p></td><td table_id="fd4115xom0g" row_id="p4gylb8mrzj" cell_id="2mlon4g8188" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Population/Depreciation</span></p></td><td table_id="fd4115xom0g" row_id="p4gylb8mrzj" cell_id="lwwabykt84" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Population grows 5% yearly for 3 years</span></p></td></tr><tr row_id="20meuymwz21" style="width: 100%;"><td table_id="fd4115xom0g" row_id="20meuymwz21" cell_id="7raddc1z0w7" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Type 8</span></p></td><td table_id="fd4115xom0g" row_id="20meuymwz21" cell_id="vd0fot1wyei" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Result/Marks</span></p></td><td table_id="fd4115xom0g" row_id="20meuymwz21" cell_id="m20vxtvzwcn" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">A got 35% of marks and failed by 20 marks</span></p></td></tr></table><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Keywords to Recognize Topic:</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">"percent", "more than", "less than", "increase by", "decreased to", "growth rate", "marks obtained", "population", "profit/loss", "successive change".</span></p><p><br></p><h3><strong style="background-color: transparent; color: rgb(0, 0, 0);">6. STEP-BY-STEP SOLUTION METHODS</strong></h3><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model 1: Finding Percentage Value</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Question: Find 12% of 450.</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Step 1: 12% = 12/100</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Step 2: (12/100) × 450 = 54.</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Answer = 54.</span></p><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model 2: Finding Increase or Decrease Percentage</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Question: A number increases from 80 to 100. Find % increase.</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Step 1: Change = 100 − 80 = 20.</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Step 2: (20/80) × 100 = 25%.</span></p><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model 3: Successive Percentage</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Question: A quantity increases by 10% and then by 20%. Find overall % increase.</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Solution: Net % = 10 + 20 + (10×20)/100 = 32%.</span></p><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model 4: Reverse Percentage</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Question: A salary after a 25% rise is ₹25,000. Find the original salary.</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Step 1: Original = (25,000 × 100)/(100 + 25) = ₹20,000.</span></p><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model 5: Population Change</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Question: Population 5,000, grows 10% annually for 2 years.</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Population after 2 years = 5000 × (1 + 10/100)² = 5000 × (1.1)² = 6050.</span></p><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model 6: Marks Problem</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Question: A student scored 180 marks, which is 60% of total. Find total marks.</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Total = (180 × 100)/60 = 300.</span></p><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model 7: Percentage Comparison</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Question: A is 25% more than B. Find how much % less is B than A.</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Step 1: A = 1.25B</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Step 2: Difference = A − B = 0.25B</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Step 3: (0.25B / 1.25B) × 100 = 20%.</span></p><p><br></p><h4><strong style="background-color: transparent; color: rgb(0, 0, 0);">7. CONCLUSION</strong></h4><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Key Learnings:</strong></p><ul><li><span style="background-color: transparent;">Percentages convert any ratio into an easy-to-compare standard form.</span></li><li><span style="background-color: transparent;">Increase or decrease percentages always relate to the </span><strong style="background-color: transparent;">original value</strong><span style="background-color: transparent;">.</span></li><li>Always apply successive percentage rules carefully (don’t add directly).</li><li>Reverse percentage helps find original quantities after change.</li></ul><p><br></p><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Speed Tips:</strong></p><ul><li><span style="background-color: transparent;">Memorize key fraction–percentage conversions.</span></li><li><span style="background-color: transparent;">Use the 100-base rule for comparing quantities.</span></li><li><span style="background-color: transparent;">For rapid mental work, approximate percentages (e.g., 12.5% = 1/8).</span></li></ul><p><br></p><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Connections:</strong></p><ul><li><span style="background-color: transparent;">Directly related to </span><strong style="background-color: transparent;">Profit &amp; Loss</strong><span style="background-color: transparent;">, </span><strong style="background-color: transparent;">Simple &amp; Compound Interest</strong><span style="background-color: transparent;">, </span><strong style="background-color: transparent;">Data Interpretation</strong><span style="background-color: transparent;">, and </span><strong style="background-color: transparent;">Mixtures</strong><span style="background-color: transparent;">.</span></li></ul><p><br></p><h3><strong style="background-color: transparent; color: rgb(0, 0, 0);">Additional Section: COMMON MISTAKES TO AVOID</strong></h3><ol><li><span style="background-color: transparent;">Confusing “increase by 25%” with “becomes 125% of original.”</span></li><li><span style="background-color: transparent;">Using wrong base for % change (must always be original).</span></li><li><span style="background-color: transparent;">Forgetting to reverse the operation in reverse % questions.</span></li><li><span style="background-color: transparent;">Adding successive percentages directly without using the formula.</span></li></ol><p><br></p><p><strong>Practice Question:</strong></p><p>A quantity is increased by 10% and then decreased by 20%. Find the net percentage change.</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b323');

-- 24. Alligation or Mixture -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b224
INSERT INTO topics (id, subject_id, unit_id, name, description, difficulty, display_order, is_active, created_at, updated_at)
SELECT 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b224', '55555555-5555-5555-5555-555555555501',
    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Alligation or Mixture',
    'Deals with mixing of two or more quantities of different values to find ratio or mean value', 'MEDIUM', 52, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE id = 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b224');
INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b324', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b224',
    'Alligation or Mixture Concepts',
    '<h3><strong>1. CONCEPTUAL FOUNDATION</strong></h3><ul><li><strong>Alligation</strong> is a method used to find the <strong>ratio</strong> in which two or more ingredients at different costs or concentrations are mixed to obtain a desired mean cost or concentration.</li><li><strong>Mixture</strong> refers to the <strong>combination of two or more ingredients</strong> having different qualities (price, strength, percentage, etc.).</li><li><strong>Real-life use:</strong></li><li class="ql-indent-1">Mixing two varieties of rice, milk, or alloys.</li><li class="ql-indent-1">Combining two liquids of different strengths (like alcohol and water).</li><li class="ql-indent-1">Finding average value, rate, or cost of a mixture.</li><li><strong>Mathematical connection:</strong> This topic bridges <strong>Ratio &amp; Proportion</strong>, <strong>Averages</strong>, and <strong>Percentages</strong>.</li></ul><p><br></p><h3><strong>2. CORE THEORY &amp; PRINCIPLES</strong></h3><ol><li><strong>Alligation Rule (Mean Rule):</strong></li><li> When two ingredients at different costs are mixed, the mean cost lies <strong>between</strong> the two costs.</li><li>If we have two ingredients costing ₹x₁ and ₹x₂ per unit, mixed to produce a mean cost ₹m,</li><li> then</li><li> <strong>Ratio of quantities</strong> = (x₂ - m) : (m - x₁)</li><li><strong>Alligation Method is Applied When:</strong></li></ol><ul><li class="ql-indent-1">Ingredients are <strong>mixed</strong> or <strong>blended</strong>.</li><li class="ql-indent-1">The <strong>mean value</strong> or average concentration of the mixture is <strong>known</strong> or required.</li><li class="ql-indent-1">The <strong>components differ</strong> in price, value, strength, or concentration.</li></ul><ol><li><strong>Important Terms:</strong></li></ol><ul><li class="ql-indent-1"><strong>Mean Value:</strong> The desired average (cost, strength, or concentration) of the mixture.</li><li class="ql-indent-1"><strong>Cheaper Quantity (C):</strong> The item with a lower value.</li><li class="ql-indent-1"><strong>Dearer Quantity (D):</strong> The item with a higher value.</li><li class="ql-indent-1"><strong>Mean Price (M):</strong> Target or average price of the mixture.</li></ul><p><br></p><h3><strong>3. MAGIC SHORTCUTS</strong></h3><p><strong>Alligation Cross Formula (Visual Trick):</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> </span><span style="background-color: transparent; color: rgb(24, 128, 56);">&nbsp;Dearer (D) → x₂</span></p><p><span style="background-color: transparent; color: rgb(24, 128, 56);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;↘ &nbsp; &nbsp; ↖</span></p><p><span style="background-color: transparent; color: rgb(24, 128, 56);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\ &nbsp; /</span></p><p><span style="background-color: transparent; color: rgb(24, 128, 56);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Mean (M)</span></p><p><span style="background-color: transparent; color: rgb(24, 128, 56);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;/ &nbsp; \</span></p><p><span style="background-color: transparent; color: rgb(24, 128, 56);">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;↗ &nbsp; &nbsp; ↘</span></p><p><span style="background-color: transparent; color: rgb(24, 128, 56);">&nbsp;&nbsp;Cheaper (C) → x₁</span></p><p>Then Ratio of quantities = (x₂ - M) : (M - x₁)</p><p><strong>When Mean is Not Directly Given:</strong></p><ul><li>Find the <strong>average value</strong> or <strong>weighted mean</strong> first, then apply the alligation rule.</li></ul><p><strong>When One Quantity is Water (Free Substance):</strong></p><ul><li>Use “0” as the cost or concentration of water.</li></ul><p><strong>Fast Identification:</strong></p><ul><li>If question mentions “mixture,” “mean price,” or “percentage of ingredient,” think <strong>Alligation</strong>.</li></ul><p><strong>Quick Reverse Alligation (Backtrack Trick):</strong></p><ul><li>When ratio and prices are given, reverse the formula to find the mean:</li><li> Mean = (Quantity₁×Price₁ + Quantity₂×Price₂) / (Quantity₁ + Quantity₂)</li></ul><p><br></p><h3><strong>6. STEP-BY-STEP SOLUTION METHODS</strong></h3><p><strong>Model 2: Concentration-based Mixture</strong></p><p> Example: Mix two alcohol solutions 20% and 50% to get 30%. Find ratio.</p><ul><li>Step 1: D=50, C=20, M=30</li><li>Step 2: Ratio = (50-30):(30-20) = 20:10 = 2:1</li><li>Step 3: Hence, mix in ratio 2:1.</li></ul><p><strong>Model 3: Mean Value Calculation (Reverse Alligation)</strong></p><p> Example: Mixture contains substances in ratio 2:3, prices ₹40, ₹50. Find mean price.</p><ul><li>Step 1: M = (2×40 + 3×50)/(2+3)</li><li>Step 2: M = (80+150)/5 = ₹46</li><li>Step 3: Mean price = ₹46/kg.</li></ul><p><strong>Model 4: Replacement Problems</strong></p><p> Example: 60L of milk-water mixture (5:1). 10L replaced by water. Find ratio after 1 replacement.</p><ul><li>Step 1: Milk part = 5/6 of 60 = 50L</li><li>Step 2: Milk left = 50 × (1 - 10/60) = 50 × (5/6) = 41.67L</li><li>Step 3: New milk:water = 41.67 : (60 - 41.67) = 41.67 : 18.33 = 2.27 : 1</li></ul><p><strong>Model 5: Successive Mixtures</strong></p><p> Example: Mix ₹8/kg, ₹12/kg, and ₹20/kg in ratio to get ₹13/kg.</p><ul><li>Step 1: Apply alligation twice.</li><li class="ql-indent-1">Mix ₹8 and ₹12 → Mean ₹10 ⇒ Ratio (12-10):(10-8)=2:2=1:1</li><li class="ql-indent-1">Mix result (₹10) and ₹20 to get ₹13 ⇒ Ratio (20-13):(13-10)=7:3</li><li>Step 2: Combine to get final ratio using multiplication rule.</li></ul><p><br></p><h3><strong>7. CONCLUSION</strong></h3><ul><li><strong>Alligation = Ratio + Average + Percentage combined into one visual method.</strong></li><li>Always identify <strong>dearer, cheaper, and mean</strong> values before applying the rule.</li><li>Prefer the <strong>Alligation Cross Method</strong> for quick ratio derivation in exams.</li><li><strong>Replacement models</strong> are extensions of mixture logic — often tested for advanced reasoning.</li><li>Once mastered, this topic enhances understanding of <strong>Partnership</strong>, <strong>Profit &amp; Loss</strong>, and <strong>Simple Interest</strong> models.</li></ul><p><br></p><h3><strong>8. COMMON TRAPS &amp; SMART CHECKS</strong></h3><p><strong>Trap:</strong> Using higher value first in ratio difference.</p><ul><li class="ql-indent-1"><strong>Fix:</strong> Always subtract <em>Mean from High</em> and <em>Low from Mean</em> in correct order.</li></ul><p><strong>Trap:</strong> Confusing price-based and percentage-based questions.</p><ul><li class="ql-indent-1"><strong>Fix:</strong> Check the units — if in %, use as concentration; if in ₹, treat as cost.</li></ul><p><strong>Trap:</strong> Ignoring dilution in replacement problems.</p><ul><li class="ql-indent-1"><strong>Fix:</strong> Use $A(1 - \frac{x}{V})^n$ formula when repeated replacement occurs.</li></ul><p><strong>Smart Check:</strong></p><p>Mean must always lie <strong>between</strong> cheaper and dearer values. If not, calculation error exists.</p><p><br></p><p><strong>Practice Question:</strong></p><p>Tea costing ₹180/kg mixed with ₹120/kg tea to get ₹150/kg mixture. Find ratio.</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b324');

-- 25. Time & Work -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b225
INSERT INTO topics (id, subject_id, unit_id, name, description, difficulty, display_order, is_active, created_at, updated_at)
SELECT 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b225', '55555555-5555-5555-5555-555555555501',
    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Time & Work',
    'Focuses on work efficiency, combined work, and time taken by multiple workers to complete a task', 'MEDIUM', 53, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE id = 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b225');
INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b325', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b225',
    'Time & Work Concepts',
    '<h4><strong>1. CONCEPTUAL FOUNDATION</strong></h4><p>The topic <em>Time and Work</em> deals with the relationship between the amount of work done, the time taken, and the efficiency (or rate) of working. It establishes how multiple workers (or machines) can together complete a job in a certain period. This concept forms the base for solving problems related to human efficiency, pipes and cisterns, and machine productivity.</p><p><strong>Key Idea:</strong></p><p> If a person can do a piece of work in <em>n</em> days, then the work done by him in one day is <em>1/n</em> of the total work.</p><p><br></p><h3>2. CORE THEORY &amp; PRINCIPLES</h3><ol><li><strong>Work–Time Relation:</strong></li></ol><ul><li class="ql-indent-1">Work done is directly proportional to the number of workers and the time they work.</li><li>Formula:</li><li class="ql-indent-1"> $Work = Time × Efficiency$</li></ul><ol><li><strong>Individual Efficiency:</strong></li></ol><ul><li>If A can complete a work in <em>x</em> days, then:</li><li class="ql-indent-1"> A’s 1 day work = $1/x$</li></ul><ol><li><strong>Combined Work:</strong></li></ol><ul><li>If A can do a work in <em>x</em> days and B in <em>y</em> days, then together in 1 day they complete:</li><li class="ql-indent-1"> $(1/x + 1/y)$ part of work.</li><li class="ql-indent-1">Total time taken = $\dfrac{xy}{x + y}$ days.</li></ul><ol><li><strong>Work Difference Concept:</strong></li></ol><ul><li class="ql-indent-1">If A and B start together but A leaves after some time, then we calculate total work and subtract A’s contribution.</li></ul><ol><li><strong>Efficiency and Ratio:</strong></li></ol><ul><li>The ratio of time taken by A and B to complete the same work is inverse of their efficiency ratio.</li><li class="ql-indent-1"> $Time_A : Time_B = 1/Eff_A : 1/Eff_B$</li></ul><p><br></p><h3>3. MAGIC SHORTCUTS</h3><ol><li><strong>Shortcut 1 – Work Efficiency Ratio:</strong></li><li> If A:B = 3:2 (efficiency), then their time ratio = 2:3.</li><li><strong>Shortcut 2 – Part of Work Done:</strong></li><li> If a person works for <em>d</em> days out of <em>n</em> days required to complete the job, then fraction of work done = $d/n$.</li><li><strong>Shortcut 3 – Pipes &amp; Cistern Connection:</strong></li></ol><ul><li>For filling and emptying problems:</li><li class="ql-indent-1"> Net work rate = (filling rate – emptying rate).</li></ul><ol><li><strong>Shortcut 4 – Work Left Formula:</strong></li><li> If A and B can finish a work in <em>x</em> and <em>y</em> days respectively, then the fraction of work left after <em>n</em> days = $1 - n(1/x + 1/y)$.</li><li><strong>Shortcut 5 – Efficiency % Concept:</strong></li></ol><ul><li class="ql-indent-1">If a person is <em>p%</em> more efficient than another, time taken is reduced by $\dfrac{p}{100 + p} × 100%$.</li></ul><p><br></p><h3>4. ESSENTIAL FORMULAE &amp; METHODS</h3><ol><li><strong>Work Formula:</strong></li><li> $Work = Rate × Time$</li><li><strong>Combined Time Formula:</strong></li><li> If A takes <em>x</em> days and B takes <em>y</em> days, then:</li><li> $T = \dfrac{xy}{x + y}$</li><li><strong>If A, B, C work together:</strong></li><li> $1/T = 1/x + 1/y + 1/z$</li><li><strong>Work left after t days:</strong></li><li> $Remaining\ Work = 1 - (t × (1/x + 1/y))$</li><li><strong>Efficiency–Time Conversion:</strong></li><li> $Efficiency ∝ 1/Time$</li><li><strong>Alternate Day Work:</strong></li></ol><ul><li class="ql-indent-1">If A and B work on alternate days, calculate total work in 2 days as a unit cycle.</li></ul><ol><li><strong>Pipes and Cistern Analogy:</strong></li></ol><ul><li class="ql-indent-1">A filling pipe is positive work, an emptying pipe is negative work.</li></ul><p><br></p><h3>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</h3><ol><li><strong>Type 1: Individual Work Problems</strong></li></ol><ul><li class="ql-indent-1">One person or machine doing complete work.</li></ul><ol><li><strong>Type 2: Combined Work Problems</strong></li></ol><ul><li class="ql-indent-1">Two or more workers working together.</li></ul><ol><li><strong>Type 3: Partial Work / Leaving Early Problems</strong></li></ol><ul><li class="ql-indent-1">A starts work and B joins later or leaves early.</li></ul><ol><li><strong>Type 4: Efficiency Ratio Problems</strong></li></ol><ul><li class="ql-indent-1">Time ratio to efficiency ratio conversion.</li></ul><ol><li><strong>Type 5: Work &amp; Wages Problems</strong></li></ol><ul><li class="ql-indent-1">Wages distributed in ratio of work done (or efficiency × time).</li></ul><ol><li><strong>Type 6: Alternate Day Work Problems</strong></li></ol><ul><li class="ql-indent-1">A and B work alternately or cyclically.</li></ul><ol><li><strong>Type 7: Pipes &amp; Cistern Type (Extension)</strong></li></ol><ul><li class="ql-indent-1">One or more pipes filling/emptying a tank.</li></ul><p><br></p><h3>6. STEP-BY-STEP SOLUTION METHODS</h3><p><strong>Example 2:</strong></p><p> A can do a work in 20 days, B in 30 days. A works for 5 days and leaves; B completes the rest. How many total days?</p><p><strong>Step 1:</strong> Total work = 1 unit</p><p> A’s 1 day work = 1/20 → In 5 days, A does 5/20 = 1/4 work.</p><p> <strong>Step 2:</strong> Remaining = 3/4 work.</p><p> B’s 1 day work = 1/30 → Time = (3/4) ÷ (1/30) = (3/4) × 30 = 22.5 days</p><p> <strong>Step 3:</strong> Total = 5 + 22.5 = 27.5 days.</p><p><strong>Example 3:</strong></p><p> If A is 50% more efficient than B, find their time ratio.</p><p>Efficiency ratio = 150 : 100 = 3 : 2</p><p> Time ratio = 2 : 3</p><p><br></p><h3>7. CONCLUSION</h3><p>Time and Work is a vital arithmetic topic combining proportional reasoning and efficiency analysis. It connects directly to Pipes &amp; Cisterns, Wages, and Speed-Time relations. Mastering this topic requires understanding unitary methods and developing speed using efficiency ratios.</p><p><strong>Key Takeaways:</strong></p><ul><li>Always convert days to <em>one-day work</em> first.</li><li>Efficiency and time are inversely proportional.</li><li>For group work, use combined work rate addition.</li><li>Handle “leaving early” or “joining late” logically by isolating work done.</li></ul><p><br></p><p><strong>Practice Question:</strong></p><p>A can do a work in 10 days and B in 15 days. How long will they take to finish it together?</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b325');

-- 26. Compound Interest -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b226
INSERT INTO topics (id, subject_id, unit_id, name, description, difficulty, display_order, is_active, created_at, updated_at)
SELECT 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b226', '55555555-5555-5555-5555-555555555501',
    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Compound Interest',
    'Interest calculated on principal plus accumulated interest using exponential growth', 'MEDIUM', 54, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE id = 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b226');
INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b326', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b226',
    'Compound Interest Concepts',
    '<p>1. CONCEPTUAL FOUNDATION</p><p><strong>Definition:</strong></p><p> Compound Interest (CI) is the interest calculated not only on the <em>original principal</em> but also on the <em>accumulated interest</em> from previous periods. This means the interest keeps increasing because every period’s interest is added to the principal before calculating the next interest.</p><p><strong>Real-Life Context:</strong></p><ul><li>Bank fixed deposits and savings accounts</li><li>Recurring deposits</li><li>Investment growth and business capital appreciation</li><li>Credit card balances and long-term loans</li></ul><p><strong>Mathematical Significance:</strong></p><p> Compound Interest represents <em>exponential growth</em> and introduces the concept of <em>geometric progression</em> in finance. It is an advanced version of Simple Interest.</p><p><strong>Prerequisites:</strong></p><ul><li>Understanding of Simple Interest</li><li>Basic percentage and ratio calculations</li><li>Power and exponents concept (indices)</li></ul><h3>2. CORE THEORY &amp; PRINCIPLES</h3><ol><li><strong>Basic Concept:</strong></li><li> Interest is added to the principal at the end of each compounding period. Thus, every new period earns interest on a <em>larger</em> amount.</li><li><strong>Key Relationship:</strong></li></ol><ul><li class="ql-indent-1">$A = P + CI$</li><li class="ql-indent-1">Amount (A) is the total sum after interest is added.</li></ul><ol><li><strong>Compounding Principle:</strong></li></ol><ul><li>For annual compounding:</li><li class="ql-indent-1"> $A = P \left(1 + \dfrac{R}{100}\right)^T$</li><li>For half-yearly compounding:</li><li class="ql-indent-1"> $A = P \left(1 + \dfrac{R}{2 \times 100}\right)^{2T}$</li><li>For quarterly compounding:</li><li class="ql-indent-1"> $A = P \left(1 + \dfrac{R}{4 \times 100}\right)^{4T}$</li></ul><ol><li><strong>Compound Interest Formula:</strong></li><li> $CI = A - P = P\left[\left(1 + \dfrac{R}{100}\right)^T - 1\right]$</li><li><strong>Growth Nature:</strong></li></ol><ul><li class="ql-indent-1">CI increases faster than SI for the same rate and time.</li><li class="ql-indent-1">The difference between CI and SI increases with both rate and time.</li></ul><ol><li><strong>Relation Between CI and SI:</strong></li><li> For small rates or short periods, CI ≈ SI.</li></ol><h3>3. MAGIC SHORTCUTS</h3><ol><li><strong>Shortcut 1 – Successive Percentage Method (for 2 or 3 years):</strong></li></ol><ul><li>For 2 years:</li><li class="ql-indent-1"> $CI = P\left[\dfrac{R}{100} + \left(\dfrac{R}{100}\right)^2\right]$</li><li>For 3 years:</li><li class="ql-indent-1"> $CI = P\left[\dfrac{R}{100} + 3\left(\dfrac{R}{100}\right)^2 + \left(\dfrac{R}{100}\right)^3\right]$</li></ul><ol><li><strong>Shortcut 2 – Difference Between CI and SI for 2 Years:</strong></li><li> $CI - SI = P\left(\dfrac{R}{100}\right)^2$</li><li><strong>Shortcut 3 – Doubling and Tripling Time Rules:</strong></li></ol><ul><li>To <em>double</em> the money:</li><li class="ql-indent-1"> $T = \dfrac{72}{R}$ (Rule of 72 – approximate)</li><li>To <em>triple</em> the money:</li><li class="ql-indent-1"> $T = \dfrac{114}{R}$ (Rule of 114 – approximate)</li></ul><ol><li><strong>Shortcut 4 – Finding Rate Quickly (for 2 years):</strong></li><li> If CI for 2 years = ₹x and SI = ₹y,</li><li> $R = \sqrt{\dfrac{100^2 \times (x - y)}{P}}$ (approx method for quick comparison)</li><li><strong>Shortcut 5 – Successive Rate Shortcut:</strong></li><li> When two rates R₁% and R₂% are applied successively:</li><li> Equivalent single rate = $R_1 + R_2 + \dfrac{R_1 R_2}{100}$</li></ol><h3>4. ESSENTIAL FORMULAE &amp; METHODS</h3><ol><li><strong>For Annual Compounding:</strong></li><li> $A = P\left(1 + \dfrac{R}{100}\right)^T$</li><li> $CI = A - P = P\left[\left(1 + \dfrac{R}{100}\right)^T - 1\right]$</li><li><strong>For Half-Yearly Compounding:</strong></li><li> $A = P\left(1 + \dfrac{R/2}{100}\right)^{2T}$</li><li><strong>For Quarterly Compounding:</strong></li><li> $A = P\left(1 + \dfrac{R/4}{100}\right)^{4T}$</li><li><strong>For Different Rates Each Year:</strong></li><li> $A = P\left(1 + \dfrac{R_1}{100}\right)\left(1 + \dfrac{R_2}{100}\right)\left(1 + \dfrac{R_3}{100}\right)...$</li><li><strong>Difference Between CI and SI (for 2 years):</strong></li><li> $CI - SI = P\left(\dfrac{R}{100}\right)^2$</li><li><strong>For 3 Years:</strong></li><li> $CI - SI = P\left[\dfrac{R^2(300 + R)}{100^3}\right]$</li><li><strong>Amount Doubling or Tripling:</strong></li></ol><ul><li>$2P = P(1 + R/100)^T$</li><li class="ql-indent-1"> → $T = \dfrac{\log 2}{\log(1 + R/100)}$</li><li>$3P = P(1 + R/100)^T$</li><li class="ql-indent-1"> → $T = \dfrac{\log 3}{\log(1 + R/100)}$</li></ul><h3>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</h3><ol><li><strong>Type 1: Direct CI Calculation</strong></li></ol><ul><li class="ql-indent-1">Compute CI and A using formula for annual compounding.</li></ul><ol><li><strong>Type 2: Half-Yearly or Quarterly Compounding</strong></li></ol><ul><li class="ql-indent-1">Adjust rate and time accordingly.</li></ul><ol><li><strong>Type 3: Different Rates for Different Years</strong></li></ol><ul><li class="ql-indent-1">Apply successive multiplication of rates.</li></ul><ol><li><strong>Type 4: Find P, R, or T When Others Known</strong></li></ol><ul><li class="ql-indent-1">Rearrange formula accordingly.</li></ul><ol><li><strong>Type 5: Difference Between CI and SI</strong></li></ol><ul><li class="ql-indent-1">Use specific formulas for 2 or 3 years.</li></ul><ol><li><strong>Type 6: Population Growth / Depreciation Problems</strong></li></ol><ul><li class="ql-indent-1">Growth: $P(1 + R/100)^T$</li><li class="ql-indent-1">Depreciation: $P(1 - R/100)^T$</li></ul><ol><li><strong>Type 7: Installment and Variable Rate Problems</strong></li></ol><ul><li class="ql-indent-1">Calculate CI on reduced balances or varying interest rates.</li></ul><h3>6. STEP-BY-STEP SOLUTION METHODS</h3><p><strong>Example 2:</strong></p><p> Find CI on ₹8,000 for 1.5 years at 10% per annum compounded half-yearly.</p><p><strong>Step 1:</strong> Half-yearly rate = 10/2 = 5%</p><p> <strong>Step 2:</strong> Time = 1.5 years = 3 half-years</p><p> <strong>Step 3:</strong> $A = 8000(1 + 5/100)^3 = 8000(1.157625)$</p><p> <strong>Step 4:</strong> $A = ₹9261$</p><p> <strong>Step 5:</strong> $CI = 9261 - 8000 = ₹1261$</p><p><strong>Answer:</strong> CI = ₹1261</p><p><br></p><p><strong>Example 3:</strong></p><p> Find CI on ₹10,000 for 3 years, rates being 10%, 12%, and 15% for each year respectively.</p><p><strong>Step 1:</strong></p><p> $A = 10000(1 + 10/100)(1 + 12/100)(1 + 15/100)$</p><p> = $10000 × 1.10 × 1.12 × 1.15$</p><p> = $10000 × 1.4208 = ₹14208$</p><p> <strong>Step 2:</strong> $CI = 14208 - 10000 = ₹4208$</p><p><strong>Answer:</strong> CI = ₹4208</p><p><br></p><p><strong>Example 4:</strong></p><p> Find the difference between CI and SI on ₹5,000 for 2 years at 10% p.a.</p><p><strong>Step 1:</strong> Difference = $P(R/100)^2 = 5000(10/100)^2 = 5000 × 1/100 = ₹50$</p><p> <strong>Step 2:</strong> CI – SI = ₹50</p><p><strong>Answer:</strong> ₹50</p><p><br></p><h3>7. CONCLUSION</h3><p><strong>Summary of Key Points:</strong></p><ul><li>Compound Interest grows exponentially, unlike Simple Interest.</li><li>Interest is added to principal periodically, leading to higher returns.</li><li>The frequency of compounding (annual, half-yearly, quarterly) affects the final amount.</li><li>CI is closely related to population growth, inflation, and depreciation models.</li></ul><p><strong>Tips for Students:</strong></p><ul><li>Memorize the annual, half-yearly, and quarterly compounding formulas.</li><li>For 2 or 3 years, use successive percentage shortcut instead of full expansion.</li><li>Always check whether time is in years or fractions.</li><li>For growth/depreciation, remember:</li><li class="ql-indent-1">Growth → $(1 + R/100)$</li><li class="ql-indent-1">Depreciation → $(1 - R/100)$</li></ul><p><br></p><p><strong>Practice Question:</strong></p><p>Find CI on ₹5,000 for 2 years at 10% per annum compounded annually.</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b326');

