INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b327', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b227',
    'Statistics Concepts',
    '<h2><strong>1. CONCEPTUAL FOUNDATION</strong></h2><p><strong>Definition:</strong></p><p> Statistics deals with the <em>collection, organization, analysis, and interpretation of numerical data</em> to extract meaningful information. It helps summarize large sets of data in simple numerical forms such as <em>mean, median, mode</em>, and graphical representations like <em>bar graphs, pie charts, histograms</em>, etc.</p><p><strong>Purpose:</strong></p><p> To make informed decisions or comparisons based on data patterns rather than individual data points.</p><p><strong>Real-Life Relevance:</strong></p><ul><li>Used in exam score analysis, sales reports, surveys, population studies, and data interpretation questions.</li><li>Frequently appears in aptitude tests through charts, tables, or diagrams.</li></ul><p><strong>Key Concept:</strong></p><p> Statistics focuses on <strong>central tendency</strong> (how data clusters around a center) and <strong>dispersion</strong> (how data spreads).</p><p><strong>Connection to Other Topics:</strong></p><p> Closely related to <em>Averages, Ratio &amp; Proportion, and Data Interpretation (DI)</em>.</p><p><br></p><h2><strong>2. CORE THEORY &amp; PRINCIPLES</strong></h2><h3><strong>Measures of Central Tendency:</strong></h3><p>These indicate the central or typical value of a dataset.</p><ol><li><strong>Mean (Arithmetic Average):</strong></li><li> $Mean = \dfrac{Sum\ of\ observations}{Number\ of\ observations}$</li><li> Every observation affects the mean.</li><li><strong>Median:</strong></li></ol><ul><li class="ql-indent-1">The <em>middle value</em> when data is arranged in ascending or descending order.</li><li class="ql-indent-1">If n is odd → Middle term.</li><li class="ql-indent-1">If n is even → Average of two middle terms.</li><li class="ql-indent-1">Median is <em>not affected</em> by extreme values (outliers).</li></ul><ol><li><strong>Mode:</strong></li></ol><ul><li class="ql-indent-1">The <em>most frequently occurring</em> value.</li><li class="ql-indent-1">Can be determined directly from data or visually from graphs (modal class).</li></ul><h3><strong>Relationship between Mean, Median, and Mode:</strong></h3><p>$Mode = 3(Median) - 2(Mean)$</p><p><br></p><h3><strong>Measures of Dispersion:</strong></h3><p>Indicate how spread out data is.</p><ol><li><strong>Range = Highest value – Lowest value</strong></li><li><strong>Variance &amp; Standard Deviation (for advanced exams):</strong></li></ol><ul><li class="ql-indent-1">Variance = Average of squared deviations from mean</li><li class="ql-indent-1">SD = √Variance</li></ul><p><br></p><h3><strong>Frequency Distribution:</strong></h3><p>When data is large, it is grouped into <em>classes</em> or <em>intervals</em> with frequencies.</p><p> Mean, median, and mode can be computed using shortcut methods from such tables.</p><p><br></p><h2><strong>3. MAGIC SHORTCUTS</strong></h2><p><strong>Mean from Frequency Table (Shortcut Formula):</strong></p><p>$Mean = A + \dfrac{\sum f d}{\sum f}$</p><p>where</p><ul><li class="ql-indent-1">A = Assumed mean</li><li class="ql-indent-1">d = (x – A)/class width</li><li class="ql-indent-1">f = frequency</li></ul><p>➜ This “step deviation method” is the fastest approach for grouped data.</p><p><strong>Median for Grouped Data:</strong></p><p>$Median = L + \dfrac{\dfrac{N}{2} - F}{f_m} × c$</p><p>where</p><ul><li class="ql-indent-1">L = lower boundary of median class</li><li class="ql-indent-1">N = total frequency</li><li class="ql-indent-1">F = cumulative frequency before median class</li><li class="ql-indent-1">fₘ = frequency of median class</li><li class="ql-indent-1">c = class width</li></ul><p><strong>Mode for Grouped Data:</strong></p><p>$Mode = L + \dfrac{(f_1 - f_0)}{(2f_1 - f_0 - f_2)} × c$</p><p>where</p><ul><li class="ql-indent-1">f₁ = frequency of modal class</li><li class="ql-indent-1">f₀, f₂ = frequencies before and after modal class</li><li class="ql-indent-1">L = lower boundary of modal class</li></ul><p><strong>Short Verification:</strong></p><p>In a moderately skewed distribution,</p><p>Mean &gt; Median &gt; Mode</p><p>or</p><p>Mode &gt; Median &gt; Mean</p><p>(Use this pattern to cross-check calculations!)</p><p><br></p><h2><strong>4. ESSENTIAL FORMULAE &amp; METHODS</strong></h2><table table_id="l8razrzb89d" id="l8razrzb89d" class=""><tr row_id="5yembtmyf89" style="width: 100%;"><td table_id="l8razrzb89d" row_id="5yembtmyf89" cell_id="b7fi6ndsaw" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Concept</strong></p></td><td table_id="l8razrzb89d" row_id="5yembtmyf89" cell_id="vytq7qrg1o" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Formula</strong></p></td><td table_id="l8razrzb89d" row_id="5yembtmyf89" cell_id="43v6stpbz74" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Notes</strong></p></td></tr><tr row_id="lv3nlf17w3i" style="width: 100%;"><td table_id="l8razrzb89d" row_id="lv3nlf17w3i" cell_id="sk8za58qln" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Mean (Ungrouped Data)</span></p></td><td table_id="l8razrzb89d" row_id="lv3nlf17w3i" cell_id="l06h30e1bds" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\bar{x} = \dfrac{\sum x}{n}$</span></p></td><td table_id="l8razrzb89d" row_id="lv3nlf17w3i" cell_id="35ok88tgigq" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Direct calculation</span></p></td></tr><tr row_id="sc263xfnfj" style="width: 100%;"><td table_id="l8razrzb89d" row_id="sc263xfnfj" cell_id="ukf349wv5q" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Mean (Grouped Data)</span></p></td><td table_id="l8razrzb89d" row_id="sc263xfnfj" cell_id="b8k1mklyf9d" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\bar{x} = \dfrac{\sum f x}{\sum f}$</span></p></td><td table_id="l8razrzb89d" row_id="sc263xfnfj" cell_id="imjpkml5kh" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Using midpoints</span></p></td></tr><tr row_id="r25654zeuzr" style="width: 100%;"><td table_id="l8razrzb89d" row_id="r25654zeuzr" cell_id="phnvrh47y98" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Step-Deviation Mean</span></p></td><td table_id="l8razrzb89d" row_id="r25654zeuzr" cell_id="wwur24y4qc" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\bar{x} = A + \dfrac{\sum f d}{\sum f} × c$</span></p></td><td table_id="l8razrzb89d" row_id="r25654zeuzr" cell_id="gay3zqp566" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Fastest for large data</span></p></td></tr><tr row_id="e3nzo2k44vb" style="width: 100%;"><td table_id="l8razrzb89d" row_id="e3nzo2k44vb" cell_id="h7rq0rnzd2f" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Median (Ungrouped)</span></p></td><td table_id="l8razrzb89d" row_id="e3nzo2k44vb" cell_id="kfrhljt5p1" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Middle term(s)</span></p></td><td table_id="l8razrzb89d" row_id="e3nzo2k44vb" cell_id="r2b17e1z48o" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Arrange in order first</span></p></td></tr><tr row_id="5q0tuepjgs2" style="width: 100%;"><td table_id="l8razrzb89d" row_id="5q0tuepjgs2" cell_id="w6frbwptrm" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Median (Grouped)</span></p></td><td table_id="l8razrzb89d" row_id="5q0tuepjgs2" cell_id="9lmdb6zp8i8" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$L + \dfrac{(N/2 - F)}{f_m} × c$</span></p></td><td table_id="l8razrzb89d" row_id="5q0tuepjgs2" cell_id="aabqhy6rtk" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Use cumulative frequency</span></p></td></tr><tr row_id="5utjsht7hoj" style="width: 100%;"><td table_id="l8razrzb89d" row_id="5utjsht7hoj" cell_id="olmf3n6uya8" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Mode (Grouped)</span></p></td><td table_id="l8razrzb89d" row_id="5utjsht7hoj" cell_id="byd11bdf87" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$L + \dfrac{(f_1 - f_0)}{(2f_1 - f_0 - f_2)} × c$</span></p></td><td table_id="l8razrzb89d" row_id="5utjsht7hoj" cell_id="phm7yvf8ycg" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Mode = most frequent class</span></p></td></tr><tr row_id="5032dzmgqv" style="width: 100%;"><td table_id="l8razrzb89d" row_id="5032dzmgqv" cell_id="cndw0fsrx6c" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Range</span></p></td><td table_id="l8razrzb89d" row_id="5032dzmgqv" cell_id="thbxig55z8r" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Max – Min</span></p></td><td table_id="l8razrzb89d" row_id="5032dzmgqv" cell_id="5x0paxa9jos" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Simplest dispersion measure</span></p></td></tr><tr row_id="k4jzzsyg6rn" style="width: 100%;"><td table_id="l8razrzb89d" row_id="k4jzzsyg6rn" cell_id="hsv24zywnv" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Mean–Median–Mode Relation</span></p></td><td table_id="l8razrzb89d" row_id="k4jzzsyg6rn" cell_id="3gklh0md05r" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$Mode = 3(Median) - 2(Mean)$</span></p></td><td table_id="l8razrzb89d" row_id="k4jzzsyg6rn" cell_id="m2jutbsp7n9" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Only for normal distributions</span></p></td></tr></table><p><br></p><h2><strong>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</strong></h2><table table_id="0cghnpfkslts" id="0cghnpfkslts" class=""><tr row_id="my9k7fsu94" style="width: 100%;"><td table_id="0cghnpfkslts" row_id="my9k7fsu94" cell_id="xiq3d6084jg" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model Type</strong></p></td><td table_id="0cghnpfkslts" row_id="my9k7fsu94" cell_id="h5ifya7n0l4" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Description</strong></p></td><td table_id="0cghnpfkslts" row_id="my9k7fsu94" cell_id="j8yi53carr" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Identification Keywords</strong></p></td></tr><tr row_id="wyz01w0ytmn" style="width: 100%;"><td table_id="0cghnpfkslts" row_id="wyz01w0ytmn" cell_id="8pww4n0nh6p" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model 1:</strong><span style="background-color: transparent; color: rgb(0, 0, 0);"> Direct Mean Problems</span></p></td><td table_id="0cghnpfkslts" row_id="wyz01w0ytmn" cell_id="ldxp3hr39d" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Find average of numbers</span></p></td><td table_id="0cghnpfkslts" row_id="wyz01w0ytmn" cell_id="mh3zqu7gf2i" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">“Find mean/average”</span></p></td></tr><tr row_id="d7y4dk1uc7" style="width: 100%;"><td table_id="0cghnpfkslts" row_id="d7y4dk1uc7" cell_id="pze7sd351ln" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model 2:</strong><span style="background-color: transparent; color: rgb(0, 0, 0);"> Weighted Mean</span></p></td><td table_id="0cghnpfkslts" row_id="d7y4dk1uc7" cell_id="13geg64wrqib" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Different importance given</span></p></td><td table_id="0cghnpfkslts" row_id="d7y4dk1uc7" cell_id="umw57kg2ke" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">“Weights, importance, frequency”</span></p></td></tr><tr row_id="2rqxyrn6ydi" style="width: 100%;"><td table_id="0cghnpfkslts" row_id="2rqxyrn6ydi" cell_id="mmr1feu9fs" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model 3:</strong><span style="background-color: transparent; color: rgb(0, 0, 0);"> Median-Based</span></p></td><td table_id="0cghnpfkslts" row_id="2rqxyrn6ydi" cell_id="uictzdxlxl" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Middle term calculation</span></p></td><td table_id="0cghnpfkslts" row_id="2rqxyrn6ydi" cell_id="odzxk7q0zic" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">“Middle value, halfway, 50th percentile”</span></p></td></tr><tr row_id="ag4q92ask8t" style="width: 100%;"><td table_id="0cghnpfkslts" row_id="ag4q92ask8t" cell_id="whqvg9j4zwf" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model 4:</strong><span style="background-color: transparent; color: rgb(0, 0, 0);"> Mode-Based</span></p></td><td table_id="0cghnpfkslts" row_id="ag4q92ask8t" cell_id="zk92ueszoi" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Highest frequency data</span></p></td><td table_id="0cghnpfkslts" row_id="ag4q92ask8t" cell_id="adetagc2el" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">“Most frequent, common value”</span></p></td></tr><tr row_id="mkhnuv2v329" style="width: 100%;"><td table_id="0cghnpfkslts" row_id="mkhnuv2v329" cell_id="ewtfzgdcle8" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model 5:</strong><span style="background-color: transparent; color: rgb(0, 0, 0);"> Grouped Data</span></p></td><td table_id="0cghnpfkslts" row_id="mkhnuv2v329" cell_id="lwgu6tp9ma" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Class intervals given</span></p></td><td table_id="0cghnpfkslts" row_id="mkhnuv2v329" cell_id="2xls583ana1" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">“0–10, 10–20, etc.”</span></p></td></tr><tr row_id="ufl2bddntun" style="width: 100%;"><td table_id="0cghnpfkslts" row_id="ufl2bddntun" cell_id="8epua8t9amg" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model 6:</strong><span style="background-color: transparent; color: rgb(0, 0, 0);"> Missing Frequency</span></p></td><td table_id="0cghnpfkslts" row_id="ufl2bddntun" cell_id="ud15k1ou4hs" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">One frequency missing</span></p></td><td table_id="0cghnpfkslts" row_id="ufl2bddntun" cell_id="4ggzctukqrq" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">“Find missing frequency when mean given”</span></p></td></tr><tr row_id="mbxfe53qdr" style="width: 100%;"><td table_id="0cghnpfkslts" row_id="mbxfe53qdr" cell_id="77cxuoncr13" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model 7:</strong><span style="background-color: transparent; color: rgb(0, 0, 0);"> Graph Interpretation</span></p></td><td table_id="0cghnpfkslts" row_id="mbxfe53qdr" cell_id="fepsw8655s" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">From bar/pie/histogram</span></p></td><td table_id="0cghnpfkslts" row_id="mbxfe53qdr" cell_id="g14ol8n6wgt" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">“Refer to diagram/chart”</span></p></td></tr><tr row_id="2z2bph73mim" style="width: 100%;"><td table_id="0cghnpfkslts" row_id="2z2bph73mim" cell_id="i0ivjp1idd" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Model 8:</strong><span style="background-color: transparent; color: rgb(0, 0, 0);"> Range/Dispersion</span></p></td><td table_id="0cghnpfkslts" row_id="2z2bph73mim" cell_id="aryzh9crzdp" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Spread of data</span></p></td><td table_id="0cghnpfkslts" row_id="2z2bph73mim" cell_id="j3qmjpgj1wg" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">“Difference between max and min”</span></p></td></tr></table><p><br></p><h2><strong>6. STEP-BY-STEP SOLUTION METHODS</strong></h2><h3>Example 1: Mean from Frequency Table</h3><p>Find mean for the following data:</p><p> x: 2, 4, 6, 8, 10</p><p> f: 3, 5, 7, 4, 1</p><p>Step 1: Multiply each x by its f → ∑fx = (2×3 + 4×5 + 6×7 + 8×4 + 10×1) = 6 + 20 + 42 + 32 + 10 = 110</p><p> Step 2: ∑f = 20</p><p> Step 3: Mean = 110 ÷ 20 = <strong>5.5</strong></p><h3>Example 2: Median for Ungrouped Data</h3><p>Data: 5, 8, 10, 12, 15</p><p> n = 5 (odd) → Median = 3rd term = <strong>10</strong></p><p>If even → average of two middle values.</p><h3>Example 3: Mode from Ungrouped Data</h3><p>Data: 4, 5, 6, 5, 8, 5, 7 → Mode = <strong>5</strong></p><h3>Example 4: Grouped Median</h3><p>Class: 0–10, 10–20, 20–30, 30–40</p><p> Freq: 5, 8, 15, 2</p><p>N = 30, N/2 = 15</p><p> Cumulative frequency: 5, 13, 28 → Median class = 20–30</p><p> Using formula:</p><p> Median = 20 + [(15 – 13)/15]×10 = 20 + (2/15)×10 = <strong>21.33</strong></p><h3>Example 5: Mode (Grouped Data)</h3><p>Class: 10–20, 20–30, 30–40, 40–50</p><p> Freq: 5, 9, 12, 8</p><p>Modal class = 30–40</p><p> L = 30, f₁=12, f₀=9, f₂=8, c=10</p><p> Mode = 30 + [(12–9)/(2×12–9–8)]×10 = 30 + (3/7)×10 = <strong>34.3</strong></p><h3>Example 6: Range</h3><p>Marks = 12, 18, 10, 20, 25</p><p> Range = 25 – 10 = <strong>15</strong></p><h2><br></h2><h2><strong style="background-color: transparent; color: rgb(0, 0, 0);">7. VISUAL &amp; GRAPHICAL REPRESENTATION (Extra Section)</strong></h2><table table_id="w91wl1vy8t8" id="w91wl1vy8t8" class=""><tr row_id="c6u8dyq98b" style="width: 100%;"><td table_id="w91wl1vy8t8" row_id="c6u8dyq98b" cell_id="jm9fenonjpa" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Graph Type</strong></p></td><td table_id="w91wl1vy8t8" row_id="c6u8dyq98b" cell_id="1py511fyan3" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Description</strong></p></td><td table_id="w91wl1vy8t8" row_id="c6u8dyq98b" cell_id="6ahq7cflr8" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Quick Identification</strong></p></td></tr><tr row_id="wqsz1ri3ku" style="width: 100%;"><td table_id="w91wl1vy8t8" row_id="wqsz1ri3ku" cell_id="quj33m1ouis" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Bar Graph</strong></p></td><td table_id="w91wl1vy8t8" row_id="wqsz1ri3ku" cell_id="9u8801iey5g" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Shows comparison between categories</span></p></td><td table_id="w91wl1vy8t8" row_id="wqsz1ri3ku" cell_id="d5o8wu5jpfc" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Bars with equal width</span></p></td></tr><tr row_id="f6x5jgv4ayc" style="width: 100%;"><td table_id="w91wl1vy8t8" row_id="f6x5jgv4ayc" cell_id="ask5v7xmpk9" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Histogram</strong></p></td><td table_id="w91wl1vy8t8" row_id="f6x5jgv4ayc" cell_id="02ndp4n3zrsd" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Continuous data frequency distribution</span></p></td><td table_id="w91wl1vy8t8" row_id="f6x5jgv4ayc" cell_id="e6dxa10pcfj" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">No gaps between bars</span></p></td></tr><tr row_id="cl2gb67rcae" style="width: 100%;"><td table_id="w91wl1vy8t8" row_id="cl2gb67rcae" cell_id="3ow1vp49km5" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Pie Chart</strong></p></td><td table_id="w91wl1vy8t8" row_id="cl2gb67rcae" cell_id="cjzr40kh8uw" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Circular representation of data</span></p></td><td table_id="w91wl1vy8t8" row_id="cl2gb67rcae" cell_id="hruzr0rk6qo" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Sum = 360°, shows proportion</span></p></td></tr><tr row_id="xxqf0do5ywg" style="width: 100%;"><td table_id="w91wl1vy8t8" row_id="xxqf0do5ywg" cell_id="7ivqi1gaacx" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Frequency Polygon</strong></p></td><td table_id="w91wl1vy8t8" row_id="xxqf0do5ywg" cell_id="gcdedmna304" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Line joining midpoints of histogram bars</span></p></td><td table_id="w91wl1vy8t8" row_id="xxqf0do5ywg" cell_id="2cpeh9xwrr7" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Used for visual trends</span></p></td></tr></table><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Shortcut for Pie Chart:</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Angle for a component = (Value ÷ Total) × 360°</span></p><p><br></p><h2>8. COMMON TRAPS &amp; MISCONCEPTIONS </h2><ul><li>Confusing <strong>frequency</strong> with <strong>data values</strong> while calculating mean.</li><li>Forgetting to take <strong>cumulative frequencies</strong> for median formula.</li><li>Misidentifying <strong>modal class</strong> (it’s based on highest frequency).</li><li>Using <strong>simple average</strong> instead of <strong>weighted mean</strong> when frequencies differ.</li><li>In pie charts, forgetting that <strong>total = 360°</strong>.</li></ul><p><br></p><h2>9. CONCLUSION</h2><p><strong>Key Takeaways:</strong></p><ul><li><strong>Mean</strong>: Mathematical center (affected by all values).</li><li><strong>Median</strong>: Middle observation (resistant to extremes).</li><li><strong>Mode</strong>: Most frequent value (useful for categorical data).</li><li><strong>Range</strong>: Quick measure of spread.</li><li>Use appropriate shortcut formulas for grouped data.</li><li>Always cross-check Mean–Median–Mode relationship.</li></ul><p><strong>Speed Tips:</strong></p><ul><li>For grouped data, prefer <em>assumed mean</em> or <em>step deviation method</em>.</li><li>For median, cumulative frequency chart saves time.</li><li>For pie charts, pre-calculate 1% = 3.6° to convert quickly.</li></ul><p><br></p><p><strong>Practice Question:</strong></p><p>Find the mean of the following data:</p><p> 5, 8, 12, 15, 20</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b327');

-- 28. Stocks & Shares -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b228
INSERT INTO topics (id, subject_id, unit_id, name, description, difficulty, display_order, is_active, created_at, updated_at)
SELECT 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b228', '55555555-5555-5555-5555-555555555501',
    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Stocks & Shares',
    'Focuses on investment, dividend, brokerage calculations, and market value concepts', 'MEDIUM', 56, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE id = 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b228');
INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b328', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b228',
    'Stocks & Shares Concepts',
    '<h3>1. CONCEPTUAL FOUNDATION</h3><p>Stocks and shares are fundamental concepts in commercial arithmetic related to investment, profit, and dividend calculations.</p><p>A <strong>stock</strong> represents a part ownership in a company, while a <strong>share</strong> is a single unit of that stock.</p><p>When a person buys shares, they invest money and become entitled to a portion of the company’s profits, called <strong>dividends</strong>.</p><p>Key terms:</p><ul><li><strong>Face Value (Nominal Value)</strong>: The printed value on the share (e.g., ₹100).</li><li><strong>Market Value</strong>: The price at which the share is bought or sold in the market.</li><li><strong>Dividend</strong>: The return (profit) declared on the face value of the share, expressed as a percentage.</li><li><strong>Brokerage</strong>: The commission charged by a broker for buying or selling shares.</li></ul><p><br></p><h3>2. CORE THEORY &amp; PRINCIPLES</h3><ol><li><strong>Dividend Calculation</strong>:</li><li>Dividend is always calculated on the <strong>Face Value</strong>, not the Market Value.</li><li>Example: If a 10% dividend is declared on ₹100 share, dividend per share = ₹10.</li><li><strong>Investor’s Return (Yield)</strong>:</li><li>Actual return depends on the <strong>Market Value</strong> — how much the investor paid.</li><li><strong>Classification of Shares</strong>:</li></ol><ul><li><strong>At Par</strong>: Market Value = Face Value.<strong>At Premium</strong>: Market Value &gt; Face Value.<strong>At Discount</strong>: Market Value &lt; Face Value.</li></ul><ol><li><strong>Brokerage Impact</strong>:</li></ol><ul><li>If brokerage is charged on purchase, it increases the cost price.If brokerage is charged on sale, it decreases the selling price.</li></ul><p><br></p><h3>3. MAGIC SHORTCUTS</h3><ol><li><strong>To find Income (Dividend)</strong>:</li><li>Income = $\frac{\text{Face Value} \times \text{Rate of Dividend}}{100}$</li><li><strong>To find Yield (Rate of Return)</strong>:</li><li>Yield % = $\frac{\text{Income}}{\text{Market Value}} \times 100$</li><li><strong>To find Market Value for a desired yield</strong>:</li><li>Market Value = $\frac{\text{Income} \times 100}{\text{Required Yield %}}$</li><li><strong>Brokerage Adjustments</strong>:</li></ol><ul><li>For buying: Effective cost = Market Value + BrokerageFor selling: Effective sale price = Market Value – Brokerage</li></ul><p><br></p><h3>4. ESSENTIAL FORMULAE &amp; METHODS</h3><ol><li><strong>Dividend per Share</strong> = $\frac{\text{Face Value} \times \text{Dividend %}}{100}$</li><li><strong>Income from Investment</strong> = $\frac{\text{Investment} \times \text{Dividend %} \times \text{Face Value}}{100 \times \text{Market Value}}$</li><li><strong>Yield % (Rate of Return)</strong> = $\frac{\text{Dividend per Share}}{\text{Market Value}} \times 100$</li><li><strong>Market Value for a given yield</strong> = $\frac{\text{Dividend per Share} \times 100}{\text{Required Yield %}}$</li></ol><p><br></p><h3>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</h3><p><strong>Model 1:</strong> Finding income, given investment details.</p><p><strong>Model 2:</strong> Finding investment, given income and yield.</p><p><strong>Model 3:</strong> Finding market value or yield when brokerage is included.</p><p><strong>Model 4:</strong> Comparing two different stock investments for better return.</p><p><strong>Model 5:</strong> Determining total income from mixed shares portfolio.</p><p><br></p><h3>6. STEP-BY-STEP SOLUTION METHODS</h3><p><strong>Example 1:</strong></p><p>Find the income from ₹4500 invested in ₹100 shares at ₹120, paying 10% dividend.</p><p><strong>Step 1:</strong> Dividend per share = $\frac{100 \times 10}{100} = ₹10$</p><p><strong>Step 2:</strong> Number of shares = $\frac{4500}{120} = 37.5$</p><p><strong>Step 3:</strong> Total income = $37.5 \times 10 = ₹375$</p><p>Hence, the annual income is <strong>₹375</strong>.</p><p><br></p><p><strong>Example 2:</strong></p><p>Find the yield percentage if a ₹100 share pays 9% dividend and is bought at ₹120.</p><p><strong>Step 1:</strong> Dividend per share = ₹9</p><p><strong>Step 2:</strong> Yield % = $\frac{9}{120} \times 100 = 7.5%$</p><p>Hence, the yield is <strong>7.5%</strong>.</p><p><br></p><p><strong>Example 3:</strong></p><p>At what price should a ₹100 share paying 8% dividend be bought to yield 10% return?</p><p><strong>Step 1:</strong> Dividend per share = ₹8</p><p><strong>Step 2:</strong> Market Value = $\frac{8 \times 100}{10} = ₹80$</p><p>Hence, the share should be bought at <strong>₹80</strong>.</p><p><br></p><h3>7. CONCLUSION</h3><ul><li>Stocks &amp; Shares problems combine concepts of percentage, ratio, and profit.</li><li>Always remember: <strong>Dividend is on Face Value, but return is on Market Value.</strong></li><li>Brokerage plays a key role in real market-based calculations.</li><li>A strong grasp of the relationship between face value, market value, and yield helps quickly solve exam-level problems.</li></ul><p><br></p><p>Practice Question:</p><p>A ₹100 face value share pays 8% dividend. At what market price should it be bought to earn a 10% yield (ignore brokerage)?</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b328');

-- 29. Mensuration -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b229
INSERT INTO topics (id, subject_id, unit_id, name, description, difficulty, display_order, is_active, created_at, updated_at)
SELECT 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b229', '55555555-5555-5555-5555-555555555501',
    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Mensuration',
    'Measures area, volume, and perimeter of 2D and 3D figures like cubes, cones, and cylinders', 'MEDIUM', 57, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE id = 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b229');
INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b329', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b229',
    'Mensuration Concepts',
    '<h3>1. CONCEPTUAL FOUNDATION</h3><p><strong>Mensuration</strong> is the branch of mathematics that deals with the <strong>measurement of geometric figures</strong> and their parameters like <strong>length, area, volume, and perimeter</strong>.</p><p>It forms the backbone of geometry-based quantitative problems and has wide applications in engineering, architecture, construction, and design.</p><p>Mensuration is divided into two parts:</p><ul><li><strong>2D Mensuration (Plane Figures):</strong> Involves measurement of length, perimeter, and area.</li><li>Examples: square, rectangle, triangle, circle, parallelogram, trapezium, rhombus.</li><li><strong>3D Mensuration (Solid Figures):</strong> Involves measurement of surface area, curved area, and volume.</li><li>Examples: cube, cuboid, cylinder, cone, sphere, hemisphere.</li></ul><p><strong>Prerequisites:</strong></p><ul><li>Knowledge of basic geometric shapes.</li><li>Understanding of units of measurement (cm, m, km, etc.).</li><li>Conversion between different units (1 m = 100 cm, 1 cm² = $10^{-4}$ m², etc.).</li></ul><p><br></p><h3>2. CORE THEORY &amp; PRINCIPLES</h3><ol><li><strong>Dimensional Understanding:</strong></li></ol><ul><li><strong>1D</strong> → Length<strong>2D</strong> → Area<strong>3D</strong> → Volume / Surface Area</li></ul><ol><li><strong>Measurement Units:</strong></li></ol><ul><li>Length → cm, m, kmArea → cm², m²Volume → cm³, m³, liters</li></ul><ol><li><strong>General Relationships:</strong></li></ol><ul><li>If all linear dimensions are increased ‘k’ times:</li><li>Area increases by $k^2$ times.Volume increases by $k^3$ times.</li></ul><ol><li><strong>Pi ($\pi$) Approximation:</strong></li></ol><ul><li>$\pi = \frac{22}{7}$ or $\pi = 3.1416$</li></ul><ol><li><strong>Real-Life Relevance:</strong></li></ol><ul><li>Land area (2D)Tank capacity, room space (3D)Construction and packaging (composite solids)</li></ul><p><br></p><h3>3. MAGIC SHORTCUTS</h3><ol><li><strong>Diagonal of Rectangle/Square:</strong></li><li>$d = \sqrt{l^2 + b^2}$</li><li><strong>Area of Equilateral Triangle:</strong></li><li>$A = \frac{\sqrt{3}}{4} a^2$</li><li><strong>Length of Arc of Circle:</strong></li><li>$L = \frac{\theta}{360} \times 2\pi r$</li><li><strong>Area of Sector:</strong></li><li>$A = \frac{\theta}{360} \times \pi r^2$</li><li><strong>Total Surface Area (TSA) and Volume Relation (Solids):</strong></li><li>Memorize shortcut ratios:</li></ol><ul><li>Cube → TSA : Volume = $6 : 1$ (for unit side)Sphere → TSA : Volume = $3 : 4r$</li></ul><p><br></p><h3>4. ESSENTIAL FORMULAE &amp; METHODS</h3><h3><strong>2D Figures</strong></h3><table table_id="marxgutazg" id="marxgutazg" class=""><tr row_id="u6aeusjxz3" style="width: 100%;"><td table_id="marxgutazg" row_id="u6aeusjxz3" cell_id="msnb4kn3xo" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Shape</strong></p></td><td table_id="marxgutazg" row_id="u6aeusjxz3" cell_id="jsjjd81uex" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Perimeter (P)</strong></p></td><td table_id="marxgutazg" row_id="u6aeusjxz3" cell_id="x9xj02csdri" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Area (A)</strong></p></td></tr><tr row_id="gljf9a3c8of" style="width: 100%;"><td table_id="marxgutazg" row_id="gljf9a3c8of" cell_id="l3dg0cmfhtf" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Square</span></p></td><td table_id="marxgutazg" row_id="gljf9a3c8of" cell_id="zaxp6l1dc2d" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$4a$</span></p></td><td table_id="marxgutazg" row_id="gljf9a3c8of" cell_id="fntc58p43hs" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$a^2$</span></p></td></tr><tr row_id="reggllu6e7j" style="width: 100%;"><td table_id="marxgutazg" row_id="reggllu6e7j" cell_id="t3rvu8144as" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Rectangle</span></p></td><td table_id="marxgutazg" row_id="reggllu6e7j" cell_id="ug5cu5zuhi" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$2(l + b)$</span></p></td><td table_id="marxgutazg" row_id="reggllu6e7j" cell_id="kobf3dmqnla" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$l \times b$</span></p></td></tr><tr row_id="il2xkskzi1" style="width: 100%;"><td table_id="marxgutazg" row_id="il2xkskzi1" cell_id="py8vcnun8" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Triangle</span></p></td><td table_id="marxgutazg" row_id="il2xkskzi1" cell_id="h0rp5ydow7s" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$a + b + c$</span></p></td><td table_id="marxgutazg" row_id="il2xkskzi1" cell_id="gbyvps1w344" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\sqrt{s(s-a)(s-b)(s-c)}$ (Heron’s Formula), where $s = \frac{a+b+c}{2}$</span></p></td></tr><tr row_id="shhc4qjudoi" style="width: 100%;"><td table_id="marxgutazg" row_id="shhc4qjudoi" cell_id="xen8t11zmkk" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Parallelogram</span></p></td><td table_id="marxgutazg" row_id="shhc4qjudoi" cell_id="fgw1a1f35tb" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$2(a+b)$</span></p></td><td table_id="marxgutazg" row_id="shhc4qjudoi" cell_id="26ifo7wx8p8" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$b \times h$</span></p></td></tr><tr row_id="qvrue92ld5" style="width: 100%;"><td table_id="marxgutazg" row_id="qvrue92ld5" cell_id="btph1pohhh5" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Rhombus</span></p></td><td table_id="marxgutazg" row_id="qvrue92ld5" cell_id="6c5w9nqb71w" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$4a$</span></p></td><td table_id="marxgutazg" row_id="qvrue92ld5" cell_id="7g6toiw286g" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\frac{1}{2} d_1 d_2$</span></p></td></tr><tr row_id="ngssm8275yl" style="width: 100%;"><td table_id="marxgutazg" row_id="ngssm8275yl" cell_id="eu8z4gp2ai" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Trapezium</span></p></td><td table_id="marxgutazg" row_id="ngssm8275yl" cell_id="qp2q4d0qwse" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Sum of all sides</span></p></td><td table_id="marxgutazg" row_id="ngssm8275yl" cell_id="t1x29pdgio" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\frac{1}{2}(a + b)h$</span></p></td></tr><tr row_id="b1gz1kjwztu" style="width: 100%;"><td table_id="marxgutazg" row_id="b1gz1kjwztu" cell_id="hf2oeq8zdv8" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Circle</span></p></td><td table_id="marxgutazg" row_id="b1gz1kjwztu" cell_id="1sp2evsub0v" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$2\pi r$</span></p></td><td table_id="marxgutazg" row_id="b1gz1kjwztu" cell_id="pm502fnuylf" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\pi r^2$</span></p></td></tr><tr row_id="3h937mopw36" style="width: 100%;"><td table_id="marxgutazg" row_id="3h937mopw36" cell_id="vwmq1oe1mu" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Sector (Angle $\theta$)</span></p></td><td table_id="marxgutazg" row_id="3h937mopw36" cell_id="fum8lhashui" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">—</span></p></td><td table_id="marxgutazg" row_id="3h937mopw36" cell_id="st5vq3ltw" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\frac{\theta}{360} \times \pi r^2$</span></p></td></tr></table><p><br></p><h3><strong>3D Figures</strong></h3><table table_id="1t1pkbs0xl9h" id="1t1pkbs0xl9h"><tr row_id="nwtbhsp8od" style="width: 100%;"><td table_id="1t1pkbs0xl9h" row_id="nwtbhsp8od" cell_id="c3d0yy4u2" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Solid</strong></p></td><td table_id="1t1pkbs0xl9h" row_id="nwtbhsp8od" cell_id="vlzfda3oex" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Total Surface Area (TSA)</strong></p></td><td table_id="1t1pkbs0xl9h" row_id="nwtbhsp8od" cell_id="bhdp10wembn" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Curved Surface Area (CSA)</strong></p></td><td table_id="1t1pkbs0xl9h" row_id="nwtbhsp8od" cell_id="dnupbg5whlp" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Volume (V)</strong></p></td></tr><tr row_id="ardo52jmr6o" style="width: 100%;"><td table_id="1t1pkbs0xl9h" row_id="ardo52jmr6o" cell_id="oz77wq3z6" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Cube</span></p></td><td table_id="1t1pkbs0xl9h" row_id="ardo52jmr6o" cell_id="o5vbkxov0g" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$6a^2$</span></p></td><td table_id="1t1pkbs0xl9h" row_id="ardo52jmr6o" cell_id="uqglp2frs8s" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">—</span></p></td><td table_id="1t1pkbs0xl9h" row_id="ardo52jmr6o" cell_id="vwjqzbth3r" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$a^3$</span></p></td></tr><tr row_id="hr4boav5m7t" style="width: 100%;"><td table_id="1t1pkbs0xl9h" row_id="hr4boav5m7t" cell_id="uhoprtnnfgf" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Cuboid</span></p></td><td table_id="1t1pkbs0xl9h" row_id="hr4boav5m7t" cell_id="guspqium19f" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$2(lb + bh + hl)$</span></p></td><td table_id="1t1pkbs0xl9h" row_id="hr4boav5m7t" cell_id="mgsvhj9aw0l" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$2h(l + b)$</span></p></td><td table_id="1t1pkbs0xl9h" row_id="hr4boav5m7t" cell_id="psttywukh6" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$lbh$</span></p></td></tr><tr row_id="ztaws0i06o" style="width: 100%;"><td table_id="1t1pkbs0xl9h" row_id="ztaws0i06o" cell_id="x4sduxzv43p" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Cylinder</span></p></td><td table_id="1t1pkbs0xl9h" row_id="ztaws0i06o" cell_id="c7ekccvi3xt" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$2\pi r(r + h)$</span></p></td><td table_id="1t1pkbs0xl9h" row_id="ztaws0i06o" cell_id="rh8r3pyo0bd" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$2\pi r h$</span></p></td><td table_id="1t1pkbs0xl9h" row_id="ztaws0i06o" cell_id="zizttq4ca2l" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\pi r^2 h$</span></p></td></tr><tr row_id="ln162ahtmws" style="width: 100%;"><td table_id="1t1pkbs0xl9h" row_id="ln162ahtmws" cell_id="dvsjyuph7wj" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Cone</span></p></td><td table_id="1t1pkbs0xl9h" row_id="ln162ahtmws" cell_id="edcwcyybaha" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\pi r (l + r)$</span></p></td><td table_id="1t1pkbs0xl9h" row_id="ln162ahtmws" cell_id="cboiltjm9n" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\pi r l$</span></p></td><td table_id="1t1pkbs0xl9h" row_id="ln162ahtmws" cell_id="of8946vp35d" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\frac{1}{3} \pi r^2 h$</span></p></td></tr><tr row_id="5ny9hib2f4i" style="width: 100%;"><td table_id="1t1pkbs0xl9h" row_id="5ny9hib2f4i" cell_id="3ed3dw0l3v2" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Sphere</span></p></td><td table_id="1t1pkbs0xl9h" row_id="5ny9hib2f4i" cell_id="m5xsi75v7l" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$4\pi r^2$</span></p></td><td table_id="1t1pkbs0xl9h" row_id="5ny9hib2f4i" cell_id="gqnnb65xb4" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">—</span></p></td><td table_id="1t1pkbs0xl9h" row_id="5ny9hib2f4i" cell_id="3o024zgh98l" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\frac{4}{3} \pi r^3$</span></p></td></tr><tr row_id="xsp10135tz" style="width: 100%;"><td table_id="1t1pkbs0xl9h" row_id="xsp10135tz" cell_id="unbleba40a" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Hemisphere</span></p></td><td table_id="1t1pkbs0xl9h" row_id="xsp10135tz" cell_id="859c2tcazh" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$3\pi r^2$</span></p></td><td table_id="1t1pkbs0xl9h" row_id="xsp10135tz" cell_id="3ll8f4ernpc" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$2\pi r^2$</span></p></td><td table_id="1t1pkbs0xl9h" row_id="xsp10135tz" cell_id="evfo49mit3f" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\frac{2}{3} \pi r^3$</span></p></td></tr></table><h3><br></h3><h3>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</h3><p><strong>Model 1:</strong> Finding perimeter and area of 2D shapes (basic problems).</p><p><strong>Model 2:</strong> Finding surface area, curved area, and volume of solids.</p><p><strong>Model 3:</strong> Comparing two shapes having equal area or volume.</p><p><strong>Model 4:</strong> Finding increase/decrease in area or volume when dimensions change.</p><p><strong>Model 5:</strong> Composite figures (combining solids — e.g., cylinder + cone).</p><p><strong>Model 6:</strong> Conversion problems (e.g., metal melted and recast into new shape).</p><p><br></p><h3>6. STEP-BY-STEP SOLUTION METHODS</h3><p><strong>Example 1 (2D):</strong></p><p>Find the area of a circle with radius 7 cm.</p><p><strong>Step 1:</strong> Formula → $A = \pi r^2$</p><p><strong>Step 2:</strong> Substitute → $A = \frac{22}{7} \times 7 \times 7 = 154$ cm²</p><p><strong>Answer:</strong> Area = <strong>154 cm²</strong></p><p><strong>Example 2 (3D):</strong></p><p>Find the volume of a cylinder with radius 3 cm and height 7 cm.</p><p><strong>Step 1:</strong> Formula → $V = \pi r^2 h$</p><p><strong>Step 2:</strong> Substitute → $V = \frac{22}{7} \times 3 \times 3 \times 7 = 198$ cm³</p><p><strong>Answer:</strong> Volume = <strong>198 cm³</strong></p><p><strong>Example 3 (Composite):</strong></p><p>A cone is placed on a cylinder having the same radius 3 cm and height 7 cm (cylinder) and 4 cm (cone).</p><p>Find total volume.</p><p><strong>Step 1:</strong> $V = \pi r^2 h_1 + \frac{1}{3}\pi r^2 h_2$</p><p><strong>Step 2:</strong> $V = \pi (3^2)(7 + \frac{4}{3}) = \pi (9)(\frac{25}{3}) = 75\pi$ cm³</p><p><strong>Step 3:</strong> $V = 75 \times 3.1416 = 235.62$ cm³</p><p><strong>Answer:</strong> Volume = <strong>235.62 cm³</strong></p><p><strong>Example 4 (Change in Dimension):</strong></p><p>If the radius of a sphere is increased by 10%, find the percentage increase in volume.</p><p><strong>Step 1:</strong> Volume ∝ $r^3$</p><p><strong>Step 2:</strong> Increase % = $(1.1)^3 - 1 = 0.331 = 33.1%$</p><p><strong>Answer:</strong> Volume increases by <strong>33.1%</strong></p><p><br></p><h3>7. CONCLUSION</h3><ul><li><strong>Mensuration</strong> connects geometry with practical life measurements.</li><li>Remember: Linear → 1st power, Area → 2nd power, Volume → 3rd power.</li><li>Always use consistent units throughout the problem.</li><li>For mixed or composite solids, calculate parts separately, then combine.</li><li>A solid grasp of formulas and visualization skills ensures 100% accuracy and speed.</li></ul><p><br></p><p>Practice Question:</p><p>A circular garden has radius 7 m. Find its (i) area and (ii) circumference. Take π = 22/7.</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b329');

-- 30. Clocks -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b230
INSERT INTO topics (id, subject_id, unit_id, name, description, difficulty, display_order, is_active, created_at, updated_at)
SELECT 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b230', '55555555-5555-5555-5555-555555555501',
    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Clocks',
    'Solves problems on angles, gains, and losses of time between clock hands', 'MEDIUM', 58, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
