INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b330', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b230',
    'Clocks Concepts',
    '<h2><strong>1. CONCEPTUAL FOUNDATION</strong></h2><p>The <strong>Clock</strong> topic deals with problems based on the positions and movements of the <strong>hour hand</strong> and <strong>minute hand</strong> of a clock.</p><p>It helps determine:</p><ul><li>The angle between the two hands at a given time.</li><li>When both hands will coincide, form a right angle, or be opposite.</li><li>Gain or loss of time when a clock runs fast or slow.</li></ul><h3><strong>Real-World Context</strong></h3><p>Clock reasoning is used in:</p><ul><li>Time calculation problems.</li><li>Scheduling and synchronization (e.g., trains, machines).</li><li>Logical reasoning tests in aptitude exams.</li></ul><h3><strong>Mathematical Nature</strong></h3><p>The hands of a clock move in <strong>circular motion</strong>, and their relative speed determines angular relationships.</p><p>Understanding this requires basic knowledge of:</p><ul><li><strong>Degrees in a circle (360°)</strong></li><li><strong>Ratios of speeds</strong> of hour and minute hands.</li><li><strong>Relative speed concept</strong> from time–speed–distance problems.</li></ul><h2><strong>2. CORE THEORY &amp; PRINCIPLES</strong></h2><h3><strong>2.1 Key Facts</strong></h3><ol><li>A clock is a <strong>circle of 360°</strong> divided into <strong>12 equal parts</strong>, each part = <strong>30°</strong>.</li><li>The <strong>minute hand</strong> moves <strong>360° in 60 minutes → 6° per minute</strong>.</li><li>The <strong>hour hand</strong> moves <strong>360° in 12 hours → 0.5° per minute</strong>.</li></ol><h3><strong>2.2 Relative Motion Concept</strong></h3><p>The <strong>relative speed</strong> of the minute hand with respect to the hour hand is:</p><p>$\text{Relative Speed} = 6 - 0.5 = 5.5°\text{ per minute}$</p><p>This concept helps find:</p><ul><li>The time taken for the hands to coincide.</li><li>The number of coincidences in a 12-hour period.</li></ul><h3><strong>2.3 Types of Positions</strong></h3><ol><li><strong>Coinciding Hands:</strong> Both hands overlap.</li><li><strong>Right Angle (90°):</strong> The hands are 90° apart.</li><li><strong>Straight Line (180°):</strong> The hands are opposite each other.</li><li><strong>Reflex Angle:</strong> The larger angle between the hands.</li></ol><h2><strong>3. MAGIC SHORTCUTS</strong></h2><ol><li><strong>Angle between Hands Formula:</strong></li><li>$\text{Angle} = |30H - 5.5M|$</li><li>where $H$ = hour, $M$ = minutes.</li><li><strong>Coinciding Time Shortcut:</strong></li><li>Time between two coincidences = $\frac{720}{11}$ minutes = <strong>65 5/11 minutes</strong>.</li><li><strong>Right Angle Shortcut:</strong></li><li>Between two coincidences, hands form right angles twice.</li><li><strong>Opposite (Straight Line) Shortcut:</strong></li><li>Between two coincidences, hands are opposite once.</li><li><strong>Clock Gain/Loss Shortcut:</strong></li><li>If a clock gains/loses $x$ minutes in $y$ hours,</li><li>then in 24 hours it will gain/lose $\frac{24x}{y}$ minutes.</li></ol><h2><strong>4. ESSENTIAL FORMULAE &amp; METHODS</strong></h2><table table_id="gy44kw9ruj5" id="gy44kw9ruj5" class=""><tr row_id="pl72mbqlz8o" style="width: 100%;"><td table_id="gy44kw9ruj5" row_id="pl72mbqlz8o" cell_id="hbwppg2xw57" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Concept</strong></p></td><td table_id="gy44kw9ruj5" row_id="pl72mbqlz8o" cell_id="g9fs4zmksj5" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Formula</strong></p></td></tr><tr row_id="r3974554mf" style="width: 100%;"><td table_id="gy44kw9ruj5" row_id="r3974554mf" cell_id="26b57q36zn7" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Angle between hour and minute hands</span></p></td><td table_id="gy44kw9ruj5" row_id="r3974554mf" cell_id="yr34zsfip0f" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\theta =</span></p></td></tr><tr row_id="rx9av3fuqem" style="width: 100%;"><td table_id="gy44kw9ruj5" row_id="rx9av3fuqem" cell_id="0qgdpll6o8v" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Coinciding time difference</span></p></td><td table_id="gy44kw9ruj5" row_id="rx9av3fuqem" cell_id="k0j9accsiv" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\frac{720}{11}$ minutes</span></p></td></tr><tr row_id="bmhda02mh5i" style="width: 100%;"><td table_id="gy44kw9ruj5" row_id="bmhda02mh5i" cell_id="zv2mtr1ojf" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Right angle condition</span></p></td><td table_id="gy44kw9ruj5" row_id="bmhda02mh5i" cell_id="jp73voz47un" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$</span></p></td></tr><tr row_id="h5fyqr5lft7" style="width: 100%;"><td table_id="gy44kw9ruj5" row_id="h5fyqr5lft7" cell_id="axga3615ssg" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Straight line (opposite) condition</span></p></td><td table_id="gy44kw9ruj5" row_id="h5fyqr5lft7" cell_id="d2qgxffwmve" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$</span></p></td></tr><tr row_id="qtz1xf4v84h" style="width: 100%;"><td table_id="gy44kw9ruj5" row_id="qtz1xf4v84h" cell_id="l473hq7s9rp" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Clock gaining/losing time</span></p></td><td table_id="gy44kw9ruj5" row_id="qtz1xf4v84h" cell_id="ob6ekq45ab" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Gain or loss = $\frac{\text{Time error}}{\text{Total time}} \times 100%$</span></p></td></tr></table><p><br></p><p><br></p><h2><strong>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</strong></h2><h3><strong>Type 1: Angle Between Hands</strong></h3><p>Find the angle between the hour and minute hands at a given time.</p><p><br></p><p><br></p><p><br></p><h3><strong>Type 2: Coincidence Problems</strong></h3><p>Find when both hands coincide or overlap.</p><p><br></p><p><br></p><p><br></p><h3><strong>Type 3: Right Angle Problems</strong></h3><p>Find when the hands form 90° angles.</p><p><br></p><p><br></p><p><br></p><h3><strong>Type 4: Opposite or Straight Line</strong></h3><p>Find when hands are 180° apart.</p><p><br></p><p><br></p><p><br></p><h3><strong>Type 5: Time Gain/Loss</strong></h3><p>Find how much a faulty clock gains or loses over a period.</p><p><br></p><p><br></p><p><br></p><h3><strong>Type 6: Hands in Between</strong></h3><p>Find the time when hands are in a specific angular relation other than 90° or 180°.</p><p><br></p><p><br></p><p><br></p><h2><strong>6. STEP-BY-STEP SOLUTION METHODS</strong></h2><h3><strong>Example 1: Angle Between Hands</strong></h3><p><strong>Question:</strong> Find the angle between hands at 4:20.</p><p><strong>Solution:</strong></p><p>$\theta = |30H - 5.5M| = |30(4) - 5.5(20)| = |120 - 110| = 10°$</p><p><strong>Answer:</strong> $10°$</p><p><br></p><p><br></p><h3><strong>Example 2: Coinciding Hands</strong></h3><p><strong>Question:</strong> When will the hands coincide after 12 o’clock?</p><p><strong>Solution:</strong></p><p>Time taken = $\frac{720}{11}$ minutes = $65 \frac{5}{11}$ minutes = <strong>65.45 minutes (approx 1:05:27)</strong>.</p><p><strong>Answer:</strong> At 1 hour 5 minutes and 27 seconds.</p><p><br></p><p><br></p><h3><strong>Example 3: Right Angle</strong></h3><p><strong>Question:</strong> At what time between 2 and 3 o’clock will the hands be at right angles?</p><p><strong>Solution:</strong></p><p>Use $|30H - 5.5M| = 90$</p><p>$\Rightarrow |60 - 5.5M| = 90$</p><p>Case 1: $60 - 5.5M = 90 \Rightarrow M = -5.45$ (Not valid)</p><p>Case 2: $5.5M - 60 = 90 \Rightarrow M = 27.27$</p><p><strong>Answer:</strong> At 2:27:16 approximately.</p><p><br></p><p><br></p><h3><strong>Example 4: Straight Line</strong></h3><p><strong>Question:</strong> When are hands opposite each other between 6 and 7?</p><p><strong>Solution:</strong></p><p>$|30H - 5.5M| = 180$</p><p>$\Rightarrow |180 - 5.5M| = 180$</p><p>$\Rightarrow 5.5M = 0$ or $360$ → $M = 65.45$ (after 65.45 minutes)</p><p><strong>Answer:</strong> 7:05:27.</p><p><br></p><p><br></p><h3><strong>Example 5: Clock Gain/Loss</strong></h3><p><strong>Question:</strong> A clock gains 3 minutes in 24 hours. How much will it gain in 8 days?</p><p><strong>Solution:</strong></p><p>$3 \times 8 = 24$ minutes.</p><p><strong>Answer:</strong> Gains <strong>24 minutes</strong> in 8 days.</p><p><br></p><p><br></p><h2><strong>7. CONCLUSION</strong></h2><p>The <strong>Clocks</strong> topic combines geometry and relative speed concepts to determine angular and time relations between clock hands.</p><p>It is formula-driven but highly logical once understood through visualization.</p><p><br></p><p><br></p><p><br></p><h3><strong>Key Insights</strong></h3><ul><li>Both hands coincide every 65 5/11 minutes.</li><li>Each hour, the angle changes at a constant rate of 5.5° per minute.</li><li>Visualization of hands helps eliminate confusion in right-angle or opposite problems.</li></ul><h3><strong>Mastery Indicators</strong></h3><ul><li>Can compute angles quickly using $\theta = |30H - 5.5M|$.</li><li>Can predict next coincidence times instantly.</li><li>Understands difference between clock time and relative motion.</li><li>Solves gain/loss problems confidently.</li></ul><p>Practice Question:</p><p>Find the angle between the hour and minute hands at 4:20.</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b330');

-- 31. Installments -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b231
INSERT INTO topics (id, subject_id, unit_id, name, description, difficulty, display_order, is_active, created_at, updated_at)
SELECT 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b231', '55555555-5555-5555-5555-555555555501',
    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Installments',
    'Deals with equal payments made periodically to repay a loan including interest', 'MEDIUM', 59, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE id = 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b231');
INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b331', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b231',
    'Installments Concepts',
    '<h3>1. CONCEPTUAL FOUNDATION</h3><p>The <strong>Installment System</strong> is a common method of payment in which a buyer pays the total cost of an article over a period of time through <strong>equal periodic payments</strong> (installments).</p><p>Each installment may include:</p><ul><li>A portion of the <strong>principal amount (actual cost)</strong>, and</li><li>The <strong>interest</strong> charged on the unpaid balance.</li></ul><p>Installment problems are frequently asked in <strong>Banking, SSC, Railway, Insurance, and Placement Exams</strong>, testing one’s understanding of compound interest, time value of money, and arithmetic progression.</p><p><br></p><h3>2. CORE THEORY &amp; PRINCIPLES</h3><ol><li><strong>Definition:</strong></li><li>An installment is one of the equal payments made at regular intervals toward the total debt, including interest.</li><li><strong>Key Idea:</strong></li><li>Each installment covers interest on the <strong>outstanding amount</strong> and repayment of part of the <strong>principal</strong>.</li><li><strong>Interest Basis:</strong></li><li>Installments are usually based on <strong>Compound Interest (C.I.)</strong>, not Simple Interest (S.I.), because the outstanding balance reduces with each payment.</li><li><strong>Essential Terms:</strong></li></ol><ul><li><strong>Cash Price (P):</strong> The price of an article if paid at once.<strong>Installment Value (I):</strong> The periodic payment amount.<strong>Rate (R):</strong> Annual rate of interest.<strong>Time (T):</strong> Period between two consecutive payments.<strong>Amount (A):</strong> Total of all installments paid.</li></ul><p><br></p><h3>3. MAGIC SHORTCUTS</h3><ol><li>When <strong>all installments are equal</strong>, and interest is compounded annually,</li><li>$\text{P} = \text{I} \times \frac{(1 + \frac{R}{100})^n - 1}{(\frac{R}{100})(1 + \frac{R}{100})^n}$</li><li>When <strong>rate and number of installments</strong> are known, but <strong>installment amount</strong> is missing, use:</li><li>$\text{I} = \text{P} \times \frac{(\frac{R}{100})(1 + \frac{R}{100})^n}{(1 + \frac{R}{100})^n - 1}$</li><li>If <strong>no interest is charged</strong>,</li><li>$\text{Installment} = \frac{\text{Total Amount}}{\text{Number of Installments}}$</li></ol><h2><br></h2><h3>4. ESSENTIAL FORMULAE &amp; METHODS</h3><table table_id="5lslui6a3sk" id="5lslui6a3sk" class=""><tr row_id="nkvjtrugxyc" style="width: 100%;"><td table_id="5lslui6a3sk" row_id="nkvjtrugxyc" cell_id="o22c0qc22p" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Concept</strong></p></td><td table_id="5lslui6a3sk" row_id="nkvjtrugxyc" cell_id="7amt3uirjho" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Formula</strong></p></td><td table_id="5lslui6a3sk" row_id="nkvjtrugxyc" cell_id="y4tnaewd0pn" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="background-color: transparent; color: rgb(0, 0, 0);">Description</strong></p></td></tr><tr row_id="2yge6ahon5g" style="width: 100%;"><td table_id="5lslui6a3sk" row_id="2yge6ahon5g" cell_id="815z20klsyd" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Present Worth (Cash Price)</span></p></td><td table_id="5lslui6a3sk" row_id="2yge6ahon5g" cell_id="i1uk1bz6vg" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\text{P} = \text{I} \times \frac{(1 + \frac{R}{100})^n - 1}{(\frac{R}{100})(1 + \frac{R}{100})^n}$</span></p></td><td table_id="5lslui6a3sk" row_id="2yge6ahon5g" cell_id="yilbsinakxg" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Used when all installments are equal</span></p></td></tr><tr row_id="weo3o338ry" style="width: 100%;"><td table_id="5lslui6a3sk" row_id="weo3o338ry" cell_id="neqi6yh6q5a" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Installment Value</span></p></td><td table_id="5lslui6a3sk" row_id="weo3o338ry" cell_id="3gu7r0kohkk" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\text{I} = \text{P} \times \frac{(\frac{R}{100})(1 + \frac{R}{100})^n}{(1 + \frac{R}{100})^n - 1}$</span></p></td><td table_id="5lslui6a3sk" row_id="weo3o338ry" cell_id="qidt1ujdedm" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Used to find each installment</span></p></td></tr><tr row_id="ki1h9a0j9ab" style="width: 100%;"><td table_id="5lslui6a3sk" row_id="ki1h9a0j9ab" cell_id="tvv0eue88m" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Total Amount Paid</span></p></td><td table_id="5lslui6a3sk" row_id="ki1h9a0j9ab" cell_id="m74nh8wo4l9" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\text{A} = \text{I} \times n$</span></p></td><td table_id="5lslui6a3sk" row_id="ki1h9a0j9ab" cell_id="865xh8rc3re" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Total payment made including interest</span></p></td></tr><tr row_id="6oaxyrw7v0d" style="width: 100%;"><td table_id="5lslui6a3sk" row_id="6oaxyrw7v0d" cell_id="jj9iwmr6zzg" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Interest Paid</span></p></td><td table_id="5lslui6a3sk" row_id="6oaxyrw7v0d" cell_id="peqoilepc4" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">$\text{Interest} = \text{A} - \text{P}$</span></p></td><td table_id="5lslui6a3sk" row_id="6oaxyrw7v0d" cell_id="gti44zxbywf" column="null" color="null" style="background-color: null" colspan="null"><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Difference between total payment and cash price</span></p></td></tr></table><p><br></p><h3>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</h3><ol><li><strong>Type 1:</strong> Finding the cash price given equal installments, rate, and number of years.</li><li><strong>Type 2:</strong> Finding the installment value when cash price, rate, and number of years are known.</li><li><strong>Type 3:</strong> Finding the total interest paid over the entire period.</li><li><strong>Type 4:</strong> Calculating outstanding balance after one or more installments are paid.</li><li><strong>Type 5:</strong> Installment-based comparison between two offers (e.g., bank vs dealer).</li></ol><h2><br></h2><h3>6. STEP-BY-STEP SOLUTION METHODS</h3><h4>Example 1</h4><p><strong>Question:</strong></p><p>A person buys a scooter for ₹40,000. He pays ₹10,000 in cash and the rest in 3 equal yearly installments at 10% compound interest. Find the annual installment amount.</p><p><strong>Solution:</strong></p><p>Given:</p><p>$\text{Cash Price Paid} = 10,000$</p><p>Remaining Amount = $40,000 - 10,000 = 30,000$</p><p>$R = 10%$, $n = 3$</p><p>$\text{I} = \text{P} \times \frac{(\frac{R}{100})(1 + \frac{R}{100})^n}{(1 + \frac{R}{100})^n - 1}$</p><p>$\text{I} = 30,000 \times \frac{(0.1)(1.1)^3}{(1.1)^3 - 1}$</p><p>$= 30,000 \times \frac{0.1 \times 1.331}{0.331}$</p><p>$= 30,000 \times 0.402$</p><p>$= 12,060$</p><p><strong>Each installment = ₹12,060</strong></p><p><br></p><h4>Example 2</h4><p><strong>Question:</strong></p><p>The cash price of a TV is ₹25,000. If it can be paid in 2 equal yearly installments of ₹13,000 each at 10% compound interest, find the total interest paid.</p><p><strong>Solution:</strong></p><p>Total payment = $13,000 \times 2 = 26,000$</p><p>Interest = Total Payment – Cash Price</p><p>Interest = $26,000 - 25,000 = 1,000$</p><p><strong>Total Interest = ₹1,000</strong></p><p><br></p><h4>Example 3</h4><p><strong>Question:</strong></p><p>A person agrees to pay ₹12,000 in 3 yearly installments with interest at 10% per annum. Find the cash price.</p><p><strong>Solution:</strong></p><p>$\text{P} = \text{I} \times \frac{(1 + \frac{R}{100})^n - 1}{(\frac{R}{100})(1 + \frac{R}{100})^n}$</p><p>$\text{P} = 12,000 \times \frac{(1.1)^3 - 1}{0.1 \times (1.1)^3}$</p><p>$= 12,000 \times \frac{0.331}{0.1331}$</p><p>$= 12,000 \times 2.487$</p><p>$= 29,844$</p><p><strong>Cash Price = ₹29,844</strong></p><p><br></p><h3>7. CONCLUSION</h3><ul><li>The <strong>Installment system</strong> involves equal periodic payments including both principal and interest.</li><li>The concept primarily uses <strong>Compound Interest formulas</strong> because the unpaid balance reduces after every payment.</li><li>Problems often require careful interpretation of <strong>time periods</strong>, <strong>rate of interest</strong>, and <strong>number of installments</strong>.</li><li>Mastering the relationships between <strong>cash price</strong>, <strong>installment</strong>, <strong>interest</strong>, and <strong>total amount</strong> ensures accuracy in real-life and exam scenarios.</li></ul><p><br></p><p><strong>Practice Question:</strong></p><p>A washing machine is sold for a cash price of ₹24,000 or for 3 equal yearly installments at 10% compound interest per annum. Find the value of each installment.</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b331');

-- 32. H.C.F. & L.C.M. of Numbers -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b232
