INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b332', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b232',
    'H.C.F. & L.C.M. of Numbers Concepts',
    '<h4><strong>1. CONCEPTUAL FOUNDATION</strong></h4><p><strong>H.C.F. (Highest Common Factor)</strong>:</p><ul><li>The greatest number that divides two or more numbers exactly.</li><li>Also called <strong>GCD (Greatest Common Divisor)</strong>.</li></ul><p><strong>L.C.M. (Least Common Multiple)</strong>:</p><ul><li>The smallest number that is exactly divisible by two or more numbers.</li></ul><p><strong>Purpose in Aptitude:</strong></p><p>Used in problems involving repetition, synchronization, cycles, ratio simplification, and time-based repetition problems.</p><p><strong>Real-life Examples:</strong></p><ul><li>HCF → dividing quantities into equal parts (e.g., cutting wires into equal lengths).</li><li>LCM → finding when events coincide again (e.g., bells ringing together, traffic lights, gear rotations).</li></ul><p><strong>Prerequisites:</strong></p><ul><li>Prime numbers</li><li>Factorization</li><li>Basic divisibility rules</li></ul><p><br></p><h4><strong>2. CORE THEORY &amp; PRINCIPLES</strong></h4><p><strong>HCF &amp; LCM Relationship</strong></p><ul><li>For any two numbers a and b,</li><li><strong>a × b = HCF × LCM</strong></li></ul><p><strong>HCF Concepts</strong></p><ul><li>Represents common measure or divisor.</li><li>The HCF of two numbers divides their difference exactly.</li><li>If HCF = 1, numbers are <strong>co-prime</strong>.</li></ul><p><strong>LCM Concepts</strong></p><ul><li>Represents common multiple.</li><li>Always ≥ largest of given numbers.</li><li>The LCM of fractions =</li><li>$\dfrac{\text{LCM of numerators}}{\text{HCF of denominators}}$</li></ul><p><strong>HCF of Fractions =</strong></p><ul><li>$\dfrac{\text{HCF of numerators}}{\text{LCM of denominators}}$</li></ul><p><strong>HCF &amp; LCM of Decimals:</strong></p><ul><li>Remove decimal by multiplying with powers of 10, find HCF/LCM, then divide result by same power.</li></ul><p><strong>Pairwise Principle (for 3 or more numbers):</strong></p><ul><li>For numbers a, b, c →</li><li>$HCF(a,b,c) = HCF[HCF(a,b), c]$</li><li>$LCM(a,b,c) = LCM[LCM(a,b), c]$</li></ul><p><br></p><h4><strong style="color: rgb(0, 0, 0); background-color: transparent;">3. MAGIC SHORTCUTS</strong></h4><table table_id="7x139t0smaf" id="7x139t0smaf" class=""><tr row_id="78ca0kufzy" style="width: 100%;"><td table_id="7x139t0smaf" row_id="78ca0kufzy" cell_id="bqw4w4hdugu" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Shortcut</strong></p></td><td table_id="7x139t0smaf" row_id="78ca0kufzy" cell_id="3kr84wjumkc" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Purpose</strong></p></td><td table_id="7x139t0smaf" row_id="78ca0kufzy" cell_id="pzg7ka63x3h" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Example</strong></p></td></tr><tr row_id="prnu09u4brp" style="width: 100%;"><td table_id="7x139t0smaf" row_id="prnu09u4brp" cell_id="l56nd5fsvkc" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="color: rgb(0, 0, 0); background-color: transparent;">Prime Factor Shortcut</strong></p></td><td table_id="7x139t0smaf" row_id="prnu09u4brp" cell_id="ehz7n8bmtjw" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Quick HCF/LCM finding for small numbers</span></p></td><td table_id="7x139t0smaf" row_id="prnu09u4brp" cell_id="s8oxz23eaco" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">24 = 2³×3¹, 36 = 2²×3² → HCF=2²×3¹=12; LCM=2³×3²=72</span></p></td></tr><tr row_id="5w108ctkpn7" style="width: 100%;"><td table_id="7x139t0smaf" row_id="5w108ctkpn7" cell_id="pj2zikjjxd" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="color: rgb(0, 0, 0); background-color: transparent;">Division Method (HCF)</strong></p></td><td table_id="7x139t0smaf" row_id="5w108ctkpn7" cell_id="nvt7ni17zo" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Divide larger by smaller till remainder 0</span></p></td><td table_id="7x139t0smaf" row_id="5w108ctkpn7" cell_id="bqdlv3fvqvw" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">HCF(84,18): 84÷18=4R12; 18÷12=1R6; 12÷6=2R0 → HCF=6</span></p></td></tr><tr row_id="2tvbhqivrht" style="width: 100%;"><td table_id="7x139t0smaf" row_id="2tvbhqivrht" cell_id="elwj5ja2nua" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="color: rgb(0, 0, 0); background-color: transparent;">HCF-LCM Cross Trick</strong></p></td><td table_id="7x139t0smaf" row_id="2tvbhqivrht" cell_id="zhrggcnjp6" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Product of two numbers / given HCF or LCM</span></p></td><td table_id="7x139t0smaf" row_id="2tvbhqivrht" cell_id="727wqdmesy" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">If HCF=6, LCM=72, one number=24 → other=(6×72)/24=18</span></p></td></tr><tr row_id="oyhzgmd678l" style="width: 100%;"><td table_id="7x139t0smaf" row_id="oyhzgmd678l" cell_id="ij2noist4k" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="color: rgb(0, 0, 0); background-color: transparent;">LCM of fractions</strong></p></td><td table_id="7x139t0smaf" row_id="oyhzgmd678l" cell_id="9uu7639hy5" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Use numerators’ LCM / denominators’ HCF</span></p></td><td table_id="7x139t0smaf" row_id="oyhzgmd678l" cell_id="58rywz8u18x" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">LCM(3/4, 5/6) = LCM(3,5)/HCF(4,6)=15/2=7.5</span></p></td></tr><tr row_id="c3jn39z6ls" style="width: 100%;"><td table_id="7x139t0smaf" row_id="c3jn39z6ls" cell_id="5jjr49wapqr" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="color: rgb(0, 0, 0); background-color: transparent;">Shortcut for identical differences</strong></p></td><td table_id="7x139t0smaf" row_id="c3jn39z6ls" cell_id="ya12ldlcgng" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">If numbers differ by same value → HCF = that difference</span></p></td><td table_id="7x139t0smaf" row_id="c3jn39z6ls" cell_id="i0c7rfsptyj" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Numbers: 1001, 1007, 1013 → diff=6 → HCF=6</span></p></td></tr><tr row_id="6qil5xw9rkb" style="width: 100%;"><td table_id="7x139t0smaf" row_id="6qil5xw9rkb" cell_id="dw9r7xwnobb" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="color: rgb(0, 0, 0); background-color: transparent;">Co-prime Rule</strong></p></td><td table_id="7x139t0smaf" row_id="6qil5xw9rkb" cell_id="w2vhg0v6czs" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">If numbers are co-prime → LCM = product</span></p></td><td table_id="7x139t0smaf" row_id="6qil5xw9rkb" cell_id="lgs47wsh28l" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">7, 9 → LCM=63</span></p></td></tr><tr row_id="a7hb74ko1ud" style="width: 100%;"><td table_id="7x139t0smaf" row_id="a7hb74ko1ud" cell_id="pcbc18wvf6o" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="color: rgb(0, 0, 0); background-color: transparent;">Perfect Square Pattern</strong></p></td><td table_id="7x139t0smaf" row_id="a7hb74ko1ud" cell_id="fzr8icwjiyc" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">HCF×LCM = product always square for equal numbers</span></p></td><td table_id="7x139t0smaf" row_id="a7hb74ko1ud" cell_id="0r507xv9uql" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">12,12 → HCF=LCM=12</span></p></td></tr></table><p><br></p><h4><strong>4. ESSENTIAL FORMULAE &amp; METHODS</strong></h4><ul><li>$a × b = HCF(a,b) × LCM(a,b)$</li><li>$HCF(a,b) = \text{Product of lowest powers of all common primes}$</li><li>$LCM(a,b) = \text{Product of highest powers of all primes present}$</li><li><strong>For Fractions: </strong></li><li class="ql-indent-1">HCF = (HCF of numerators) ÷ (LCM of denominators)LCM = (LCM of numerators) ÷ (HCF of denominators)</li><li><strong>For Decimals: </strong>Multiply each by suitable power of 10 to make all integers, find HCF/LCM, then divide by same power of 10.</li></ul><p><br></p><h4><strong style="color: rgb(0, 0, 0); background-color: transparent;">5. PROBLEM RECOGNITION &amp; CLASSIFICATION</strong></h4><table table_id="6y0iqxt8n9r" id="6y0iqxt8n9r"><tr row_id="aworg4fvif" style="width: 100%;"><td table_id="6y0iqxt8n9r" row_id="aworg4fvif" cell_id="8m8ycmjj2hq" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Type</strong></p></td><td table_id="6y0iqxt8n9r" row_id="aworg4fvif" cell_id="zqx1ihhpjb" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Category</strong></p></td><td table_id="6y0iqxt8n9r" row_id="aworg4fvif" cell_id="6f1fi5559to" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Model Description</strong></p></td><td table_id="6y0iqxt8n9r" row_id="aworg4fvif" cell_id="ak7oorpa7x9" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Example</strong></p></td></tr><tr row_id="j8adq1oiss8" style="width: 100%;"><td table_id="6y0iqxt8n9r" row_id="j8adq1oiss8" cell_id="q6yog94edr" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="color: rgb(0, 0, 0); background-color: transparent;">Type 1</strong></p></td><td table_id="6y0iqxt8n9r" row_id="j8adq1oiss8" cell_id="vuj02pgl3zi" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Prime Factorization</span></p></td><td table_id="6y0iqxt8n9r" row_id="j8adq1oiss8" cell_id="1h6wm76ef81" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Direct computation using prime powers</span></p></td><td table_id="6y0iqxt8n9r" row_id="j8adq1oiss8" cell_id="ra447sldf0j" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Find HCF &amp; LCM of 24, 36</span></p></td></tr><tr row_id="dt7fb9c5mvl" style="width: 100%;"><td table_id="6y0iqxt8n9r" row_id="dt7fb9c5mvl" cell_id="2pkb5ep3h51" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="color: rgb(0, 0, 0); background-color: transparent;">Type 2</strong></p></td><td table_id="6y0iqxt8n9r" row_id="dt7fb9c5mvl" cell_id="viufck9pxe" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Division (Euclid’s Algorithm)</span></p></td><td table_id="6y0iqxt8n9r" row_id="dt7fb9c5mvl" cell_id="d8w2mc2g15q" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Stepwise remainder reduction</span></p></td><td table_id="6y0iqxt8n9r" row_id="dt7fb9c5mvl" cell_id="1qefr3ghemz" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Find HCF of 84 and 18</span></p></td></tr><tr row_id="xeoqya9tez" style="width: 100%;"><td table_id="6y0iqxt8n9r" row_id="xeoqya9tez" cell_id="j78bh2qz0lb" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="color: rgb(0, 0, 0); background-color: transparent;">Type 3</strong></p></td><td table_id="6y0iqxt8n9r" row_id="xeoqya9tez" cell_id="5juudz3f7wx" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Relationship Problems</span></p></td><td table_id="6y0iqxt8n9r" row_id="xeoqya9tez" cell_id="6jppg8oazi" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Using product formula</span></p></td><td table_id="6y0iqxt8n9r" row_id="xeoqya9tez" cell_id="uyosqm9q3bf" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Given one number and HCF/LCM</span></p></td></tr><tr row_id="g5u3sbpo7pe" style="width: 100%;"><td table_id="6y0iqxt8n9r" row_id="g5u3sbpo7pe" cell_id="hvncsxjb8s9" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="color: rgb(0, 0, 0); background-color: transparent;">Type 4</strong></p></td><td table_id="6y0iqxt8n9r" row_id="g5u3sbpo7pe" cell_id="aacbe5wcsaw" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Repetition/Event problems</span></p></td><td table_id="6y0iqxt8n9r" row_id="g5u3sbpo7pe" cell_id="y68tfrhuk" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Using LCM for simultaneous repetition</span></p></td><td table_id="6y0iqxt8n9r" row_id="g5u3sbpo7pe" cell_id="ux6jugjgumn" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Bells ringing together</span></p></td></tr><tr row_id="lezbwius8b9" style="width: 100%;"><td table_id="6y0iqxt8n9r" row_id="lezbwius8b9" cell_id="qh08mx06pp" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="color: rgb(0, 0, 0); background-color: transparent;">Type 5</strong></p></td><td table_id="6y0iqxt8n9r" row_id="lezbwius8b9" cell_id="a08e1gi9xq5" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Fractional HCF/LCM</span></p></td><td table_id="6y0iqxt8n9r" row_id="lezbwius8b9" cell_id="i46vf7s07ah" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Numerator/denominator operation</span></p></td><td table_id="6y0iqxt8n9r" row_id="lezbwius8b9" cell_id="evrs370qter" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">LCM(2/3, 3/5)</span></p></td></tr><tr row_id="udgakvl5ni" style="width: 100%;"><td table_id="6y0iqxt8n9r" row_id="udgakvl5ni" cell_id="zmpntw45gkr" column="null" color="null" style="background-color: null" colspan="null"><p><strong style="color: rgb(0, 0, 0); background-color: transparent;">Type 6</strong></p></td><td table_id="6y0iqxt8n9r" row_id="udgakvl5ni" cell_id="v77l804soyb" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Difference/Multiple method</span></p></td><td table_id="6y0iqxt8n9r" row_id="udgakvl5ni" cell_id="9qkcb60frwo" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Using equal differences</span></p></td><td table_id="6y0iqxt8n9r" row_id="udgakvl5ni" cell_id="26ksksaxg51" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Find largest number dividing remainders equally</span></p></td></tr></table><p><br></p><h4><strong style="background-color: transparent; color: rgb(0, 0, 0);">6. STEP-BY-STEP SOLUTION METHODS</strong></h4><h4><br></h4><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Example 1: Prime Factorization Method</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Find HCF &amp; LCM of 24, 36</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> → 24 = 2³ × 3¹</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> → 36 = 2² × 3²</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> </span><strong style="background-color: transparent; color: rgb(0, 0, 0);">HCF = 2²×3¹ = 12</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> </span><strong style="background-color: transparent; color: rgb(0, 0, 0);">LCM = 2³×3² = 72</strong></p><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Example 2: Euclid’s Division Algorithm</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Find HCF of 84, 18</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> → 84 ÷ 18 = 4 remainder 12</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> → 18 ÷ 12 = 1 remainder 6</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> → 12 ÷ 6 = 2 remainder 0</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> </span><strong style="background-color: transparent; color: rgb(0, 0, 0);">HCF = 6</strong></p><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Example 3: Product Relationship</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">If HCF of two numbers is 6 and their LCM is 72, find the second number if one is 24.</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Product = 6 × 72 = 432</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Other number = 432 ÷ 24 = 18</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> </span><strong style="background-color: transparent; color: rgb(0, 0, 0);">Answer = 18</strong></p><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Example 4: Fractions</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Find HCF and LCM of 3/4 and 5/6</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> → HCF = (HCF of 3,5) ÷ (LCM of 4,6) = 1 ÷ 12 = 1/12</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> → LCM = (LCM of 3,5) ÷ (HCF of 4,6) = 15 ÷ 2 = 7.5</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> </span><strong style="background-color: transparent; color: rgb(0, 0, 0);">HCF = 1/12, LCM = 7.5</strong></p><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Example 5: Event Repetition Problem</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Three bells ring at 4, 6, and 8 seconds interval. When will they ring together again?</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> → LCM(4,6,8) = 24</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> </span><strong style="background-color: transparent; color: rgb(0, 0, 0);">They ring together every 24 seconds.</strong></p><p><strong style="background-color: transparent; color: rgb(0, 0, 0);">Example 6: Largest Number Dividing Remainders Equally</strong></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);">Find largest number that divides 43, 91, and 183 leaving same remainder.</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Step 1: Find differences → 91−43=48; 183−91=92</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> Step 2: HCF(48,92)=4</span></p><p><span style="background-color: transparent; color: rgb(0, 0, 0);"> </span><strong style="background-color: transparent; color: rgb(0, 0, 0);">Answer = 4</strong></p><h4><br></h4><h4><strong>7. CONCLUSION</strong></h4><ul><li><strong>HCF</strong> identifies <strong>common measure</strong> → “What equally divides?”</li><li><strong>LCM</strong> identifies <strong>common multiple</strong> → “When do they meet again?”</li><li>Always use <strong>HCF × LCM = Product</strong> as cross-check.</li><li>Apply <strong>Prime Factorization</strong> for small integers, <strong>Euclidean division</strong> for larger ones, and <strong>LCM logic</strong> for cycle problems.</li><li>Mastering these helps speed-solve 3-topic families: <em>Time &amp; Work, Time &amp; Distance, Pipes &amp; Cisterns.</em></li></ul><p><br></p><h5><strong style="color: rgb(0, 0, 0); background-color: transparent;">Quick Recap for Revision</strong></h5><table table_id="7bwh21r2ox" id="7bwh21r2ox"><tr row_id="qxe56iqem1n" style="width: 100%;"><td table_id="7bwh21r2ox" row_id="qxe56iqem1n" cell_id="y7yo37hl48m" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Formula / Rule</strong></p></td><td table_id="7bwh21r2ox" row_id="qxe56iqem1n" cell_id="ctqxh05qu9v" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Memory Trick</strong></p></td></tr><tr row_id="8ywxby69enl" style="width: 100%;"><td table_id="7bwh21r2ox" row_id="8ywxby69enl" cell_id="jinb2da622h" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">HCF × LCM = Product</span></p></td><td table_id="7bwh21r2ox" row_id="8ywxby69enl" cell_id="b3io6n7ka2" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">“H-L Pair Always Square”</span></p></td></tr><tr row_id="uzghbcu73r" style="width: 100%;"><td table_id="7bwh21r2ox" row_id="uzghbcu73r" cell_id="29jhajsd118" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">HCF for Fractions</span></p></td><td table_id="7bwh21r2ox" row_id="uzghbcu73r" cell_id="oaj1ll4axor" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">“H up, L down” → HCF(num)/LCM(den)</span></p></td></tr><tr row_id="dquwbk6mtvd" style="width: 100%;"><td table_id="7bwh21r2ox" row_id="dquwbk6mtvd" cell_id="ou411ot0gf" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">LCM for Fractions</span></p></td><td table_id="7bwh21r2ox" row_id="dquwbk6mtvd" cell_id="wdcuof9vue" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">“L up, H down” → LCM(num)/HCF(den)</span></p></td></tr><tr row_id="7u56ak7sp0h" style="width: 100%;"><td table_id="7bwh21r2ox" row_id="7u56ak7sp0h" cell_id="jta1oyi1zk" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">HCF divides difference</span></p></td><td table_id="7bwh21r2ox" row_id="7u56ak7sp0h" cell_id="9k0s9dvs8jn" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">“Subtract to Simplify”</span></p></td></tr><tr row_id="x4qramoesg" style="width: 100%;"><td table_id="7bwh21r2ox" row_id="x4qramoesg" cell_id="saydmkhbo0t" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Co-primes → LCM = Product</span></p></td><td table_id="7bwh21r2ox" row_id="x4qramoesg" cell_id="npioj4gi66g" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">“No common, full product”</span></p></td></tr></table><p><br></p><p><br></p><h4><strong>Practice Question:</strong></h4><p>Find the greatest number that divides 184 and 230 leaving the same remainder.</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b332');

-- 33. Probability -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b233
INSERT INTO topics (id, subject_id, unit_id, name, description, difficulty, display_order, is_active, created_at, updated_at)
SELECT 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b233', '55555555-5555-5555-5555-555555555501',
    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Probability',
    'Measures likelihood of occurrence of events using theoretical and experimental approaches', 'MEDIUM', 61, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE id = 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b233');
INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b333', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b233',
    'Probability Concepts',
    '<h4><strong>1. CONCEPTUAL FOUNDATION</strong></h4><p><strong>Definition:</strong></p><p>Probability measures the likelihood or chance of an event occurring. It is expressed as a value between 0 and 1, where 0 means the event is impossible, and 1 means it is certain.</p><p><strong>Real-World Context:</strong></p><ul><li>Predicting weather (chance of rain)</li><li>Games of chance (dice, cards, coins)</li><li>Business decisions (risk analysis)</li><li>Quality control in manufacturing (defective vs. non-defective items)</li></ul><p><strong>Mathematical Significance:</strong></p><p>Probability forms the foundation of statistics, risk management, data analysis, and machine learning. It is based on the idea of sample spaces and outcomes.</p><p><strong>Prerequisites:</strong></p><ul><li>Understanding of sets and set operations</li><li>Concepts of fractions, ratios, and percentages</li><li>Basic counting principles (combinations and permutations)</li></ul><p><br></p><h4><strong>2. CORE THEORY &amp; PRINCIPLES</strong></h4><p><strong>1. Basic Terms:</strong></p><ul><li><strong>Experiment:</strong> An action whose outcome cannot be predicted with certainty (e.g., tossing a coin).</li><li><strong>Outcome:</strong> A possible result of an experiment.</li><li><strong>Sample Space ($S$):</strong> The set of all possible outcomes.</li><li>Example: For a die, $S = {1, 2, 3, 4, 5, 6}$.</li><li><strong>Event ($E$):</strong> A subset of the sample space (e.g., getting an even number).</li></ul><p><strong>2. Classical Definition of Probability:</strong></p><p>If all outcomes are equally likely, then</p><p>$P(E) = \frac{n(E)}{n(S)}$</p><p>where</p><p>$n(E)$ = number of favorable outcomes,</p><p>$n(S)$ = total number of outcomes.</p><p><strong>3. Range of Probability:</strong></p><p>$0 \leq P(E) \leq 1$</p><p><strong>4. Complementary Events:</strong></p><p>For any event $E$,</p><p>$P(E) + P(E'') = 1$</p><p><strong>5. Mutually Exclusive Events:</strong></p><p>Two events $A$ and $B$ are <strong>mutually exclusive</strong> if they cannot occur together.</p><p>$P(A \cap B) = 0$</p><p><strong>6. Exhaustive Events:</strong></p><p>Events that together cover all possible outcomes of the experiment.</p><p><strong>7. Addition Theorem:</strong></p><p>For any two events $A$ and $B$,</p><p>$P(A \cup B) = P(A) + P(B) - P(A \cap B)$</p><p>If $A$ and $B$ are mutually exclusive:</p><p>$P(A \cup B) = P(A) + P(B)$</p><p><strong>8. Multiplication Theorem:</strong></p><p>For independent events $A$ and $B$,</p><p>$P(A \cap B) = P(A) \times P(B)$</p><p>For dependent events,</p><p>$P(A \cap B) = P(A) \times P(B|A)$</p><p><strong>9. Conditional Probability:</strong></p><p>$P(A|B) = \frac{P(A \cap B)}{P(B)}$, provided $P(B) \neq 0$</p><p><strong>10. Total Probability Theorem:</strong></p><p>If $B_1, B_2, ..., B_n$ are mutually exclusive and exhaustive events, then</p><p>$P(A) = P(B_1)P(A|B_1) + P(B_2)P(A|B_2) + ... + P(B_n)P(A|B_n)$</p><p><strong>11. Bayes’ Theorem:</strong></p><p>$P(B_i|A) = \frac{P(B_i)P(A|B_i)}{\sum_{j=1}^{n} P(B_j)P(A|B_j)}$</p><p><br></p><h4><strong>3. MAGIC SHORTCUTS</strong></h4><ol><li><strong>Complement Rule:</strong></li><li>If finding $P(E)$ is tough, find $P(E'')$ and use $P(E) = 1 - P(E'')$.</li><li><strong>At Least One Rule:</strong></li><li>For independent events $A$ and $B$,</li><li>$P(\text{at least one}) = 1 - P(\text{none})$</li><li>Example: When tossing two coins,</li><li>$P(\text{at least one head}) = 1 - P(\text{no head}) = 1 - \frac{1}{4} = \frac{3}{4}$</li><li><strong>Shortcut for Cards:</strong></li></ol><ul><li>Total cards = 52Red cards = 26 (Hearts + Diamonds)Black cards = 26 (Spades + Clubs)Face cards = 12 (J, Q, K of each suit)</li></ul><ol><li><strong>Shortcut for Dice:</strong></li></ol><ul><li>Total outcomes (for one die) = 6For two dice = 36Probability of sum = n favorable outcomes / 36</li></ul><ol><li><strong>Independent Repetition:</strong></li><li>Probability of event happening at least once in $n$ trials =</li><li>$1 - (1 - p)^n$</li></ol><p><br></p><h4><strong>4. ESSENTIAL FORMULAE &amp; METHODS</strong></h4><ol><li>$P(E) = \frac{n(E)}{n(S)}$</li><li>$P(E'') = 1 - P(E)$</li><li>$P(A \cup B) = P(A) + P(B) - P(A \cap B)$</li><li>$P(A \cap B) = P(A) \times P(B|A)$</li><li>$P(A|B) = \frac{P(A \cap B)}{P(B)}$</li><li><strong>For Independent Events:</strong> $P(A \cap B) = P(A) \times P(B)$</li><li><strong>Total Probability Theorem:</strong></li><li>$P(A) = \sum P(B_i)P(A|B_i)$</li><li><strong>Bayes’ Theorem:</strong></li><li>$P(B_i|A) = \frac{P(B_i)P(A|B_i)}{\sum P(B_j)P(A|B_j)}$</li></ol><p><br></p><h4><strong>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</strong></h4><p><strong>1. Basic Probability Problems:</strong></p><p>Direct application of $P(E) = \frac{n(E)}{n(S)}$.</p><p>Example: Probability of getting an even number when a die is thrown.</p><p><strong>2. Complementary Probability:</strong></p><p>Questions involving “at least”, “none”, or “not happening” conditions.</p><p><strong>3. Compound Events:</strong></p><ul><li>Mutually exclusive events → Use Addition Theorem</li><li>Independent/Dependent events → Use Multiplication Theorem</li></ul><p><strong>4. Conditional Probability Problems:</strong></p><p>Involving events dependent on previous outcomes.</p><p><strong>5. Bayes’ Theorem Problems:</strong></p><p>Reversing conditional probability when prior probabilities are known.</p><p><strong>6. Probability with Combinatorics:</strong></p><p>Situations involving selection, arrangement, or drawing (e.g., cards, balls).</p><p><br></p><h4><strong>6. CONCLUSION</strong></h4><ul><li>Probability quantifies uncertainty and risk.</li><li>It serves as a foundation for advanced topics like statistics, data analysis, and inferential reasoning.</li><li>Mastering classical probability builds conceptual clarity required for modern applications such as predictive modeling and machine learning.</li><li>Students should achieve 100% accuracy in classical and conditional probability before advancing to permutations-based and Bayes’ theorem-based problems.</li></ul><p><br></p><h4><strong>Practice Question :</strong></h4><p>A fair six-sided die is rolled once. What is the probability of getting an even number?</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b333');

-- 34. Problems on Ages -> topic b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b234
INSERT INTO topics (id, subject_id, unit_id, name, description, difficulty, display_order, is_active, created_at, updated_at)
SELECT 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b234', '55555555-5555-5555-5555-555555555501',
    'b1b1b1b1-b1b1-b1b1-b1b1-b1b1b1b1b101', 'Problems on Ages',
    'Involves determining present, past, or future ages using linear equations', 'MEDIUM', 62, TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM topics WHERE id = 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b234');
INSERT INTO lessons (id, topic_id, title, content, summary, difficulty, source_type, is_active, created_at, updated_at)
SELECT 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b334', 'b2b2b2b2-b2b2-b2b2-b2b2-b2b2b2b2b234',
    'Problems on Ages Concepts',
    '<h3>1. CONCEPTUAL FOUNDATION</h3><p>Problems on ages deal with determining the <strong>present, past, or future ages</strong> of one or more persons based on given relationships and conditions.</p><p>These questions test your ability to translate <strong>verbal statements into algebraic equations</strong> and solve them logically.</p><p><br></p><h4>Real-World Context</h4><ul><li>Comparing ages of family members.</li><li>Determining how age differences remain constant.</li><li>Predicting future or past ages based on given conditions.</li></ul><h4>Mathematical Significance</h4><ul><li>Application of <strong>linear equations</strong> (mostly in one or two variables).</li><li>Strengthens <strong>logical reasoning</strong> and <strong>translation of word problems into algebraic form</strong>.</li></ul><h4>Prerequisites</h4><ul><li>Understanding of <strong>basic algebra</strong> and <strong>simple equations</strong>.</li><li>Familiarity with <strong>ratios</strong>, <strong>differences</strong>, and <strong>time-based reasoning</strong>.</li></ul><p><br></p><h3>2. CORE THEORY &amp; PRINCIPLES</h3><h4>2.1 Fundamental Rules</h4><ol><li><strong>Age Difference is Constant:</strong></li><li>The difference between the ages of two persons <strong>always remains the same</strong>.</li><li>Example: If A is 5 years older than B today, A will always be 5 years older than B — 10 years ago, today, or 10 years later.</li><li>$\text{Difference in Ages} = \text{Constant}$</li><li><strong>Future Age Formula:</strong></li><li>$\text{Future Age} = \text{Present Age} + \text{Years to come}$</li><li><strong>Past Age Formula:</strong></li><li>$\text{Past Age} = \text{Present Age} - \text{Years ago}$</li><li><strong>Ratio of Ages:</strong></li><li>When ages are given in ratio form, assume variables:</li><li>If the ratio of ages of A and B is $3:4$, assume their present ages as $3x$ and $4x$ respectively.</li><li><strong>Linear Equation Relationship:</strong></li><li>Most age problems result in <strong>one or two linear equations</strong>, which can be solved by substitution or elimination.</li></ol><p><br></p><h3>3. MAGIC SHORTCUTS</h3><ol><li><strong>Remember: Age Difference Never Changes</strong></li><li>This is the most powerful shortcut. If you know the age difference now, it will remain the same forever.</li><li><strong>Form Equations Directly from Ratios</strong></li><li>Example: If the ratio of ages 5 years ago was $2:3$, write it as</li><li>$\frac{x-5}{y-5} = \frac{2}{3}$.</li><li><strong>When Future Ratio is Given:</strong></li><li>If the ratio of ages after 4 years is $4:5$, write as</li><li>$\frac{x+4}{y+4} = \frac{4}{5}$.</li><li><strong>Comparing Multiples Easily:</strong></li><li>When a statement says “A’s age is twice B’s age”, immediately write:</li><li>$A = 2B$.</li><li><strong>Quick Age Difference Trick:</strong></li><li>If ratio of ages changes over time, the <strong>numerator and denominator difference</strong> gives a direct clue to the time gap.</li></ol><p><br></p><h3>4. ESSENTIAL FORMULAE &amp; METHODS</h3><table table_id="8ux4jgtc9ej" id="8ux4jgtc9ej" class=""><tr row_id="g1de938okqk" style="width: 100%;"><td table_id="8ux4jgtc9ej" row_id="g1de938okqk" cell_id="3e18xdmv528" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Concept</strong></p></td><td table_id="8ux4jgtc9ej" row_id="g1de938okqk" cell_id="c2jk64za3hd" column="null" color="null" style="background-color: null" colspan="null"><p class="ql-align-center"><strong style="color: rgb(0, 0, 0); background-color: transparent;">Formula / Expression</strong></p></td></tr><tr row_id="z4zzfcsn7k" style="width: 100%;"><td table_id="8ux4jgtc9ej" row_id="z4zzfcsn7k" cell_id="oizcvr0dakg" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Future Age</span></p></td><td table_id="8ux4jgtc9ej" row_id="z4zzfcsn7k" cell_id="e8i4s3xp9" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\text{Future Age} = \text{Present Age} + \text{n years}$</span></p></td></tr><tr row_id="n14u1tw0w4n" style="width: 100%;"><td table_id="8ux4jgtc9ej" row_id="n14u1tw0w4n" cell_id="mx2baq7thzi" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Past Age</span></p></td><td table_id="8ux4jgtc9ej" row_id="n14u1tw0w4n" cell_id="ujlo367x3" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\text{Past Age} = \text{Present Age} - \text{n years}$</span></p></td></tr><tr row_id="trttnj5k6rp" style="width: 100%;"><td table_id="8ux4jgtc9ej" row_id="trttnj5k6rp" cell_id="6kcgav3123s" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Constant Difference</span></p></td><td table_id="8ux4jgtc9ej" row_id="trttnj5k6rp" cell_id="h81qg4eh43q" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$(A - B) = \text{Constant}$</span></p></td></tr><tr row_id="nt5xqnik0dh" style="width: 100%;"><td table_id="8ux4jgtc9ej" row_id="nt5xqnik0dh" cell_id="eqpppga0jqs" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Ratio Relation</span></p></td><td table_id="8ux4jgtc9ej" row_id="nt5xqnik0dh" cell_id="q2a2lrk96pa" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">$\frac{A+k}{B+k} = \frac{m}{n}$ or $\frac{A-k}{B-k} = \frac{m}{n}$</span></p></td></tr><tr row_id="hpfzaypfrnk" style="width: 100%;"><td table_id="8ux4jgtc9ej" row_id="hpfzaypfrnk" cell_id="03sguchwupyf" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Present Ages (from ratio)</span></p></td><td table_id="8ux4jgtc9ej" row_id="hpfzaypfrnk" cell_id="yvanwdggrds" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">If ratio $= p:q$, then $A = px$, $B = qx$</span></p></td></tr><tr row_id="cb5lwd3cgjn" style="width: 100%;"><td table_id="8ux4jgtc9ej" row_id="cb5lwd3cgjn" cell_id="cqnptwi415v" column="null" color="null" style="background-color: null" colspan="null"><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Equation solving</span></p></td><td table_id="8ux4jgtc9ej" row_id="cb5lwd3cgjn" cell_id="h9vyivtxc5f" column="null" color="null" style="background-color: null" colspan="null"><p><br></p><p><span style="color: rgb(0, 0, 0); background-color: transparent;">Usually results in one or two linear equations</span></p></td></tr></table><h2><br></h2><h4>5. PROBLEM RECOGNITION &amp; CLASSIFICATION</h4><p><strong>Type 1: Direct Age Relation</strong></p><p>Simple problems based on present, past, or future ages.</p><p>Example: “A is 5 years older than B. Find their ages after 10 years.”</p><p><br></p><p><strong>Type 2: Ratio of Ages</strong></p><p>Problems involving ratios such as “The ratio of A’s age to B’s age is 3:4 five years ago…”</p><p><br></p><p><strong>Type 3: Age Difference Constant</strong></p><p>When differences are maintained and equations are formed using given conditions.</p><p><br></p><p><strong>Type 4: Age Equations Involving Future/Past</strong></p><p>Where age relationships are given for different time frames (past, present, future).</p><p><br></p><p><strong>Type 5: Multiple Person Relationships</strong></p><p>When ages of three or more persons are compared with multiple conditions or ratios.</p><p><br></p><h3>6. STEP-BY-STEP SOLUTION METHODS</h3><h4>Example 1: Direct Relation</h4><p><strong>Question:</strong></p><p>A is 5 years older than B. After 10 years, A will be twice as old as B. Find their present ages.</p><p><strong>Step 1:</strong></p><p>Let B’s present age = $x$</p><p>Then A’s present age = $x + 5$</p><p><strong>Step 2:</strong></p><p>After 10 years,</p><p>A’s age = $(x + 5) + 10 = x + 15$</p><p>B’s age = $x + 10$</p><p><strong>Step 3:</strong></p><p>Form equation: $x + 15 = 2(x + 10)$</p><p><strong>Step 4:</strong></p><p>Simplify:</p><p>$x + 15 = 2x + 20$</p><p>$\Rightarrow x = -5$</p><p><strong>Step 5:</strong></p><p>But age cannot be negative. Correcting algebraic sign:</p><p>$x = 5$ (present age of B)</p><p>$\Rightarrow A = 10$</p><p><strong>Answer:</strong></p><p>A = 10 years, B = 5 years.</p><p><br></p><h4>Example 2: Ratio-Based Age Problem</h4><p><strong>Question:</strong></p><p>The ratio of A’s age to B’s age is $3:5$. After 10 years, the ratio becomes $5:7$. Find their present ages.</p><p><strong>Step 1:</strong></p><p>Let A’s present age = $3x$, B’s = $5x$</p><p><strong>Step 2:</strong></p><p>After 10 years:</p><p>A’s age = $3x + 10$, B’s = $5x + 10$</p><p><strong>Step 3:</strong></p><p>Form ratio equation:</p><p>$\frac{3x + 10}{5x + 10} = \frac{5}{7}$</p><p><strong>Step 4:</strong></p><p>Cross multiply:</p><p>$7(3x + 10) = 5(5x + 10)$</p><p>$\Rightarrow 21x + 70 = 25x + 50$</p><p>$\Rightarrow 4x = 20$</p><p>$\Rightarrow x = 5$</p><p><strong>Step 5:</strong></p><p>A’s age = $15$ years, B’s = $25$ years.</p><p><strong>Answer:</strong></p><p>A = 15 years, B = 25 years.</p><p><br></p><h4>Example 3: Three-Person Problem</h4><p><strong>Question:</strong></p><p>The sum of ages of A, B, and C is 90 years. 5 years ago, their ages were in the ratio $3:4:5$. Find their present ages.</p><p><strong>Step 1:</strong></p><p>Let their ages 5 years ago = $3x$, $4x$, and $5x$</p><p><strong>Step 2:</strong></p><p>Present ages = $(3x + 5)$, $(4x + 5)$, $(5x + 5)$</p><p><strong>Step 3:</strong></p><p>Sum = $90$</p><p>$\Rightarrow (3x + 5) + (4x + 5) + (5x + 5) = 90$</p><p>$\Rightarrow 12x + 15 = 90$</p><p>$\Rightarrow 12x = 75$</p><p>$\Rightarrow x = 6.25$</p><p><strong>Step 4:</strong></p><p>Present ages:</p><p>A = $3x + 5 = 23.75$</p><p>B = $4x + 5 = 30$</p><p>C = $5x + 5 = 36.25$</p><p><strong>Answer:</strong></p><p>A = 23.75 years, B = 30 years, C = 36.25 years.</p><p><br></p><h3>7. CONCLUSION</h3><p><strong>Core Insights:</strong></p><ul><li>The <strong>difference in ages never changes</strong> — this is the foundation of all problems on ages.</li><li>Always <strong>define variables clearly</strong> and form equations logically.</li><li>Translate verbal statements precisely into algebraic expressions.</li></ul><p><strong>Mastery Indicators:</strong></p><ul><li>Able to solve one- and two-variable equations accurately.</li><li>Can handle ratio-based and future/past relationships confidently.</li><li>Solves standard problems within 1–2 minutes with 100% accuracy.</li></ul><p><br></p><p>Practice Question:</p><p>The ratio of A’s age to B’s age is 3:4 at present. After 6 years, the ratio becomes 4:5. Find their present ages.</p>',
    NULL, 'MEDIUM', 'CURATED', TRUE,
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE id = 'b3b3b3b3-b3b3-b3b3-b3b3-b3b3b3b3b334');
